window.HOLUS_DATA=window.HOLUS_DATA||{};window.HOLUS_DATA["nc"]={"id":"nc","num":5,"name":"Nutritional Counselling","area":"Counselling practice","lessons":[{"n":1,"title":"Nutrition Basics","kicker":"Lesson 1 of your course, built from Chapter 1 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l1-b1","chapter":"Ten ideas that run through the course","title":"Ten ideas that run through the course","teach":["Chapter 1 sets out ten nutrition principles that come up again at every life stage. Food is a basic human need. Food supplies energy, nutrients and other substances we need to grow and stay healthy. Nutrition problems start inside cells. Too little and too much of a nutrient can both cause harm, and the body has ways of coping with ups and downs in intake.","Malnutrition can come from a poor diet, from disease or genes, or from a mix of these. Some groups are at higher risk than others. Poor nutrition can help set up chronic disease. Healthy eating patterns are built on adequacy, variety and balance. And no single food is simply good or bad: what matters is how it fits into the whole diet."],"act":{"type":"choice","prompt":"A very active teenager who has already eaten well today has ice cream after practice. How does the chapter see this?","options":[{"label":"Ice cream is a bad food, so it should be avoided.","correct":false,"feedback":"The chapter's tenth principle is that there are no good or bad foods. It depends on the whole diet."},{"label":"It can fit well, because her nutrient needs are met and she needs the extra energy.","correct":true,"feedback":"Yes. The same food can fit one person's diet and not another's."},{"label":"Only foods labelled healthy should count toward her diet.","correct":false,"feedback":"Labels don't decide this. What matters is adequacy, variety and balance across the day."}]}},{"id":"l1-b2","chapter":"Nutrient intake standards","title":"Nutrient intake standards","teach":["The Dietary Reference Intakes (DRIs) are a set of standards. The Estimated Average Requirement (EAR) is the intake that meets the needs of half the healthy people in a group. It is used to judge whether a group's intake is adequate. The Recommended Dietary Allowance (RDA) is set higher, to cover nearly all healthy people (about 97–98%).","When there isn't enough evidence to set an RDA, an Adequate Intake (AI) is used. The Tolerable Upper Intake Level (UL) is the highest daily intake unlikely to cause harm. It is a safety limit, not a target. Nutrition labels use a separate set of reference amounts called Daily Values, and the % DV tells you how much of that amount one serving gives."],"act":{"type":"sort","prompt":"Match each standard with what it means.","categories":["EAR","RDA","AI","UL"],"items":[{"label":"Meets the needs of half the healthy people in a group","category":0,"feedback":"That is the Estimated Average Requirement."},{"label":"Covers nearly all healthy people","category":1,"feedback":"The RDA is set above the EAR to cover almost everyone."},{"label":"Used when there isn't enough evidence for an RDA","category":2,"feedback":"That is the Adequate Intake."},{"label":"Highest intake unlikely to cause harm","category":3,"feedback":"The Tolerable Upper Intake Level is a safety limit, not a goal."}]}},{"id":"l1-b3","chapter":"Counting calories from macronutrients","title":"Counting calories from macronutrients","teach":["Carbohydrate and protein give 4 Calories per gram, and fat gives 9. (Fibre gives about 2, and alcohol 7.) To find the Calories in a food, multiply the grams of each by its factor and add them up.","To find the share of Calories from one nutrient, divide its Calories by the total and multiply by 100. For adults, the Acceptable Macronutrient Distribution Ranges are 45–65% of Calories from carbohydrate, 10–35% from protein and 20–35% from fat. Sucrose (table sugar) is made of glucose and fructose."],"act":{"type":"number","prompt":"A snack has 30 g carbohydrate, 10 g protein and 10 g fat. How many Calories does it provide?","answer":250,"tolerance":0,"unit":"Calories","explanation":"30 × 4 = 120, 10 × 4 = 40 and 10 × 9 = 90. 120 + 40 + 90 = 250 Calories."}},{"id":"l1-b4","chapter":"Vitamins","title":"Vitamins","teach":["The B-complex vitamins and vitamin C dissolve in water. Vitamins A, D, E and K dissolve in fat (think DEKA). Apart from vitamin B12, the body's stores of water-soluble vitamins are small and run out within weeks to months when intake drops. Fat-soluble vitamins are stored in fat tissue, so a deficiency takes longer to show.","Vitamins C and E and beta-carotene (which the body turns into vitamin A) act as antioxidants. They help prevent or repair damage to cells from oxidation. Large doses from supplements, especially of vitamins A and D, can be toxic. Overdoses from food alone are very rare."],"act":{"type":"sort","prompt":"Sort each vitamin by how it dissolves.","categories":["Water-soluble","Fat-soluble"],"items":[{"label":"Vitamin C","category":0,"feedback":"Vitamin C dissolves in water."},{"label":"Thiamin (a B vitamin)","category":0,"feedback":"All the B-complex vitamins are water-soluble."},{"label":"Vitamin D","category":1,"feedback":"D is one of the fat-soluble vitamins: D, E, K and A."},{"label":"Vitamin K","category":1,"feedback":"K is fat-soluble and stored in body fat."}]}},{"id":"l1-b5","chapter":"Minerals, phytochemicals and water","title":"Minerals, phytochemicals and water","teach":["Minerals tend to bind with other substances, such as other minerals in supplements or fibre in food. Bound minerals can't be absorbed, so overall we absorb a smaller share of the minerals we eat than of the vitamins. Phytochemicals are substances in plants that aren't nutrients but may protect body processes and benefit health.","Adults are about 60–70% water. Water is the medium where most of the body's chemical reactions happen. It also plays a part in energy transformation, getting rid of wastes and controlling body temperature. Pale yellow urine in normal amounts is a sign of enough fluid."],"act":{"type":"choice","prompt":"Which of these is NOT a role of water described in the chapter?","options":[{"label":"Temperature regulation","correct":false,"feedback":"Controlling body temperature is one of water's roles."},{"label":"Excretion of wastes","correct":false,"feedback":"Water helps the body get rid of wastes."},{"label":"Regulating hunger hormones","correct":true,"feedback":"Right. The chapter lists reactions, energy transformation, waste removal and temperature control, but not this."}]}},{"id":"l1-b6","chapter":"Nutrient density and malnutrition","title":"Nutrient density and malnutrition","teach":["Nutrient-dense foods give plenty of nutrients for relatively few Calories. Examples are nonfat milk and yogurt, lean meat, dried beans, vegetables and fruit. Empty-calorie foods, like soft drinks and hard candy, give Calories with few nutrients. A diet made mostly of nutrient-dense foods is more likely to meet nutrient needs without going over energy needs.","Primary malnutrition comes from the diet itself, for example not having enough money for food. Secondary malnutrition is caused by a disease, surgery or medication that affects how the body uses nutrients."],"act":{"type":"sort","prompt":"Is each situation an example of primary or secondary malnutrition?","categories":["Primary (diet)","Secondary (disease, surgery or medication)"],"items":[{"label":"A family can't afford enough food at the end of the month.","category":0,"feedback":"The poor nutrition comes from the diet itself."},{"label":"Ongoing diarrhea keeps a person from absorbing nutrients.","category":1,"feedback":"A health condition causes the problem, so it is secondary."},{"label":"A student lives mostly on soft drinks and chips.","category":0,"feedback":"The cause is what she eats."},{"label":"Bleeding in the digestive tract leads to low iron.","category":1,"feedback":"The cause is a condition, not the diet."}]}},{"id":"l1-b7","chapter":"Reading labels and claims","title":"Reading labels and claims","teach":["Almost all foods with more than one ingredient must have a Nutrition Facts panel. The panel shows the serving size, nutrients such as fat, saturated fat, trans fat, cholesterol, sodium, carbohydrate, fibre, sugars and protein, and a % DV column. Labels also flag common allergens. The textbook uses the older U.S. label, on which vitamins A and C, calcium and iron were mandatory.","Enriched refined grains such as bread, cornmeal, crackers, flour tortillas and white rice must have thiamin, riboflavin, niacin and iron added back. Supplements have a Supplement Facts panel. They don't have to be proven safe and effective before they are sold, so their labels can't claim to treat, cure or prevent a disease."],"act":{"type":"choice","prompt":"Which claim would NOT be allowed on a supplement label?","options":[{"label":"“A good source of fibre”","correct":false,"feedback":"Standard nutrient content claims like this are allowed."},{"label":"“Cures joint pain”","correct":true,"feedback":"Right. Supplements can't claim to treat, cure or prevent a disease."},{"label":"“Calcium builds strong bones”","correct":false,"feedback":"Claims about how a nutrient supports the body are allowed."}]}},{"id":"l1-b8","chapter":"The life course and nutrition assessment","title":"The life course and nutrition assessment","teach":["Nutrition at one life stage affects health at the next. Poor nutrition in pregnancy can shape gene function for life, and iron deficiency in young children can affect learning later on. Everyone needs the same nutrients throughout life, but the amounts change with age, growth and development. There is no single best diet for everyone.","Assessing a person's nutrition has four parts: clinical (physical), dietary, anthropometric (body measurements) and biochemical (lab tests). You need all four. One measure, like normal weight or good iron levels, doesn't prove someone is well nourished."],"act":{"type":"sort","prompt":"Match each finding with the part of nutrition assessment it belongs to.","categories":["Clinical / physical","Dietary","Anthropometric","Biochemical"],"items":[{"label":"Pale skin and brittle nails noted during an exam","category":0,"feedback":"Physical signs are part of the clinical assessment."},{"label":"A 24-hour recall of everything eaten yesterday","category":1,"feedback":"Recalls and food records assess diet."},{"label":"Height, weight and waist measurement","category":2,"feedback":"Body measurements are anthropometric."},{"label":"Blood iron levels","category":3,"feedback":"Lab values are biochemical."}]}}],"flashcards":[{"front":"Estimated Average Requirement (EAR)","back":"The intake that meets the needs of half the healthy people in a group."},{"front":"Recommended Dietary Allowance (RDA)","back":"The intake that meets the needs of nearly all healthy people (about 97–98%)."},{"front":"Adequate Intake (AI)","back":"Used when there isn't enough evidence to set an EAR and RDA."},{"front":"Tolerable Upper Intake Level (UL)","back":"The highest daily intake unlikely to cause harm. A safety limit, not a target."},{"front":"Calories per gram","back":"Carbohydrate 4, protein 4, fat 9 (fibre about 2, alcohol 7)."},{"front":"Adult AMDRs","back":"Carbohydrate 45–65%, protein 10–35%, fat 20–35% of Calories."},{"front":"Sucrose","back":"Table sugar, made of glucose and fructose."},{"front":"Water-soluble vitamins","back":"The B-complex vitamins and vitamin C."},{"front":"Fat-soluble vitamins","back":"Vitamins A, D, E and K (DEKA). Stored in body fat, so deficiency is slower to appear."},{"front":"Antioxidant vitamins","back":"Vitamin C, vitamin E and beta-carotene."},{"front":"Phytochemicals","back":"Substances in plants that may protect body processes and benefit health."},{"front":"Nutrient-dense foods","back":"Foods with lots of nutrients and relatively few Calories."},{"front":"Primary vs. secondary malnutrition","back":"Primary comes from the diet. Secondary is caused by a disease, surgery or medication."},{"front":"Enriched grains must include…","back":"Thiamin, riboflavin, niacin and iron."},{"front":"Four parts of nutrition assessment","back":"Clinical/physical, dietary, anthropometric and biochemical."},{"front":"Roles of water","back":"Medium for chemical reactions, energy transformation, waste removal and temperature control."}],"quiz":[{"q":"The Estimated Average Requirement (EAR) means:","o":["an intake level that meets the nutrient needs of 98% of healthy people.","an intake value that meets the nutrient needs of half the healthy individuals in a group.","the upper limits of a nutrient compatible with health.","the nutrient intake standard for healthy people.","that this is a “tentative” RDA."],"a":1,"e":"Checked answer, not from an official key. Chapter 1 defines the EAR as meeting the needs of half the healthy people in a group."},{"q":"What two monosaccharides are found in sucrose (table sugar)?","o":["Glucose and lactose","Glucose and glucose","Glucose and maltose","Glucose and fructose"],"a":3,"e":"Checked answer, not from an official key. Sucrose is glucose joined to fructose."},{"q":"Which of the following statements about food labels is FALSE?","o":["They note the presence of common food allergens.","They appear on almost all multiple-ingredient foods.","They list the content of fat, saturated fat, trans fat, and cholesterol.","They contain information about the amount recommended for ingestion each day.","They list the % Daily Value (%DV) for each relevant nutrient."],"a":3,"e":"Checked answer, not from an official key. Labels show amounts per serving and % DV, which is a general reference, not a recommended amount for you to eat each day."},{"q":"Producers of bread, cornmeal, crackers, flour tortillas, white rice, and other products made with refined grains MUST use flours enriched with which of the following?","o":["Thiamin","Niacin","Iron","Riboflavin","All of the above"],"a":4,"e":"Checked answer, not from an official key. By law, enriched flour must have thiamin, riboflavin, niacin and iron added."},{"q":"What mandatory nutrient is missing from the food label? (Refers to the label in your test.)","o":["Unsaturated fats","Simple sugars","Vitamin C","Vitamin K"],"a":2,"e":"Checked answer, not from an official key. On the older label used in the textbook, vitamin C was mandatory. The other choices weren't required."},{"q":"Does this product fall within the Acceptable Macronutrient Distribution Range for fat? (The label in your test shows 170 Calories per serving, 45 from fat.)","o":["Yes","No"],"a":0,"e":"Checked answer, not from an official key. 45 ÷ 170 × 100 is about 26%, which is within the adult fat range of 20–35%."},{"q":"After class, you go to Jamba Juice and get an “Orange-a-Peel” smoothie that contains the following nutrients: 9 g of protein, 102 g carbohydrate, and 1 g of fat. How many total Calories does this provide?","o":["299","399","448","453","546"],"a":3,"e":"Checked answer, not from an official key. 9 × 4 = 36, 102 × 4 = 408 and 1 × 9 = 9. 36 + 408 + 9 = 453."},{"q":"A woman ate 1/2 of a pita bread sandwich filled with tuna salad. The entire sandwich contained 20 grams carbohydrate, 8 grams protein, and 5 grams fat. Approximately how many calories did she obtain?","o":["80","130","150","160"],"a":0,"e":"Checked answer, not from an official key. The whole sandwich is 80 + 32 + 45 = 157 Calories. Half is about 79, so about 80."},{"q":"If the woman in question #8 drank a glass of regular, fortified milk, what is the most important essential nutrient that she added to her diet?","o":["Calcium","Cholesterol","Fluoride","Glucose","Vitamin C"],"a":0,"e":"Checked answer, not from an official key. Milk is a major source of calcium."},{"q":"What nutrient would someone susceptible to high blood pressure be consuming too much of with a meal consisting of a salami sandwich, chicken noodle soup, and whole milk?","o":["Sugar","Caffeine","Sodium","Water","Calcium"],"a":2,"e":"Checked answer, not from an official key. Salami and canned or packaged soup are high in sodium."},{"q":"Phytochemicals are chemical substances found in _____ that protect human body processes and may benefit health.","o":["animals","the human body","plants","both plants and animals","None of the above"],"a":2,"e":"Checked answer, not from an official key. “Phyto” means plant. These substances come from plants."},{"q":"Which of the following vitamins acts as an antioxidant in the body?","o":["Vitamin C","Vitamin E","Beta-carotene","All of the above","a and b only"],"a":3,"e":"Checked answer, not from an official key. The textbook names vitamins C and E and beta-carotene as antioxidants."},{"q":"Which of the following is NOT one of the roles that water plays in the body?","o":["Energy transformation","Energy metabolism regulation","Excretion of wastes","Temperature regulation","Medium in which most chemical reactions take place"],"a":1,"e":"Checked answer, not from an official key. The textbook lists every other choice as a role of water."},{"q":"Nutrient-dense foods can be defined as:","o":["foods that are both good sources of nutrients and low in Calories.","foods that contain low amounts of nutrients and are high in Calories.","foods that are both good sources of nutrients and high in Calories.","foods that contain low amounts of nutrients and are low in Calories.","all animal-derived foods."],"a":0,"e":"Checked answer, not from an official key. Nutrient-dense foods have lots of nutrients for relatively few Calories."},{"q":"Which of the following would NOT be considered one of the four components of nutrition assessment?","o":["Anthropometric","Biochemical","Clinical/physical","Initial evaluation","Dietary"],"a":3,"e":"Checked answer, not from an official key. The four parts are clinical/physical, dietary, anthropometric and biochemical."},{"q":"Jill is a very active teenager who has been maintaining her current weight of 125 pounds. Her average daily macronutrient intake consists of 250 g carbohydrate, 100 g total fat, 30 g saturated fat, and 50 g protein.\n\nHow many Calories from carbohydrates is Jill consuming daily?","o":["750","1000","1750","2250"],"a":1,"e":"Checked answer, not from an official key. 250 g × 4 = 1,000 Calories."},{"q":"Jill is a very active teenager who has been maintaining her current weight of 125 pounds. Her average daily macronutrient intake consists of 250 g carbohydrate, 100 g total fat, 30 g saturated fat, and 50 g protein.\n\nThe percentage of energy that comes from Jill’s intake of carbohydrate is:","o":["12%.","25%.","48%.","57%.","65%."],"a":2,"e":"Checked answer, not from an official key. Her total is 1,000 + 900 + 200 = 2,100 Calories. 1,000 ÷ 2,100 × 100 is about 48%."},{"q":"Jill is a very active teenager who has been maintaining her current weight of 125 pounds. Her average daily macronutrient intake consists of 250 g carbohydrate, 100 g total fat, 30 g saturated fat, and 50 g protein.\n\nThe percentage of energy that comes from Jill’s intake of fat is:","o":["13%.","30%.","43%.","56%."],"a":2,"e":"Checked answer, not from an official key. 100 g × 9 = 900 Calories. 900 ÷ 2,100 × 100 is about 43%."},{"q":"Good food sources of antioxidants would include which of the following foods?","o":["Bananas, raisins, figs","Oranges, sweet potatoes, bell peppers","Spinach, blueberries, cranberries","All of the above","b and c only"],"a":4,"e":"Checked answer, not from an official key. Less certain: the foods in b and c are the ones the textbook lists as rich in antioxidant vitamins, but raisins and figs also contain some antioxidants, so check this one against your graded result."},{"q":"Which of the following would NOT be an example of an approved dietary supplement claim?","o":["Calcium builds strong bones","Calcium prevents bone fracture","Vitamin E, an antioxidant, helps maintain cell membranes","XYZ helps promote urinary tract health","XYZ gives you energy and focus throughout your busy day"],"a":1,"e":"Checked answer, not from an official key. Supplement labels can't claim to prevent a disease or condition, such as a fracture."},{"q":"The water-soluble vitamins include:","o":["A, D, E, and K.","A and C.","B-complex and C.","B-complex and K.","All vitamins are water soluble."],"a":2,"e":"Checked answer, not from an official key. The B-complex vitamins and vitamin C dissolve in water."},{"q":"A diet low in fat-soluble vitamins will result in a more rapid onset of deficiency symptoms than one low in water-soluble vitamins.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Fat-soluble vitamins are stored in body fat, while most water-soluble vitamin stores run out within weeks to months, so it's the other way around."},{"q":"Typically, we absorb a greater percentage of minerals than vitamins.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Minerals often bind to other substances and can't be absorbed, so we absorb a smaller share of minerals than vitamins."},{"q":"Not having enough money to buy food to eat is an example of a potential cause of primary malnutrition.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Primary malnutrition comes from the diet itself."},{"q":"What food serving below does NOT provide significant amounts of iron?","o":["Round steak, 3 oz","Pork and beans, 1/2 cup","Peaches, 1/2 cup","Iron-fortified breakfast cereal, 1 cup"],"a":2,"e":"Checked answer, not from an official key. Less certain: meat, beans and fortified cereal are well-known iron sources, and peaches have very little, but check this one against your graded result."}]},{"n":2,"title":"Preconception Nutrition","kicker":"Lesson 2 of your course, built from Chapters 2 and 3 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l2-b1","chapter":"Getting pregnant isn't a sure thing","title":"Getting pregnant isn't a sure thing","teach":["Many conceptions never become a pregnancy anyone knows about. About 30–50% are lost in the first six weeks, and another 9% end in miscarriage in the first 20 weeks. The most common known cause of miscarriage is a severe defect in the fetus. Others include infection in the mother, problems with the shape of the uterus, hormone or immune problems, and random events.","Couples are called subfertile when the woman has had several miscarriages, the man has sperm problems such as a low count or poorly moving sperm, or the woman ovulates only now and then. About 18% of married couples in the U.S. are subfertile. Nutrition is one of the things that can help or hurt fertility."],"act":{"type":"choice","prompt":"Which of these would be described as subfertile?","options":[{"label":"A woman who ovulates only a few times a year","correct":true,"feedback":"Yes. Ovulating infrequently is one of the signs of subfertility."},{"label":"A woman who has just reached menopause","correct":false,"feedback":"Menopause ends fertility. Subfertility means reduced, not absent, fertility."},{"label":"A couple who conceived in their third month of trying","correct":false,"feedback":"Subfertility is usually defined as more than 12 months to conceive, or repeated losses."}]}},{"id":"l2-b2","chapter":"Hormones and the menstrual cycle","title":"Hormones and the menstrual cycle","teach":["A typical cycle is about 28 days and starts on the first day of bleeding. The first half is the follicular phase, and the last 14 days are the luteal phase. Early in the cycle, the pituitary gland releases follicle-stimulating hormone (FSH) and luteinizing hormone (LH). FSH helps eggs mature in the ovary.","Just before ovulation, usually on day 14, FSH and LH peak. The surge of LH releases the egg. If there is no pregnancy, the uterus makes prostaglandins, which make it contract and shed its lining. Prostaglandins are behind cramps and other side effects of menstruation."],"act":{"type":"sort","prompt":"Match each hormone or substance with what it does.","categories":["FSH","LH","Prostaglandins"],"items":[{"label":"Helps eggs mature in the ovary","category":0,"feedback":"Follicle-stimulating hormone drives follicle growth."},{"label":"Its surge on about day 14 triggers ovulation","category":1,"feedback":"The LH surge releases the egg."},{"label":"Makes the uterus contract, causing cramps","category":2,"feedback":"Prostaglandins from the uterus cause menstrual cramps."}]}},{"id":"l2-b3","chapter":"Body fat and fertility","title":"Body fat and fertility","teach":["Both too much and too little body fat can lower fertility in women and men. Fat cells make estrogen, testosterone and leptin, and these hormones affect egg development, ovulation and sperm. In people with obesity, losing body fat improves hormone levels, oxidative stress, inflammation and conception rates.","In normal-weight women, losing more than about 10–15% of usual weight lowers estrogen, LH and FSH. Periods can stop, ovulation can stop, and the luteal phase can become short or disappear. This is called functional hypothalamic amenorrhea, and hormone levels usually recover once weight is back to within 95% of before. Being underweight in pregnancy raises the risk of complications for the mother and of small, early babies. Young female athletes and dancers often start their periods 2–4 years later than average."],"act":{"type":"choice","prompt":"Which hormone is NOT made by fat cells?","options":[{"label":"Estrogen","correct":false,"feedback":"Fat cells do make estrogen."},{"label":"Leptin","correct":false,"feedback":"Leptin is made by fat cells."},{"label":"Insulin","correct":true,"feedback":"Right. Insulin comes from the pancreas. Fat cells make estrogen, testosterone and leptin."}]}},{"id":"l2-b4","chapter":"Folate and iron before pregnancy","title":"Folate and iron before pregnancy","teach":["All women who could become pregnant are advised to get 400 mcg of folic acid a day from fortified foods or a supplement. Good folate status around conception lowers the risk of neural tube defects such as spina bifida. One serving of a breakfast cereal fortified with 400 mcg of folic acid covers it. Gluten-free grain products may not be fortified, so check the label.","Iron status before pregnancy matters too. Low iron stores going into pregnancy are linked to poorer outcomes, and they are hard to build up once pregnancy starts."],"act":{"type":"choice","prompt":"How much folic acid a day is recommended for every woman who could become pregnant?","options":[{"label":"40 mcg","correct":false,"feedback":"That's ten times too little."},{"label":"400 mcg","correct":true,"feedback":"Yes, 400 micrograms a day from fortified foods or a supplement."},{"label":"400 mg","correct":false,"feedback":"Watch the units. The amount is 400 micrograms (mcg), not milligrams."}]}},{"id":"l2-b5","chapter":"What can throw fertility off","title":"What can throw fertility off","teach":["Conditions that affect fertility usually work through one of four routes. They change the hormones that control ovulation, change the presence or length of the luteal phase, reduce sperm production, or affect the tubes that eggs and sperm must travel through. An infection that scars the tubes is an example of the last one.","Hormonal birth control can also have nutrition side effects. Combination pills tend to lower HDL cholesterol and raise LDL cholesterol, triglycerides, blood glucose and insulin a little."],"act":{"type":"choice","prompt":"Which of these is NOT one of the ways hormone changes affect fertility, according to the chapter?","options":[{"label":"A short or missing luteal phase","correct":false,"feedback":"The textbook lists this as one of the effects."},{"label":"Lower sperm production","correct":false,"feedback":"Reduced sperm production is one of the routes."},{"label":"No follicular phase","correct":true,"feedback":"Right. The chapter talks about the luteal phase, ovulation, sperm and the passageways, not losing the follicular phase."}]}},{"id":"l2-b6","chapter":"Central body fat and metabolic syndrome","title":"Central body fat and metabolic syndrome","teach":["Fat stored deep in the abdomen is linked to insulin resistance, high insulin, inflammation, oxidative stress and metabolic syndrome. In women, high insulin leads the ovaries to make more testosterone, which disrupts egg development. Polycystic ovary syndrome (PCOS) often comes with high abdominal fat, even in normal-weight women.","Metabolic syndrome is a cluster of risk factors, not one disease. It is diagnosed when three of these five are present: waist over 40 inches in men or 35 inches in women, triglycerides of 150 mg/dL or more, HDL cholesterol under 40 mg/dL in men or 50 mg/dL in women, blood pressure of 130/85 or more, and fasting blood glucose of 100 mg/dL or more."],"act":{"type":"number","prompt":"A woman has a 37-inch waist, triglycerides of 160 mg/dL, HDL of 55 mg/dL, blood pressure of 118/76 and fasting glucose of 104 mg/dL. How many of the five criteria does she meet?","answer":3,"tolerance":0,"unit":"criteria","explanation":"Waist (over 35), triglycerides (150 or more) and fasting glucose (100 or more) count. Her HDL and blood pressure are fine. Three criteria means she would be diagnosed with metabolic syndrome."}},{"id":"l2-b7","chapter":"Diabetes and PKU before pregnancy","title":"Diabetes and PKU before pregnancy","teach":["High blood glucose in the first two months of pregnancy is teratogenic: it raises the risk of birth defects two- to three-fold and also raises the risk of miscarriage. Good glucose control before conception helps. Low-glycemic-index foods and plenty of fibre, about 14 g per 1,000 Calories, help keep blood glucose steady.","Phenylketonuria (PKU) is an inherited condition in which the body can't break down the amino acid phenylalanine. High phenylalanine early in pregnancy harms the baby's brain development and raises the risk of heart defects. Untreated, there is a 92% chance of intellectual disability and a 73% chance of an abnormally small head (microcephaly). That's why the PKU diet needs to be under control before pregnancy."],"act":{"type":"number","prompt":"Using 14 g of fibre per 1,000 Calories, how much fibre should someone eating 2,000 Calories a day aim for?","answer":28,"tolerance":0,"unit":"g","explanation":"14 g × 2 = 28 g of fibre a day."}},{"id":"l2-b8","chapter":"PMS and PMDD","title":"PMS and PMDD","teach":["Premenstrual syndrome (PMS) brings physical and emotional changes that start in the luteal phase and go away within two days after bleeding starts. It affects about 20–40% of women who menstruate.","Premenstrual dysphoric disorder (PMDD) is a severe form of PMS that affects about 5% of women who menstruate. It brings marked mood swings, anxiety, irritability, low mood, strained relationships and physical symptoms such as breast tenderness, headaches and joint or muscle pain. It seems to come from extra sensitivity to normal hormone changes."],"act":{"type":"choice","prompt":"Which of these is part of PMDD?","options":[{"label":"Mood swings only","correct":false,"feedback":"Mood swings are part of it, but so are other symptoms."},{"label":"Physical symptoms only","correct":false,"feedback":"PMDD includes emotional symptoms as well."},{"label":"Mood swings, irritability, low mood and physical symptoms","correct":true,"feedback":"Yes. PMDD includes all of these."}]}}],"flashcards":[{"front":"Miscarriage rate in the first 20 weeks","back":"About 9% of pregnancies."},{"front":"Most common known cause of miscarriage","back":"A severe defect in the fetus."},{"front":"Subfertile","back":"Women with multiple miscarriages, men with sperm problems, or women who ovulate infrequently."},{"front":"Hormones released by the pituitary in the follicular phase","back":"Follicle-stimulating hormone (FSH) and luteinizing hormone (LH)."},{"front":"When does LH peak in a 28-day cycle?","back":"Around day 14, just before ovulation."},{"front":"Cause of menstrual cramps","back":"Prostaglandins made by the uterus."},{"front":"Hormones made by fat cells","back":"Estrogen, testosterone and leptin."},{"front":"Functional hypothalamic amenorrhea","back":"Loss of periods after losing more than about 10–15% of usual weight."},{"front":"Delay in first period for young athletes","back":"Often 2–4 years."},{"front":"Folic acid before pregnancy","back":"400 mcg a day for all women who could become pregnant."},{"front":"Metabolic syndrome","back":"Three of five: large waist, high triglycerides, low HDL, high blood pressure, high fasting glucose."},{"front":"High blood glucose early in pregnancy","back":"Teratogenic. Two- to three-fold higher risk of birth defects."},{"front":"Fibre for blood glucose control","back":"About 14 g per 1,000 Calories."},{"front":"Untreated PKU in pregnancy","back":"Raises the risk of heart defects, microcephaly and intellectual disability in the baby."},{"front":"PMDD","back":"Severe PMS with mood swings, irritability, low mood, anxiety and physical symptoms."}],"quiz":[{"q":"What is the rate of miscarriages in the first 20 weeks of pregnancy?","o":["6%","7%","8%","9%"],"a":3,"e":"Checked answer, not from an official key. The textbook says 9% are lost to miscarriage in the first 20 weeks."},{"q":"The most common cause of miscarriage for women is:","o":["structural abnormalities in the uterus.","the presence of a severe defect in the fetus.","maternal infection.","endocrine disorders.","unknown random events."],"a":1,"e":"Checked answer, not from an official key. The textbook names a severe defect in the fetus as the most common known cause."},{"q":"The two hormones secreted by the pituitary gland during the FOLLICULAR phase of a woman’s cycle are:","o":["follicle-stimulating hormone and progesterone.","progesterone and estrogen.","follicle-stimulating hormone and luteinizing hormone.","luteinizing hormone and progesterone.","luteinizing hormone and estrogen."],"a":2,"e":"Checked answer, not from an official key. Early in the cycle the pituitary releases FSH and LH."},{"q":"Fat cells produce all of the following hormones that may interfere with reproductive processes EXCEPT:","o":["estrogen.","testosterone.","leptin.","insulin.","Fat cells do not produce any of these hormones."],"a":3,"e":"Checked answer, not from an official key. Fat cells make estrogen, testosterone and leptin. Insulin comes from the pancreas."},{"q":"Loss of body fat in obese men and women is related to:","o":["improved hormone levels.","reduced oxidative stress.","improved conception rates.","All of the above","a and b only"],"a":3,"e":"Checked answer, not from an official key. The textbook links losing body fat to better hormone levels, less oxidative stress and better conception rates."},{"q":"Women who experience multiple miscarriages, men who have sperm abnormalities, and women that ovulate infrequently may be classified as:","o":["fertile.","infertile.","subfertile.","menopausal.","infecund."],"a":2,"e":"Checked answer, not from an official key. The textbook calls these people subfertile."},{"q":"The recommended daily intake of folic acid for ALL women who may become pregnant is:","o":["40 mcg.","40 mg.","400 mcg.","400 mg.","400 g."],"a":2,"e":"Checked answer, not from an official key. 400 micrograms a day."},{"q":"The primary effect(s) of being underweight on reproduction in women is/are:","o":["high likelihood of maternal complications.","the birth of small and early infants.","spina bifida or other NTDs.","All of the above","Both a and b"],"a":4,"e":"Checked answer, not from an official key. Being underweight raises the risk of complications for the mother and of small, early babies. Neural tube defects are linked to low folate, not low weight."},{"q":"Cramps and other side effects of menstruation can be traced back to the production of _______________________________ by the uterus.","o":["progesterone","estrogen","prostaglandins","pituitary hormones","both a and b"],"a":2,"e":"Checked answer, not from an official key. Prostaglandins make the uterus contract."},{"q":"When hormones are altered in the body, many changes take place that affect fertility; which of the following would NOT be one of those changes?","o":["Change in length or presence of the luteal phase","A decrease in the production of sperm","Alterations in the passageways that ova and sperm travel","Absence of the follicular phase","All of the above would be changes that occur."],"a":3,"e":"Checked answer, not from an official key. The textbook lists ovulation, the luteal phase, sperm production and the passageways, but not the follicular phase."},{"q":"Young female athletes often experience a delay in menarche of approximately what duration?","o":["1-2 years","2-4 years","No delay in menarche","6 mo-1 year","None of the above"],"a":1,"e":"Checked answer, not from an official key. The textbook says menarche is often delayed by 2–4 years."},{"q":"In a “typical” 28-day cycle, when would levels of luteinizing hormone most likely be the highest?","o":["Day 1","Day 7","Day 10","Day 14","Day 28"],"a":3,"e":"Checked answer, not from an official key. LH peaks just before ovulation, usually on day 14."},{"q":"Premenstrual dysphoric disorder (PMDD) is characterized by:","o":["mood swings.","irritability.","depressed mood.","physical symptoms.","All of the above"],"a":4,"e":"Checked answer, not from an official key. PMDD includes all of these."},{"q":"Untreated phenylketonuria in pregnant women can lead to:","o":["increased risk of heart defects in the infant.","infants with microcephaly.","mental retardation in their children.","All of the above","a and b only"],"a":3,"e":"Checked answer, not from an official key. The textbook names heart defects, microcephaly and intellectual disability."},{"q":"______________________________ during the first 2 months of pregnancy is teratogenic and leads to a two- to three-fold risk of congenital abnormalities.","o":["A high blood glucose level","Type 1 diabetes","Type 2 diabetes","Insulin resistance","Celiac disease"],"a":0,"e":"Checked answer, not from an official key. The textbook says high blood glucose in the first two months is teratogenic."},{"q":"Diets that provide low-glycemic index carbohydrates along with _______________________ of fiber daily are associated with improved blood glucose control.","o":["15 g","25-35 g","14 g per 1000 calories","38 g","50 g"],"a":2,"e":"Checked answer, not from an official key. The textbook recommends about 14 g of fibre per 1,000 Calories."},{"q":"Excess central body fat is related to ____________________________________.","o":["insulin resistance","increased sperm count","decreased testosterone production in females","increased testosterone production in males","decreased oxidative stress"],"a":0,"e":"Checked answer, not from an official key. Fat deep in the abdomen is linked to insulin resistance."},{"q":"Use the following information to answer questions 19 and 20.\n\nJane and her husband are interested in having a child, but she has had a hard time conceiving. She has met with her OB-GYN to have a physical, labs drawn, and a prenatal check-up in order to determine what the problem is. Lab work and other relevant data for Jane are as follows:\nAge: 36\nBlood pressure: 110/70 mm Hg\nFasting blood glucose: 130 mg/dL\nHDL cholesterol 35 mg/dL\nBlood triglycerides: 175 mg/dL\nWaist circumference: 36\"\nCurrent weight: 150 lbs\nHeight: 5'3\"\n\nBased on the data above, Jane will likely be diagnosed with:","o":["type 2 diabetes","metabolic syndrome","celiac disease","hypothalamic amenorrhea","gestational diabetes"],"a":1,"e":"Checked answer, not from an official key. Jane meets four of the five criteria for metabolic syndrome: high fasting glucose, low HDL, high triglycerides and a waist over 35 inches. Less certain: a fasting glucose of 130 could also point to type 2 diabetes, but the test seems to be built around metabolic syndrome, so check this one against your graded result."},{"q":"Jane and her husband are interested in having a child, but she has had a hard time conceiving. She has met with her OB-GYN to have a physical, labs drawn, and a prenatal check-up in order to determine what the problem is. Lab work and other relevant data for Jane are as follows:\nAge: 36\nBlood pressure: 110/70 mm Hg\nFasting blood glucose: 130 mg/dL\nHDL cholesterol 35 mg/dL\nBlood triglycerides: 175 mg/dL\nWaist circumference: 36\"\nCurrent weight: 150 lbs\nHeight: 5'3\"\n\nWhich of the following symptoms would indicate that Jane has this diagnosis?","o":["Her blood pressure, weight, and height","Hard time with conception and her age","High fasting blood glucose, blood triglycerides, and HDL cholesterol levels","Her waist circumference, age, and blood pressure","All of the above"],"a":2,"e":"Checked answer, not from an official key. Her fasting glucose and triglycerides are high and her HDL is low, which are three of the five criteria. Her blood pressure is normal."}]},{"n":3,"title":"Pregnancy Nutrition","kicker":"Lesson 3 of your course, built from Chapters 4 and 5 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l3-b1","chapter":"Why pregnancy nutrition matters","title":"Why pregnancy nutrition matters","teach":["What a woman eats before and during pregnancy affects the baby's growth, health at birth and even health later in life. Infant deaths are one way to measure how well a population is doing. Two-thirds of deaths of babies born alive happen in the first month after birth, the newborn period. Low birthweight and preterm birth are major reasons.","Each organ has a critical period of fast growth. A shortage at that exact time can cause lasting harm that can't be fixed later. The neural tube, which becomes the brain and spinal cord, forms in weeks 3 and 4 after conception, often before a woman knows she is pregnant. That is why folate matters so much early on."],"act":{"type":"choice","prompt":"When does the neural tube, which becomes the spinal cord, form?","options":[{"label":"1–2 weeks after conception","correct":false,"feedback":"A little too early. It forms in weeks 3 and 4."},{"label":"3–4 weeks after conception","correct":true,"feedback":"Yes, which is often before a woman knows she's pregnant."},{"label":"7–8 weeks after conception","correct":false,"feedback":"By then the critical period for the neural tube has passed."}]}},{"id":"l3-b2","chapter":"How the mother's body changes","title":"How the mother's body changes","teach":["Early in pregnancy, the mother's blood volume expands. Nutrients, some drawn from her stores, go first to support this expansion. The greater the expansion, the larger the baby tends to be. The extra water in the blood dilutes some vitamins and minerals, so blood levels can look lower even when intake is fine.","Hormones made by the placenta drive many of these changes. In the second half of pregnancy the body uses more fat, so blood lipids rise a lot. Triglycerides more than double, and cholesterol rises too. The placenta uses cholesterol to make hormones, and the baby uses it for nerve and cell membranes. Levels return to normal after birth."],"act":{"type":"choice","prompt":"What happens to blood cholesterol and triglycerides during pregnancy?","options":[{"label":"They drop because the blood is diluted.","correct":false,"feedback":"Dilution lowers some vitamins and minerals, but lipids go up."},{"label":"They rise a lot from pre-pregnancy levels.","correct":true,"feedback":"Yes. Triglycerides more than double by the end of pregnancy."},{"label":"They stay the same.","correct":false,"feedback":"They change a lot, especially in the second half of pregnancy."}]}},{"id":"l3-b3","chapter":"The placenta","title":"The placenta","teach":["The placenta makes hormones and enzymes, handles the exchange of nutrients and gases between mother and baby, and removes the baby's waste. It also acts as a partial barrier, but it is more like a fence than a filter. Many harmful things, including alcohol, some drugs, excess vitamins and bacteria such as listeria, can pass through.","Some substances don't cross at all. Maternal insulin is one: the baby has to make its own. That's why high blood glucose in the mother leads the baby to make extra insulin."],"act":{"type":"choice","prompt":"Which statement about the placenta is accurate?","options":[{"label":"It blocks alcohol and drugs from reaching the baby.","correct":false,"feedback":"It's more like a fence than a filter. Alcohol and many drugs do pass through."},{"label":"It makes hormones, exchanges nutrients and gases, and removes waste.","correct":true,"feedback":"Yes. These are its main jobs."},{"label":"Maternal insulin passes through it easily.","correct":false,"feedback":"Insulin doesn't cross the placenta. The baby makes its own."}]}},{"id":"l3-b4","chapter":"How much weight to gain","title":"How much weight to gain","teach":["Recommended weight gain depends on the woman's BMI before pregnancy. The Institute of Medicine ranges for one baby are: underweight (BMI under 18.5), 28–40 lb; normal weight (18.5–24.9), 25–35 lb; overweight (25–29.9), 15–25 lb; and obese (30 or more), 11–20 lb.","BMI is weight in kilograms divided by height in metres squared. For twins, the recommended gain is higher."],"act":{"type":"number","prompt":"A woman is 1.65 m tall and weighs 75 kg before pregnancy. What is her BMI? (Round to one decimal.)","answer":27.5,"tolerance":0.1,"unit":"kg/m²","explanation":"1.65 × 1.65 = 2.72. 75 ÷ 2.72 = 27.5. She is overweight, so the recommended gain is 15–25 lb."}},{"id":"l3-b5","chapter":"Key nutrients in pregnancy","title":"Key nutrients in pregnancy","teach":["Pregnant women need 71 g of protein a day, and most North American women already eat about that much. The recommendation for folate is 600 mcg a day, including 400 mcg of folic acid from fortified foods or a supplement. The rest can come from vegetables and fruit.","DHA, an omega-3 fat, supports the baby's brain and eyes. Pregnant women are advised to eat 2–3 servings a week of fish or seafood that is low in mercury, such as shrimp, canned light tuna, salmon, pollock and catfish. They should avoid high-mercury fish like swordfish, king mackerel, tilefish and shark. Algae-based DHA is an option for vegetarians."],"act":{"type":"choice","prompt":"Which of these would give a pregnant woman the most DHA?","options":[{"label":"A tuna salad sandwich","correct":true,"feedback":"Yes. Fish such as tuna is the main food source of DHA."},{"label":"A glass of whole milk","correct":false,"feedback":"Regular milk has very little DHA."},{"label":"A cup of broccoli","correct":false,"feedback":"Vegetables don't provide DHA."}]}},{"id":"l3-b6","chapter":"Pica and food safety","title":"Pica and food safety","teach":["Pica is a craving for and eating of non-food items such as ice, laundry starch or cornstarch, baking soda or clay. It is an eating disorder and is more common in non-Hispanic Black American women than in other groups. Women with pica are more likely to have low iron, though it isn't clear which comes first.","Pregnant women are more vulnerable to foodborne illness, especially listeria, which can cross the placenta. Foods to avoid include soft cheeses such as brie (unless made with pasteurized milk), ready-to-eat deli meats unless heated until steaming, raw oysters and other raw seafood, and unpasteurized milk."],"act":{"type":"sort","prompt":"Sort each food by its food safety risk in pregnancy.","categories":["Avoid or handle with care","Low risk"],"items":[{"label":"Unpasteurized milk","category":0,"feedback":"Can carry listeria and other bacteria."},{"label":"Raw oysters","category":0,"feedback":"Raw seafood carries a risk of foodborne illness."},{"label":"Cold deli meat straight from the package","category":0,"feedback":"Heat deli meats until steaming to kill listeria."},{"label":"A washed banana","category":1,"feedback":"Fresh fruit you peel is low risk."}]}},{"id":"l3-b7","chapter":"High blood pressure and preeclampsia","title":"High blood pressure and preeclampsia","teach":["Hypertension is blood pressure of 140/90 mm Hg or higher. High blood pressure disorders of pregnancy affect 5–10% of pregnancies and are a leading cause of death in mothers around the world. Preeclampsia usually appears after 20 weeks, with high blood pressure plus signs such as headache, blurred vision, belly pain and abnormal liver tests.","In preeclampsia, small blood clots and poor blood flow most affect the placenta and the mother's kidneys, liver and brain. Helpful habits include plenty of fruit and vegetables, enough fibre, moderate activity and enough vitamin D. High-dose iron supplements should not be given, because they can make inflammation worse."],"act":{"type":"choice","prompt":"Which of these is NOT recommended for a woman at risk of preeclampsia?","options":[{"label":"Five or more servings of fruit and vegetables a day","correct":false,"feedback":"This is recommended."},{"label":"High-dose iron supplements","correct":true,"feedback":"Right. High-dose iron can increase inflammation and shouldn't be given."},{"label":"Moderate exercise","correct":false,"feedback":"Moderate activity is part of the advice."}]}},{"id":"l3-b8","chapter":"Diabetes in pregnancy","title":"Diabetes in pregnancy","teach":["When the mother's blood glucose is high, the extra glucose reaches the baby. The baby responds by making more insulin, which moves glucose into its cells and turns it into fat. This can lead to a large baby and may raise the child's risk of type 2 diabetes later.","Type 1 diabetes is usually the most hazardous type in pregnancy, because of higher risks of kidney disease, high blood pressure, preeclampsia and other complications. Gestational diabetes develops during pregnancy. Insulin sensitivity usually improves once the placenta is delivered, but these women have a higher chance of gestational diabetes in later pregnancies and of type 2 diabetes."],"act":{"type":"choice","prompt":"What does the baby do when the mother's blood glucose is high?","options":[{"label":"Makes more insulin","correct":false,"feedback":"Yes, but that's only part of it."},{"label":"Turns extra glucose into stored fat","correct":false,"feedback":"True, but there's more."},{"label":"All of these, and it may raise the child's later risk of type 2 diabetes","correct":true,"feedback":"Right. Extra insulin, fat storage and a possible later risk all go together."}]}},{"id":"l3-b9","chapter":"Twins and other multiple pregnancies","title":"Twins and other multiple pregnancies","teach":["Only about 3% of babies come from multiple pregnancies, but they make up a large share of low-birthweight and preterm babies. Many twin pregnancies lose one embryo early on, which is called the vanishing twin. It is not unusual for embryos to disappear within 13 weeks of conception.","Carrying more than one baby raises the mother's risk of preeclampsia, iron-deficiency anemia, preterm delivery and cesarean birth. A 40-lb gain for twins takes about 35,000 more Calories over the pregnancy than a single pregnancy, roughly 150 extra Calories a day. A prenatal vitamin and mineral supplement is generally advised."],"act":{"type":"choice","prompt":"What is the vanishing twin phenomenon?","options":[{"label":"The disappearance of an embryo within 13 weeks of conception","correct":true,"feedback":"Yes. Many pregnancies that start as twins end with one baby."},{"label":"Fewer twins being born because of fertility drugs","correct":false,"feedback":"Fertility treatment actually raised the number of multiple births."},{"label":"One twin being much smaller at birth","correct":false,"feedback":"That's a growth difference, not the vanishing twin."}]}}],"flashcards":[{"front":"Infant deaths in the first month","back":"About two-thirds of infant deaths happen in the newborn period."},{"front":"Critical period for the neural tube","back":"Weeks 3 and 4 after conception."},{"front":"Blood lipids in pregnancy","back":"Rise a lot. Triglycerides more than double by the end of pregnancy."},{"front":"Dilution effect","back":"Expanded blood volume lowers blood levels of some vitamins and minerals."},{"front":"Main jobs of the placenta","back":"Making hormones and enzymes, exchanging nutrients and gases, and removing waste."},{"front":"Does insulin cross the placenta?","back":"No. The baby makes its own insulin."},{"front":"Weight gain for an overweight woman (BMI 25–29.9)","back":"15–25 lb."},{"front":"Protein in pregnancy","back":"71 g a day."},{"front":"Folate in pregnancy","back":"600 mcg a day, with 400 mcg as folic acid from fortified foods or a supplement."},{"front":"DHA in pregnancy","back":"2–3 servings a week of low-mercury fish or seafood."},{"front":"Pica","back":"Eating non-food items such as ice, starch or clay. More common in non-Hispanic Black American women."},{"front":"Hypertension","back":"Blood pressure of 140/90 mm Hg or higher."},{"front":"Leading cause of maternal death worldwide","back":"High blood pressure disorders of pregnancy."},{"front":"Organs most affected in preeclampsia","back":"The placenta and the mother's kidneys, liver and brain."},{"front":"Most hazardous type of diabetes in pregnancy","back":"Type 1 diabetes."},{"front":"Extra Calories for a twin pregnancy","back":"About 35,000 more over the pregnancy, roughly 150 a day."}],"quiz":[{"q":"Approximately what proportion of infants who die within the first year of life die within the first month after birth?","o":["1/3","2/3","1/2","3/4","5/8"],"a":1,"e":"Checked answer, not from an official key. The textbook says two-thirds of infant deaths happen in the first month."},{"q":"How can the change in lipid blood levels that occurs during pregnancy best be described?","o":["Cholesterol and triglyceride levels decrease due to the increased water volume in the blood","Cholesterol and triglyceride levels remain the same as pre-pregnancy levels","Cholesterol and triglyceride levels increase dramatically from pre-pregnancy levels","Cholesterol and triglyceride levels fluctuate daily depending on when the fetus is building nerve cells"],"a":2,"e":"Checked answer, not from an official key. The textbook says blood lipids increase dramatically, with triglycerides more than doubling."},{"q":"All of the following substances are transported through the placenta easily, with the exception of _________________, which is not transferred at all.","o":["water","cholesterol","oxygen","ketones","insulin"],"a":4,"e":"Checked answer, not from an official key. Maternal insulin does not cross the placenta. The baby makes its own."},{"q":"A critical period of spinal cord development following conception is:","o":["1-2 weeks after conception.","3-4 weeks after conception.","5-6 weeks after conception.","7-8 weeks after conception.","9-10 weeks after conception."],"a":1,"e":"Checked answer, not from an official key. The neural tube becomes the brain and spinal cord during weeks 3 and 4."},{"q":"The recommended daily protein (g) intake for pregnant women is _____.","o":["30 g","71 g","90 g","120 g"],"a":1,"e":"Checked answer, not from an official key. 71 g a day."},{"q":"Research is emerging that suggests pregnant women should increase their food sources of docosahexaenoic acid (DHA). Which of the following foods would provide the most DHA to pregnant women?","o":["1/2 tuna salad sandwich","1/4 cup granola containing 1 tsp sunflower seed","8 oz glass whole milk","1 cup broccoli"],"a":0,"e":"Checked answer, not from an official key. Fish such as tuna is the main food source of DHA."},{"q":"Pregnant women of ____________________________ ethnicity are more likely than those of other ethnicities to have an eating disorder known as pica.","o":["Chinese","African American","White Caucasian","Hispanic","Hmong"],"a":1,"e":"Checked answer, not from an official key. The textbook says pica is more common in non-Hispanic Black Americans."},{"q":"______________________________ do(es) NOT pose any foodborne bacterial risks in pregnant women.","o":["Brie cheese","Ready-to-eat deli meats","Raw oysters","Unpasteurized milk","Organic bananas"],"a":4,"e":"Checked answer, not from an official key. The others can carry listeria or other bacteria."},{"q":"Why must volume expansion occur BEFORE maternal nutrient stores accumulate?","o":["In order to support large gains in fetal weight","In order to provide the fetus with sufficient energy, nutrients, and oxygen","In order to provide the mother with plenty of fluids","In order to dilute the high concentration of nutrients in pregnant women","In order to make room for growing organs"],"a":1,"e":"Checked answer, not from an official key. Less certain: the textbook says expanded blood volume carries nutrients and oxygen to support the pregnancy, but it doesn't answer this question directly, so check it against your graded result."},{"q":"Which of the following is a major function of the placenta?","o":["Hormone and enzyme production","Nutrient and gas exchange between mother and fetus","Removal of waste products from the fetus","Barrier to drugs and alcohol","a, b, and c","all of the above"],"a":4,"e":"Checked answer, not from an official key. The placenta isn't a reliable barrier. Alcohol and many drugs pass through it."},{"q":"Use the following information to answer questions 11-13:\n\nJane is 5’7” (1.70 m) and weighs 160 pounds (72.7 kg).\n\nWhat is Jane’s body mass index?","o":["19.7","25.1","31.4","43"],"a":1,"e":"Checked answer, not from an official key. 72.7 ÷ (1.70 × 1.70) = 72.7 ÷ 2.89 = 25.1."},{"q":"Jane is 5’7” (1.70 m) and weighs 160 pounds (72.7 kg).\n\nBased on her BMI, Jane would be considered:","o":["underweight.","normal weight.","overweight.","obese.","morbidly obese."],"a":2,"e":"Checked answer, not from an official key. A BMI of 25–29.9 is overweight."},{"q":"Jane is 5’7” (1.70 m) and weighs 160 pounds (72.7 kg).\n\nJane becomes pregnant. How many pounds should Jane gain during her pregnancy, based on her BMI?","o":["11 to 20","15 to 25","25 to 35","28 to 40","35 to 45"],"a":1,"e":"Checked answer, not from an official key. The recommendation for overweight women is 15–25 lb."},{"q":"The recommended daily dietary intake of folate during pregnancy is:","o":["200 mcg from fortified food or supplements.","400 mcg from fortified food or supplements.","600 mcg total with 400 mcg from fortified food or supplements.","800 mcg total with 600 mcg from fortified food or supplements.","4000 mcg total in any form."],"a":2,"e":"Checked answer, not from an official key. 600 mcg a day, including 400 mcg of folic acid."},{"q":"Hypertension is defined as having a blood pressure of _____.","o":["≥120 mm Hg systolic or ≥70 mm Hg diastolic","≥140 mm Hg systolic or ≥90 mm Hg diastolic","≥120 mm Hg systolic or ≥90 mm Hg diastolic","≥140 mm Hg systolic or ≥70 mm Hg diastolic","≥160 mm Hg systolic or ≥110 mm Hg diastolic"],"a":1,"e":"Checked answer, not from an official key. The textbook uses 140/90 mm Hg."},{"q":"A worldwide leading cause of MATERNAL mortality is:","o":["gestational diabetes.","hypertensive disorders of pregnancy.","AIDS/HIV.","multifetal pregnancies.","adolescent pregnancy complications."],"a":1,"e":"Checked answer, not from an official key. The textbook names high blood pressure disorders of pregnancy."},{"q":"Maternal organs most affected by small blot clots and reduced blood flow in preeclampsia include all of the following EXCEPT:","o":["the placenta","the kidneys.","the brain.","the appendix.","the liver."],"a":3,"e":"Checked answer, not from an official key. The textbook lists the placenta, kidneys, liver and brain."},{"q":"Nutritional and physical activity recommendations that may benefit women at risk for preeclampsia include all of the following EXCEPT:","o":["high-dose iron supplements.","5 or more servings of fruits and vegetables daily.","moderate exercise.","adequate fiber intake","adequate vitamin D."],"a":0,"e":"Checked answer, not from an official key. High-dose iron can increase inflammation and shouldn't be given."},{"q":"High maternal blood glucose levels cause the fetus to ____________________________________________________.","o":["increase insulin output","convert glucose into triglycerides and store it as fat","potentially develop type 2 diabetes later in life","All of the above"],"a":3,"e":"Checked answer, not from an official key. The textbook describes all three effects."},{"q":"Which type of diabetes is potentially the most hazardous to the mother and fetus?","o":["Type 1 diabetes","Type 2 diabetes","Gestational diabetes","They are all equally hazardous."],"a":0,"e":"Checked answer, not from an official key. The textbook says type 1 is usually the most hazardous."},{"q":"The vanishing twin phenomenon refers to:","o":["the fact that more triplets and quadruplets are being born because of fertility drugs.","the disappearance of embryos within 13 weeks of conception.","the decreasing percentage of dizygotic twins in favor of monozygotes.","None of the above"],"a":1,"e":"Checked answer, not from an official key. The textbook defines it this way."},{"q":"A multifetal pregnancy increases the mother’s risk for:","o":["development of preeclampsia","development of iron-deficiency anemia","preterm delivery","cesarean delivery","All of the above"],"a":4,"e":"Checked answer, not from an official key. Multiple pregnancies raise the risk of all of these."},{"q":"To achieve a 40-pound weight gain, women with twins need to consume approximately _________ more calories during pregnancy than do women with singleton pregnancies.","o":["15,000","25,000","35,000","45,000","50,000"],"a":2,"e":"Checked answer, not from an official key. The textbook gives about 35,000 Calories, or roughly 150 a day."},{"q":"“Best practice” vitamin and mineral supplement recommendations for women during multifetal pregnancies include which of the following statements?","o":["There is no need to take a vitamin and mineral supplement if you are eating enough food.","Women with twins need to take more iron.","Women should use a prenatal vitamin and mineral supplement.","Women with twins need to take twice the recommended amount of a supplement."],"a":2,"e":"Checked answer, not from an official key. The textbook's twin case uses a prenatal vitamin and mineral supplement. It doesn't support doubling the dose."}]},{"n":4,"title":"Lactation Nutrition","kicker":"Lesson 4 of your course, built from Chapters 6 and 7 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l4-b1","chapter":"How the breast makes milk","title":"How the breast makes milk","teach":["During puberty, the cyclic release of estrogen and progesterone develops the breasts. The working units of the mammary gland are the alveoli: clusters of milk-secreting cells around a small duct. The ducts branch like a tree toward the nipple. Muscle-like cells around the alveoli contract under the hormone oxytocin to push milk out (the letdown).","Breast size depends mostly on fat and doesn't decide how much milk a woman can make. Milk supply works on supply and demand: the more fully the breast is emptied, the more milk it makes. If a lot of milk is left behind, production slows."],"act":{"type":"choice","prompt":"What are the functional units of the mammary gland?","options":[{"label":"Alveoli","correct":true,"feedback":"Yes. Each alveolus is a cluster of cells that secrete milk."},{"label":"Areolas","correct":false,"feedback":"The areola is the darker skin around the nipple, not where milk is made."},{"label":"Lobules","correct":false,"feedback":"Lobules are groups of alveoli. The alveoli are the units that make milk."}]}},{"id":"l4-b2","chapter":"What's in breast milk","title":"What's in breast milk","teach":["Breast milk is mostly water, so a breastfed baby doesn't need extra water. Lactose is the main carbohydrate, and it helps the baby absorb calcium. Fat gives about half the energy. Fat is lower in the foremilk at the start of a feed and higher in the hindmilk at the end. Whey, the main protein, forms a soft curd that is easy to digest. Milk also carries antibodies, so nursing while the mother is sick helps protect the baby.","Milk from mothers of preterm babies has more protein and energy (58–70 kcal per 100 mL). Breast milk is low in vitamin K, so all newborns get a vitamin K shot at birth. Without it, a baby can bleed too much because the blood doesn't clot properly."],"act":{"type":"sort","prompt":"Match each part of breast milk with what it does.","categories":["Lactose","Whey","Hindmilk","Antibodies"],"items":[{"label":"Main carbohydrate. Helps calcium absorption.","category":0,"feedback":"Lactose is the dominant carbohydrate in human milk."},{"label":"Forms a soft, easily digested curd","category":1,"feedback":"Whey protein makes a soft curd in the baby's stomach."},{"label":"Higher-fat milk at the end of a feed","category":2,"feedback":"Hindmilk is richer in fat than foremilk."},{"label":"Protect the baby from germs the mother meets","category":3,"feedback":"The mother makes antibodies to germs around her and passes them on in her milk."}]}},{"id":"l4-b3","chapter":"Latch and feeding","title":"Latch and feeding","teach":["A good latch means the baby's mouth takes in a large part of the areola, with the nose close to the breast and breathing freely. The mother should hear swallowing, but not smacking, clicking or slurping. Those sounds suggest a poor latch, which raises the risk of sore nipples.","If a baby always nurses briefly on both breasts, they may get lots of low-fat foremilk and not enough hindmilk. That can cause gas, colic, loose stools and slow weight gain. Letting the baby finish one breast before switching, and having someone watch a feed, helps."],"act":{"type":"choice","prompt":"A baby makes smacking and clicking sounds while nursing. What does that tell you?","options":[{"label":"The baby is feeding well.","correct":false,"feedback":"You should hear swallowing, not smacking or clicking."},{"label":"The baby probably isn't latched on correctly, which can lead to sore nipples.","correct":true,"feedback":"Yes. These sounds point to a poor latch."},{"label":"Nothing. Some babies are just noisy.","correct":false,"feedback":"These sounds are a sign worth checking."}]}},{"id":"l4-b4","chapter":"The mother's diet","title":"The mother's diet","teach":["Drinking extra fluid doesn't raise milk supply. Mothers should drink to thirst and aim for pale yellow urine, rather than counting glasses. Mothers don't need to avoid common allergy foods unless the baby seems to react. If a baby has colic, cutting out cow's milk, eggs, peanuts, tree nuts, wheat, soy or fish has helped in studies. Only cut out foods that seem to cause problems, and replace the nutrients they provided.","Fish is good for mother and baby, but she should choose low-mercury seafood and avoid swordfish, shark and king mackerel."],"act":{"type":"choice","prompt":"A nursing mother asks how many glasses of water she should drink each day. What's the best answer?","options":[{"label":"At least 10 glasses","correct":false,"feedback":"Drinking extra doesn't raise milk supply, and needs vary."},{"label":"Drink to thirst, enough to keep your urine pale yellow","correct":true,"feedback":"Yes. Thirst and urine colour are better guides than a set number."},{"label":"6–8 glasses, no more","correct":false,"feedback":"There's no set number. Thirst is the guide."}]}},{"id":"l4-b5","chapter":"Common breastfeeding problems","title":"Common breastfeeding problems","teach":["Sore nipples, engorgement, plugged ducts and mastitis are all common. Mild nipple soreness in the first week is normal, but cracks or pain that lasts call for a check of the latch. Engorgement, swollen and overfull breasts, peaks around days 3–5. It can happen any time the breasts aren't emptied for a long stretch, such as missing several feeds.","Mastitis is inflammation or infection of the breast. The mother should keep nursing or pumping, because emptying the breast helps it clear. Rest, fluids, pain relief and, if it doesn't improve within 24 hours, antibiotics are used."],"act":{"type":"choice","prompt":"A new mother misses six hours of feeds while out. What problem is she most likely to have?","options":[{"label":"Engorgement","correct":true,"feedback":"Yes. Going a long time without emptying the breasts leads to engorgement."},{"label":"Sore nipples","correct":false,"feedback":"Sore nipples usually come from a poor latch, not from skipped feeds."},{"label":"Jaundice","correct":false,"feedback":"Jaundice is a newborn condition, not a problem for the mother."}]}},{"id":"l4-b6","chapter":"Medications, herbs and alcohol","title":"Medications, herbs and alcohol","teach":["If a nursing mother needs a medication, the safest time to take it is usually right after the baby nurses, at the lowest dose that works. Herbs can matter too. Large doses of St. John's wort may lower prolactin, the hormone that drives milk production, and so reduce milk supply.","Alcohol passes into milk. If a nursing mother drinks, the Institute of Medicine advises no more than 0.5 g of alcohol per kg of her body weight per day. Alcohol doesn't help babies sleep; babies actually sleep less after milk with alcohol. Pumping right after drinking doesn't speed up clearance. The safer plan is to pump before going out and use that milk until the alcohol has cleared."],"act":{"type":"number","prompt":"A nursing mother weighs 60 kg. Using 0.5 g of alcohol per kg, what is her daily limit in grams of alcohol?","answer":30,"tolerance":0,"unit":"g","explanation":"60 × 0.5 = 30 g of alcohol, which is about two cans of beer."}},{"id":"l4-b7","chapter":"Newborn jaundice","title":"Newborn jaundice","teach":["Jaundice is yellowing of the skin from too much bilirubin in the blood. At least 40% of healthy full-term babies and 80% of preterm babies become visibly jaundiced. Bilirubin comes from the breakdown of red blood cells. Newborns break down a lot of extra red blood cells after birth, and their young livers can't clear bilirubin quickly.","It is usually harmless and goes away on its own, but very high levels need treatment. Feeding often helps the baby pass bilirubin in stool."],"act":{"type":"choice","prompt":"What causes high bilirubin in newborns?","options":[{"label":"Breakdown of red blood cells","correct":true,"feedback":"Yes. Newborns break down many red blood cells after birth, and their livers can't keep up."},{"label":"High maternal vitamin A intake","correct":false,"feedback":"Bilirubin comes from red blood cell breakdown, not vitamin A."},{"label":"A labour lasting over 12 hours","correct":false,"feedback":"Length of labour isn't the cause."}]}}],"flashcards":[{"front":"Hormones behind breast development at puberty","back":"The cyclic release of estrogen and progesterone."},{"front":"Functional units of the mammary gland","back":"The alveoli."},{"front":"Largest components of breast milk","back":"Water first, then nutrients such as lactose and fat."},{"front":"Main carbohydrate in breast milk","back":"Lactose."},{"front":"Protein that forms a soft curd","back":"Whey."},{"front":"Foremilk vs. hindmilk","back":"Foremilk at the start of a feed is lower in fat. Hindmilk at the end is higher in fat."},{"front":"Energy in preterm milk","back":"58–70 kcal per 100 mL."},{"front":"Why newborns get vitamin K","back":"To prevent bleeding from poor blood clotting."},{"front":"Fluids while breastfeeding","back":"Drink to thirst. Aim for pale yellow urine."},{"front":"Safest time to take a medication","back":"Right after the baby nurses."},{"front":"Alcohol limit while breastfeeding","back":"No more than 0.5 g per kg of body weight per day."},{"front":"St. John's wort and breastfeeding","back":"Large doses may lower prolactin and reduce milk supply."},{"front":"Smacking or clicking while nursing","back":"A sign of a poor latch, which can cause sore nipples."},{"front":"Mastitis","back":"Breast inflammation or infection. Keep nursing or pumping."},{"front":"Newborn jaundice","back":"Yellow skin from high bilirubin, which comes from red blood cell breakdown. At least 40% of term babies get it."}],"quiz":[{"q":"Which of the following is a nutritional benefit of breastfeeding?","o":["It provides optimal nutrition to the infant.","The balance of nutrients matches requirements needed for human growth.","Infants do not need additional fluids or water when breastfeeding.","The low protein content is easily tolerated.","All of the above are considered nutritional benefits."],"a":4,"e":"Checked answer, not from an official key. Less certain: each statement describes a benefit of breast milk, but the textbook doesn't list them together, so check this one against your graded result."},{"q":"The cyclic release of what 2 hormones governs pubertal breast development?","o":["Prolactin and oxytocin","Progesterone and estrogen","Prolactin and estrogen","Progesterone and oxytocin","Testosterone and progesterone"],"a":1,"e":"Checked answer, not from an official key. The textbook says the cyclic release of estrogen and progesterone governs pubertal breast development."},{"q":"The functional units of the mammary gland are the:","o":["lobules.","myoepithelial cells.","alveoli.","areolas.","secretory cells."],"a":2,"e":"Checked answer, not from an official key. The textbook names the alveoli."},{"q":"The major component of breast milk is _________________, while the second largest component is ____________________.","o":["water, lipids","lipids, water","protein, carbohydrate","carbohydrate, protein","protein, lipids"],"a":0,"e":"Checked answer, not from an official key. Water is the largest component. Of these choices, only water then lipids fits."},{"q":"The dominant carbohydrate in human milk is _________________.","o":["galactose","glucose","lactose","sucrose","maltose"],"a":2,"e":"Checked answer, not from an official key. The textbook says lactose is the dominant carbohydrate."},{"q":"What nutrient forms a soft, easily digestible curd in the baby’s stomach?","o":["Copper","Vitamin K","Whey","Casein","Iron"],"a":2,"e":"Checked answer, not from an official key. The textbook says whey protein forms a soft, easily digestible curd."},{"q":"A health care professional was asked by a nursing mom, “How many glasses of water should I drink a today?” What would be an appropriate recommendation?","o":["6-8 glasses","8-10 glasses",">10 glasses","Drink enough fluids to keep your urine pale yellow."],"a":3,"e":"Checked answer, not from an official key. The textbook advises drinking to thirst rather than a set number of glasses."},{"q":"Use the following information for questions 8-10:\n\nA young woman comes into your office for a lactation consultation complaining that her 1-month-old baby is colicky and slow to gain weight. Her baby requires 6 to 7 diaper changes each day and suffers from diarrhea. She tells you she allows the baby to nurse equally on each breast so that she does not feel \"overfull\"; she is desperate for help and asks your advice on what to do. A 24-hour diet history provides the following information about her eating habits.\nBreakfast: cereal, milk, banana, and walnut pieces; sometimes she has eggs\nLunch: peanut butter sandwich, salad, and grapes with a glass of milk\nDinner: fish or chicken, vegetables, potato or rice, applesauce, and milk\nSnacks: change daily, but she likes trail mix because it is easy to eat when nursing\n\nWhat would the best advice be for this woman?","o":["Allow your baby to nurse on one breast only until it is completely empty.","Allow us to evaluate you while you are nursing your baby and see what you are doing.","Stop nursing immediately and use an infant formula so your baby starts growing.","Use supplemental infant formula after each feeding because the baby is obviously not getting enough to eat.","a and b only"],"a":4,"e":"Checked answer, not from an official key. Less certain: emptying one breast gives the baby more hindmilk, and watching a feed checks the latch. Stopping breastfeeding isn't called for. Check this one against your graded result."},{"q":"A young woman comes into your office for a lactation consultation complaining that her 1-month-old baby is colicky and slow to gain weight. Her baby requires 6 to 7 diaper changes each day and suffers from diarrhea. She tells you she allows the baby to nurse equally on each breast so that she does not feel \"overfull\"; she is desperate for help and asks your advice on what to do. A 24-hour diet history provides the following information about her eating habits.\nBreakfast: cereal, milk, banana, and walnut pieces; sometimes she has eggs\nLunch: peanut butter sandwich, salad, and grapes with a glass of milk\nDinner: fish or chicken, vegetables, potato or rice, applesauce, and milk\nSnacks: change daily, but she likes trail mix because it is easy to eat when nursing\n\nWhat is likely happening to this baby and causing the diarrhea?","o":["The baby is not latched on properly.","The mother is not producing enough breast milk.","The baby is getting too much foremilk and not enough hindmilk.","The baby has a poor suckle.","The baby is lactose intolerant."],"a":2,"e":"Checked answer, not from an official key. Switching breasts early gives lots of low-fat foremilk, which can cause gas, colic and loose stools."},{"q":"A young woman comes into your office for a lactation consultation complaining that her 1-month-old baby is colicky and slow to gain weight. Her baby requires 6 to 7 diaper changes each day and suffers from diarrhea. She tells you she allows the baby to nurse equally on each breast so that she does not feel \"overfull\"; she is desperate for help and asks your advice on what to do. A 24-hour diet history provides the following information about her eating habits.\nBreakfast: cereal, milk, banana, and walnut pieces; sometimes she has eggs\nLunch: peanut butter sandwich, salad, and grapes with a glass of milk\nDinner: fish or chicken, vegetables, potato or rice, applesauce, and milk\nSnacks: change daily, but she likes trail mix because it is easy to eat when nursing\n\nAfter looking at her diet, what changes could you suggest to help with the baby’s colic?","o":["Eliminate all fruit except canned fruit","Eliminate nuts","Eliminate dairy products","All of the above","b and c only"],"a":4,"e":"Checked answer, not from an official key. Cow's milk, peanuts and tree nuts are among the foods linked to colic in the textbook. There's no reason to cut fruit."},{"q":"Continuing to nurse while you are sick actually protects your baby because:","o":["you do not pass germs through breast milk.","your breast milk is full of antibodies that are passed on to your baby.","you do not contaminate bottles by handling them.","infant formulas are higher in vitamins and minerals and help boost the baby’s immune system."],"a":1,"e":"Checked answer, not from an official key. The mother makes antibodies to the germs around her and passes them on in her milk."},{"q":"A baby that is not given vitamin K at birth may have:","o":["excessive bleeding due to a lack of blood clotting.","decreased calcium absorption.","increased incidence of colic.","increased incidence of diarrhea","All of the above"],"a":0,"e":"Checked answer, not from an official key. Vitamin K is needed for clotting. Without it, babies are at risk of vitamin K deficiency bleeding."},{"q":"Which of the following would NOT be considered a common condition that is experienced by a woman who is breastfeeding?","o":["Sore nipples","Engorgement","Mastitis","Plugged ducts","All of the above are common problems."],"a":4,"e":"Checked answer, not from an official key. The textbook covers all four as common problems in breastfeeding."},{"q":"When is the safest time for a nursing mom to take a drug?","o":["In the morning","After eating a meal","After the infant nurses","Any time is safe to take a drug.","It is never safe for a nursing mom to take drugs."],"a":2,"e":"Checked answer, not from an official key. The textbook says the safest time is usually right after the baby nurses."},{"q":"If a 110-lb nursing woman (50 kg) wants to drink alcohol, how many cans of beer (15 g alcohol/12 oz) can this woman drink and stay within the Institute of Medicine’s alcohol recommendations?","o":["0","1","2","3"],"a":1,"e":"Checked answer, not from an official key. 50 kg × 0.5 g = 25 g of alcohol. One can is 15 g, and two would be 30 g, which is over the limit."},{"q":"Approximately _____ of term infants will become visibly jaundiced with their serum bilirubin levels exceeding 5 to 7 mg/dL.","o":["20%","30%","40%","50%","60%"],"a":2,"e":"Checked answer, not from an official key. The textbook says at least 40% of healthy full-term babies."},{"q":"Hyperbilirubinemia in newborns is caused by ________________________________.","o":["destruction of red blood cells","high blood lipid levels","high maternal intake of vitamin A","labor lasting over 12 hours"],"a":0,"e":"Checked answer, not from an official key. Bilirubin comes from the breakdown of red blood cells."},{"q":"The energy content of breast milk in women who deliver pre-term infants is ___________________.","o":["30-37 kcal/100 mL","40-48 kcal/100 mL","58-70 kcal/100 mL","72-120 kcal/100 mL"],"a":2,"e":"Checked answer, not from an official key. The textbook gives 58–70 kcal per 100 mL."},{"q":"A new mother goes to the mall shopping with her friends. She is gone longer than planned and is not able to nurse her baby until she returns 6 hours later. What is the most likely problem she will have?","o":["A breast infection","Engorgement","Plugged ducts","Sore nipples","Mastitis"],"a":1,"e":"Checked answer, not from an official key. Going hours without emptying the breasts leads to engorgement."},{"q":"A lactation consultant is observing a new mom breastfeeding and notices that the baby is making smacking and clicking sounds as she sucks. This tells her that:","o":["the baby is eating well and has a strong suckle.","the baby has a cleft palate and should be closely followed.","the baby is not latched on correctly and this may increase the risk of sore nipples.","this is just a noisy baby.","Noise is not an indicator of anything."],"a":2,"e":"Checked answer, not from an official key. The textbook says you should hear swallowing, not smacking or clicking."},{"q":"Large doses of St. John’s wort decrease prolactin levels in women. This could potentially:","o":["reduce oxytocin levels.","cause breast milk to taste like maple syrup.","cause a woman to become constipated.","reduce breast milk supply.","cause depression in some women."],"a":3,"e":"Checked answer, not from an official key. Prolactin drives milk production, so lowering it can reduce supply."},{"q":"Your best friend had a baby 3 months ago and is anxious to go “out on the town” with her friends. She is still breastfeeding, but would like to be able to have some drinks. What advice would you give her?","o":["It is okay to drink while nursing because it actually helps babies sleep.","It is okay to drink while nursing because it increases breast milk production.","Pump your milk immediately after drinking and it will be eliminated from your body.","Pump milk before going out and use that until the alcohol has been cleared from your system.","Drink only beer because babies tolerate it."],"a":3,"e":"Checked answer, not from an official key. The textbook suggests nursing or pumping before drinking and using that milk until the alcohol has cleared."},{"q":"You are at a nice restaurant and would like to order seafood for dinner; however, you are breastfeeding. Which of the following would have the lowest amount of mercury and be safest for you to eat?","o":["Calamari","Swordfish","Shark","Tuna","King mackerel"],"a":0,"e":"Checked answer, not from an official key. Less certain: swordfish, shark and king mackerel are high in mercury and tuna is moderate, so calamari (squid) is the low-mercury choice, but the textbook doesn't name calamari. Check this one against your graded result."},{"q":"Which of the following foods would a pediatrician recommend a nursing mother with no history of food allergies in the family restrict?","o":["Peanuts and tree nuts","Wheat","Soy","Eggs","None of the above"],"a":4,"e":"Checked answer, not from an official key. Less certain: the textbook advises cutting out only foods that seem to cause problems, so with no family history, no restriction is needed. Check this one against your graded result."},{"q":"A woman with mastitis should continue to nurse her baby.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Emptying the breast by nursing or pumping helps clear mastitis."}]},{"n":5,"title":"Infant Nutrition","kicker":"Lesson 5 of your course, built from Chapters 8 and 9 of your Nutrition Through the Life Cycle textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l5-b1","chapter":"How babies develop","title":"How babies develop","teach":["Babies gain control of their muscles in a set order: from the head downward, and from the centre of the body out to the hands and fingers. They hold up their heads before they sit, and use their arms before they pick things up with their fingers. Newborns are born with feeding reflexes such as rooting: stroke a baby's cheek and they turn toward it and open their mouth.","In the first two years, babies learn through their senses and movements. This is called the sensorimotor stage. Feeding skills follow development: sitting with support, moving the head toward a spoon, then picking up finger foods. Readiness, not just age, should guide when new textures are offered."],"act":{"type":"choice","prompt":"Which statement describes how muscle control develops in infants?","options":[{"label":"From the head downward, and from the centre of the body out to the hands","correct":true,"feedback":"Yes. Head control comes first, and fine finger control comes last."},{"label":"From the toes upward","correct":false,"feedback":"It's the other way around: head first, legs later."},{"label":"From the fingers inward","correct":false,"feedback":"The central muscles come first, and the hands and fingers later."}]}},{"id":"l5-b2","chapter":"Energy and nutrient needs","title":"Energy and nutrient needs","teach":["Babies need a lot of energy for their size. In the first six months the average is 108 Calories per kg of body weight, based on the growth of breastfed babies. From 6 to 12 months it is 98 Calories per kg. Protein needs from 7 to 12 months are about 11 g a day.","Breast milk and standard formula both give about 20 Calories per ounce. Iron stores from birth last about four to six months. Exclusively breastfed babies are advised to get an iron supplement starting at four months (1 mg per kg per day) until they eat iron-rich foods. Meat is a good early food for iron and zinc."],"act":{"type":"number","prompt":"A 4-month-old baby weighs 7 kg. At 108 Calories per kg, how many Calories does she need each day?","answer":756,"tolerance":0,"unit":"Calories","explanation":"7 × 108 = 756 Calories a day."}},{"id":"l5-b3","chapter":"Formula feeding","title":"Formula feeding","teach":["Formula-fed babies should stay on formula for the first year. Routine formulas for full-term babies give 19–20 Calories per ounce when mixed as directed. Formulas for preterm babies after they leave the hospital usually give 22 or 24 Calories per ounce.","Many feeding troubles are blamed on allergies when they aren't. A baby with a suspected protein intolerance may be switched to a formula with hydrolyzed (broken-down) protein, which is less likely to trigger a reaction. These formulas cost more and taste stronger."],"act":{"type":"number","prompt":"A baby drinks 24 ounces of standard formula a day. At 20 Calories per ounce, how many Calories is that?","answer":480,"tolerance":0,"unit":"Calories","explanation":"24 × 20 = 480 Calories."}},{"id":"l5-b4","chapter":"Growth charts and size at birth","title":"Growth charts and size at birth","teach":["Growth charts show how a baby's weight, length and head size compare with other babies of the same age and sex. A baby between the 10th and 90th percentiles at birth is appropriate for gestational age (AGA). Below the 10th is small for gestational age (SGA), and above the 90th is large (LGA).","One measurement is a snapshot. What matters most is the pattern over time, and whether the baby keeps following their own curve."],"act":{"type":"sort","prompt":"Sort each newborn by size for gestational age.","categories":["SGA (below 10th)","AGA (10th–90th)","LGA (above 90th)"],"items":[{"label":"Birthweight at the 5th percentile","category":0,"feedback":"Below the 10th percentile is small for gestational age."},{"label":"Birthweight at the 50th percentile","category":1,"feedback":"This is right in the middle, so appropriate for gestational age."},{"label":"Birthweight at the 75th percentile","category":1,"feedback":"Still between the 10th and 90th, so AGA."},{"label":"Birthweight at the 95th percentile","category":2,"feedback":"Above the 90th percentile is large for gestational age."}]}},{"id":"l5-b5","chapter":"Newborn screening and inborn errors","title":"Newborn screening and inborn errors","teach":["Newborns are screened shortly after birth for metabolic disorders, most often PKU, congenital hypothyroidism, galactosemia and sickle cell disease. Finding these early lets treatment start before damage occurs. Food allergies can't be picked up by newborn screening.","Babies with galactosemia can't break down galactose, which is part of lactose (milk sugar). They can't have breast milk or regular milk-based formula. Soy formula, which has no lactose, is used instead. Babies with PKU need a special formula low in phenylalanine."],"act":{"type":"choice","prompt":"Which feeding is NOT safe for a baby with galactosemia?","options":[{"label":"Soy formula","correct":false,"feedback":"Soy formula has no lactose, so it's used for galactosemia."},{"label":"Breast milk","correct":true,"feedback":"Right. Breast milk is rich in lactose, which contains galactose."},{"label":"Apple juice","correct":false,"feedback":"Apple juice has no galactose."}]}},{"id":"l5-b6","chapter":"Vegetarian and vegan babies","title":"Vegetarian and vegan babies","teach":["A well-planned vegetarian diet can meet a baby's needs, but some nutrients need attention. Iron, vitamin B12, vitamin D, calcium and zinc are the main ones, especially in vegan diets. Fortified soy formula, iron-fortified cereals, beans and lentils, and a B12 source all help.","Check the diet against the baby's needs: about 98 Calories per kg from 6 to 12 months, and about 11 g of protein a day."],"act":{"type":"number","prompt":"A 10-month-old weighs 9 kg. At 98 Calories per kg, how many Calories does he need each day?","answer":882,"tolerance":0,"unit":"Calories","explanation":"9 × 98 = 882 Calories a day."}},{"id":"l5-b7","chapter":"Preterm babies and special needs","title":"Preterm babies and special needs","teach":["For preterm babies, use the corrected age: subtract the weeks born early from the age since birth. A baby born at 32 weeks is 8 weeks (about 2 months) early. At 9 months old, that baby's corrected age is about 7 months, and development should be judged on that. Preterm babies often can't suck, swallow and breathe in rhythm until 32–34 weeks, so they may need gavage feeding: a tube from the mouth or nose into the stomach.","Preterm babies need more energy, about 105–130 Calories per kg. Babies with bronchopulmonary dysplasia (BPD), a lung condition, grow more slowly because of higher nutrient needs and changes in their hormone and lung systems. Some babies need fewer Calories than usual, such as babies with Down syndrome, who tend to be less active and have lower energy needs."],"act":{"type":"number","prompt":"A baby born at 28 weeks (12 weeks early) is now 6 months old. What is the corrected age in months? (Use 4 weeks = 1 month.)","answer":3,"tolerance":0,"unit":"months","explanation":"12 weeks early is 3 months. 6 − 3 = 3 months corrected age."}}],"flashcards":[{"front":"Order of muscle control in infants","back":"From the head downward, and from the centre of the body out to the hands."},{"front":"Rooting reflex","back":"Stroke the cheek and the baby turns toward it and opens the mouth."},{"front":"Energy needs, 0–6 months","back":"About 108 Calories per kg per day."},{"front":"Energy needs, 6–12 months","back":"About 98 Calories per kg per day."},{"front":"Protein, 7–12 months","back":"About 11 g a day."},{"front":"Calories in standard formula or breast milk","back":"About 20 per ounce."},{"front":"Formula for preterm babies after discharge","back":"Usually 22 or 24 Calories per ounce."},{"front":"Suspected protein intolerance","back":"Switch to a formula with hydrolyzed (broken-down) protein."},{"front":"AGA","back":"Appropriate for gestational age: birthweight between the 10th and 90th percentiles."},{"front":"Newborn screening","back":"Commonly PKU, hypothyroidism, galactosemia and sickle cell disease. Not food allergies."},{"front":"Galactosemia","back":"Can't break down galactose. No breast milk or milk-based formula. Soy formula is used."},{"front":"Nutrients of concern for vegan babies","back":"Iron, vitamin B12, vitamin D, calcium and zinc."},{"front":"Corrected age","back":"Age since birth minus the weeks born early."},{"front":"Gavage feeding","back":"A tube from the mouth or nose into the stomach."},{"front":"Bronchopulmonary dysplasia (BPD)","back":"A lung condition. Slower growth from higher needs and hormone and lung changes."},{"front":"Lower energy needs","back":"Babies with Down syndrome often need fewer Calories."}],"quiz":[{"q":"Which of the following statements best describes motor development in infants?","o":["Voluntary control of muscles starts from the head and moves down to the legs.","Voluntary control of muscles starts from being able to fan toes out at birth to blinking eyes in response to a loud noise or light.","Voluntary muscle control develops with central muscles first and then moves out to hand muscles.","Voluntary muscle control develops with rooting reflex and then moves out to hand muscles.","a and c"],"a":4,"e":"Checked answer, not from an official key. Muscle control develops from the head down and from the centre out."},{"q":"An example of sensorimotor development is _______________________________________.","o":["thumb sucking","crying when hungry","blinking eyes in response to bright light","ability to sleep through the night","an increase in head circumference"],"a":2,"e":"Checked answer, not from an official key. Less certain: sensorimotor development is about responding to the senses with movement, and blinking at bright light is the clearest example here. Thumb sucking could also be argued, so check this one against your graded result."},{"q":"The AVERAGE caloric need of infants in the first six months of life is ________________ per kg of body weight, based on growth in breast-fed infants.","o":["57 Calories","98 Calories","108 Calories","122 Calories","154 Calories"],"a":2,"e":"Checked answer, not from an official key. The textbook gives 108 Calories per kg for the first six months."},{"q":"Based on your answer to question #3, a 5-month-old infant would require approximately _____ total Calories per day based on a weight of 6 kg.","o":["648","732","924","1037","1251"],"a":0,"e":"Checked answer, not from an official key. 6 × 108 = 648."},{"q":"A 3-month-old infant was taking 30 ounces/day of a standard formula. How many Calories did the infant consume each day?","o":["600","300","450","510"],"a":0,"e":"Checked answer, not from an official key. Standard formula gives about 20 Calories an ounce. 30 × 20 = 600."},{"q":"Based on your answer to #6, this baby is: (Question 6 asks you to plot an 8-pound newborn girl on the growth chart in your test.)","o":["small for gestational age (SGA).","large for gestational age (LGA).","appropriate for gestational age (AGA).","None of the above"],"a":2,"e":"Checked answer, not from an official key. An 8-pound newborn girl falls between the 10th and 90th percentiles, so she is appropriate for gestational age."},{"q":"Which of the following conditions CANNOT be screened for shortly after birth?","o":["PKU","Food allergy","Galactosemia","Sickle-cell disease","Hypothyroidism"],"a":1,"e":"Checked answer, not from an official key. Newborns are screened for PKU, hypothyroidism, galactosemia and sickle cell disease, but not food allergies."},{"q":"An infant with a suspected protein intolerance may be:","o":["put on a soy formula because plant proteins are well tolerated.","put on a hydrolyzed formula because the protein is broken down.","breast fed only because breast milk is the gold standard to feed babies","put on IV fluids with a fat replacement."],"a":1,"e":"Checked answer, not from an official key. The textbook says these babies may be switched to a hydrolyzed protein formula."},{"q":"Use the following information to answer questions 10-12.\n\nThe mother of a 9-month-old vegetarian infant weighing 19 pounds (8.6 kg) provided the following diet history for her son.\nBreakfast: 1/4 cup oatmeal made with water; 1/2 banana; 4 oz. apple juice\nLunch: Rice cake with 1 t. peanut butter; 1/2 c. applesauce; 4 oz. soy formula\nDinner: 1/4 cup mashed potatoes made with water; 1/4 cup lentil beans; 1/4 c. yam; 4 cherry tomatoes cut; 4 oz. soy formula\nSnacks: 15 goldfish crackers and 1/4 c. canned fruit at 10 am; rice cake with 1/4 c. canned pears at 3 pm\nTotal calories = ~750\nProtein = 21 grams\n\nNutrients of concern in this diet include:","o":["calcium","vitamin B12","vitamin D","Iron","All of the above"],"a":4,"e":"Checked answer, not from an official key. With only 8 oz of soy formula and no other B12, calcium or vitamin D sources, all four are a concern."},{"q":"The mother of a 9-month-old vegetarian infant weighing 19 pounds (8.6 kg) provided the following diet history for her son.\nBreakfast: 1/4 cup oatmeal made with water; 1/2 banana; 4 oz. apple juice\nLunch: Rice cake with 1 t. peanut butter; 1/2 c. applesauce; 4 oz. soy formula\nDinner: 1/4 cup mashed potatoes made with water; 1/4 cup lentil beans; 1/4 c. yam; 4 cherry tomatoes cut; 4 oz. soy formula\nSnacks: 15 goldfish crackers and 1/4 c. canned fruit at 10 am; rice cake with 1/4 c. canned pears at 3 pm\nTotal calories = ~750\nProtein = 21 grams\n\nDoes this diet have an adequate amount of calories for a 9-month-old infant?","o":["Yes","No"],"a":1,"e":"Checked answer, not from an official key. 8.6 kg × 98 = about 843 Calories needed. 750 is short."},{"q":"The mother of a 9-month-old vegetarian infant weighing 19 pounds (8.6 kg) provided the following diet history for her son.\nBreakfast: 1/4 cup oatmeal made with water; 1/2 banana; 4 oz. apple juice\nLunch: Rice cake with 1 t. peanut butter; 1/2 c. applesauce; 4 oz. soy formula\nDinner: 1/4 cup mashed potatoes made with water; 1/4 cup lentil beans; 1/4 c. yam; 4 cherry tomatoes cut; 4 oz. soy formula\nSnacks: 15 goldfish crackers and 1/4 c. canned fruit at 10 am; rice cake with 1/4 c. canned pears at 3 pm\nTotal calories = ~750\nProtein = 21 grams\n\nDoes this diet have an adequate amount of protein for a 9-month-old infant?","o":["Yes","No"],"a":0,"e":"Checked answer, not from an official key. Babies 7–12 months need about 11 g of protein a day, and he gets 21 g."},{"q":"An infant with what special condition requires less energy than a healthy infant?","o":["Extremely low-birth-weight infant","Low-birth-weight infant","Infant with Down’s syndrome","Infant born with difficulty breathing","Infant born with PKU"],"a":2,"e":"Checked answer, not from an official key. The textbook lists babies with lower activity and slower growth, including Down syndrome, as needing fewer Calories. Preterm and lung conditions raise needs."},{"q":"What is the gestation-adjusted age for a 9-month-old infant born preterm (32 weeks)?","o":["6.5 months","7 months","8 months","8.5 months"],"a":1,"e":"Checked answer, not from an official key. Born 8 weeks (2 months) early, so 9 − 2 = 7 months."},{"q":"Which of the following foods would NOT be appropriate for a baby with galactosemia?","o":["Sugar solution","Apple juice","Soybean formula","Breast milk"],"a":3,"e":"Checked answer, not from an official key. Breast milk is rich in lactose, which contains galactose."},{"q":"Growth rates among infants that have the lung condition bronchopulmonary dysplasia (BPD) are slower due to all of the following EXCEPT:","o":["higher nutritional requirements.","more muscle mass.","changes in endocrine systems.","changes in pulmonary systems.","All of the above are reasons that these infants have slower growth rates."],"a":1,"e":"Checked answer, not from an official key. The textbook lists higher needs and changes in the endocrine and lung systems, not muscle mass."},{"q":"A gavage feeding is one that:","o":["provides nutrition directly through the central vein and includes amino acids, dextrose, and a lipid emulsion.","provides nutrition through a tube inserted into the stomach or small intestine.","provides slow feedings from the mouth or nose into the stomach through a tube.","provides oral nutrition that has been pureed thoroughly so the infant does not choke.","provides nutrition through the use of an oral syringe."],"a":2,"e":"Checked answer, not from an official key. The textbook describes gavage feeding as a tube from the mouth or nose to the stomach."},{"q":"Please read the case study below and use the information to answer questions 18-20.\n\nCase Study: Rebecca, an infant born at 32 weeks, weighed 1200 g (2.6 lb), and was SGA. Her head circumference was 30 cm (< 5th percentile). The mother was not interested in breastfeeding. A dietitian evaluated Rebecca and established appropriate growth and development goals for weight, length, head circumference, and body fat stores. A high-calorie formula (22 kcal/oz) was also initiated.\n\nWhat daily weight gain goal would the dietitian set for the first three months?","o":["10-25g/day","20-30 g/day","30-40 g/day",">40 g/day"],"a":1,"e":"Checked answer, not from an official key. Less certain: 20–30 g a day is a common goal for preterm babies after discharge, but the textbook text doesn't give the figure directly, so check this one against your graded result."},{"q":"Case Study: Rebecca, an infant born at 32 weeks, weighed 1200 g (2.6 lb), and was SGA. Her head circumference was 30 cm (< 5th percentile). The mother was not interested in breastfeeding. A dietitian evaluated Rebecca and established appropriate growth and development goals for weight, length, head circumference, and body fat stores. A high-calorie formula (22 kcal/oz) was also initiated.\n\nFollowing discharge from the hospital, Rebecca showed signs of fatigue during feeding. The dietitian then recommended a higher-calorie formula. How many Calories/ounce would the new formula most likely contain?","o":["40 Calories","24 Calories","30 Calories","35 Calories"],"a":1,"e":"Checked answer, not from an official key. Post-discharge formulas usually give 22 or 24 Calories an ounce, so the next step up is 24."},{"q":"Case Study: Rebecca, an infant born at 32 weeks, weighed 1200 g (2.6 lb), and was SGA. Her head circumference was 30 cm (< 5th percentile). The mother was not interested in breastfeeding. A dietitian evaluated Rebecca and established appropriate growth and development goals for weight, length, head circumference, and body fat stores. A high-calorie formula (22 kcal/oz) was also initiated.\n\nWill Rebecca be able to sit in a high chair and maintain a stable feeding position at 6 months — the same physical development expected from a term infant?","o":["Yes","No"],"a":1,"e":"Checked answer, not from an official key. Born 2 months early, at 6 months her corrected age is about 4 months, so she likely won't be ready yet."}]},{"n":6,"title":"Toddler and Preschooler Nutrition","kicker":"Build calm structure, check developmental fit, support the whole day","perStepChapter":true,"steps":[{"id":"l6-interactive-1","chapter":"One unfinished meal has several possible stories","title":"One unfinished meal has several possible stories","teach":["Toddlers are learning to move, communicate, choose and feed themselves; preschoolers increasingly participate in group meals. Feeding is therefore a developmental task as well as nutrient provision. Slower growth after infancy can accompany a smaller appetite, and acceptance varies across days. One unfinished meal does not establish deficiency or inadequate parenting.","Ask what changed around the time eating changed. Childcare, illness, uncomfortable stools, sleep, stress and meal timing are possibilities to explore, not diagnoses. Growth history and the whole pattern matter more than comparing siblings’ plates. Match expectations to chewing, swallowing, sensory and self-feeding skills as well as age."],"act":{"type":"explore","prompt":"Predict which question could change your interpretation of dinner refusal.","panels":[{"label":"A large snack just before dinner","text":"Ask about timing and the whole day. Dinner appetite may reflect earlier nourishment rather than a problem with the dinner food."},{"label":"No accessible food since lunch","text":"Ask about transport, childcare and food access. The response should address the long gap, not merely teach the family a stricter schedule."},{"label":"New discomfort during meals","text":"Clarify the symptoms and consider appropriate assessment. Pain or swallowing difficulty should not be treated as ordinary defiance."}]}},{"id":"l6-interactive-2","chapter":"Structure is not control of intake","title":"Structure is not control of intake","teach":["Adults provide suitable foods and predictable eating opportunities; children are supported in responding to hunger and fullness. Offer a familiar component, start with manageable amounts and allow more. Pressure, bargaining and rewards can intensify conflict. A flexible routine is not permission to withhold needed food when hunger, illness or individual care needs require adjustment.","Distinguish setting up a meal from controlling every bite. Seated snacks, manageable utensils and accessible foods provide structure; demanding five bites before play controls intake. Looking, touching or smelling can be food exploration without compulsory tasting. A calmer meal or greater participation can be a useful outcome even before the quantity eaten changes."],"act":{"type":"sort","prompt":"Place each action under supportive structure or pressure.","categories":["Supportive structure","Pressure or intake control"],"items":[{"label":"Offer a familiar food alongside other meal components.","category":0,"feedback":"This makes participation possible without requiring a specific amount to be eaten."},{"label":"Require five bites before outdoor play.","category":1,"feedback":"This turns play into leverage and disregards hunger and fullness."},{"label":"Provide a seated snack after childcare.","category":0,"feedback":"A predictable opportunity can address a real gap while remaining responsive."},{"label":"Praise a child only when the plate is empty.","category":1,"feedback":"This rewards intake rather than helping the child respond to their own cues."},{"label":"Allow smelling a new food without requiring a taste.","category":0,"feedback":"Exploration can build familiarity without coercion."}]}},{"id":"l6-interactive-3","chapter":"Count a beverage pattern without diagnosing","title":"Count a beverage pattern without diagnosing","teach":["The 12–24-month transition is not simply preschool advice with smaller portions. Breastfeeding may continue. For non-breastfed children in this age range, Canadian guidance recommends offering 500 mL homogenized 3.25% milk daily and limiting it to 750 mL so that it does not displace other foods. Breastfed children continue the infant vitamin D recommendation.","Ask about total volume, timing and drinking method before concluding that a child will not eat. A beverage can contribute nutrients while replacing opportunities for food. Arithmetic can identify a pattern worth discussing; it cannot diagnose iron deficiency. Plant beverages are not equivalent main milk replacements before age two, and medical or vegan feeding needs warrant qualified planning."],"act":{"type":"number","prompt":"In an illustrative record for a non-breastfed 20-month-old, milk servings are 250 mL, 200 mL and 300 mL. What is the daily total?","answer":750,"tolerance":0,"unit":"mL","explanation":"250 + 200 + 300 = 750 mL, the stated maximum rather than a target to aim for. Review the whole pattern and age-specific guidance; this does not diagnose a deficiency."}},{"id":"l6-interactive-4","chapter":"Choose nutrient roles, not “perfect” foods","title":"Choose nutrient roles, not “perfect” foods","teach":["Small appetites make nutrient-containing foods useful across meals and snacks. Iron, calcium, vitamin D and suitable fats deserve attention; fat is not an ingredient to eliminate from a young child’s diet. Familiar starches, iron-containing protein foods, produce and a source of fat can form a flexible meal-planning starting point.","Reference values concern total intake, not automatic supplement doses. Canadian calcium and iron RDAs are 700 mg and 7 mg at ages 1–3, and 1,000 mg and 10 mg at ages 4–8. From age one, vitamin D’s RDA is 600 IU total intake. Review supplements and food sources together instead of stacking products to chase each number."],"act":{"type":"explore","prompt":"Predict how each meal adjustment might help without pretending it creates a complete daily diet.","panels":[{"label":"Soft rice, mashed lentils, cooked tomato and vegetable oil","text":"This combines a familiar starch, an iron-containing protein food, produce and suitable fat. Check what the child actually accepts and can safely manage."},{"label":"A beverage labelled “milk” at age three","text":"Look beyond the name to protein, fortification and the whole pattern. Beverage labels do not guarantee nutritional equivalence."},{"label":"A parent wants a separate pill for every reference value","text":"Clarify total intake versus supplementation. Review actual foods and existing products with a qualified professional rather than automatically adding doses."}]}},{"id":"l6-interactive-5","chapter":"Safety has more than one route","title":"Safety has more than one route","teach":["Developmentally appropriate food shape and texture, upright seating and supervision help prevent choking. Whole grapes, whole nuts, popcorn, hard raw vegetables and thick spoonfuls of nut butter are examples of concerns. Ask how a snack is served: a food name alone does not describe whether its form is suitable for the child.","Foodborne prevention is a separate task: pasteurized products, safe cooking, clean handling and appropriate refrigeration matter. Allergy management also needs an explicit plan shared with responsible adults. Do not conduct challenges or remove multiple foods without assessment. A severe immediate reaction or breathing problem requires emergency care rather than a diary or routine appointment."],"act":{"type":"sort","prompt":"Match each action to the main safety problem it addresses.","categories":["Choking prevention","Foodborne-illness prevention","Allergy coordination"],"items":[{"label":"Seat and supervise a child while eating.","category":0,"feedback":"Position and supervision support safer eating; running with food in the mouth is unsafe."},{"label":"Refrigerate perishable foods promptly.","category":1,"feedback":"Storage reduces foodborne risk; it does not change a food’s choking shape."},{"label":"Share the existing allergy plan with childcare staff.","category":2,"feedback":"Responsible adults need a clear, verified plan; do not improvise a food challenge."},{"label":"Modify a hard food’s shape and texture.","category":0,"feedback":"Safe presentation depends on the child’s developmental skills."},{"label":"Keep raw meat and its juices separate from ready-to-eat foods during preparation.","category":1,"feedback":"Preparation hygiene addresses microbial risk independently of responsive feeding."}]}},{"id":"l6-interactive-6","chapter":"Map home, childcare and the journey between","title":"Map home, childcare and the journey between","teach":["The whole day may cross home, childcare and transport. Ask who provides breakfast, when lunch and snacks happen, whether containers are manageable and whether something familiar is available. Descriptive information is more useful than calling a child a good or bad eater. Shared routines work best when adults avoid shame and comparison.","Food access changes which suggestions are realistic. Ask privately whether food runs out and whether there is equipment, refrigeration, storage and time. Budget education cannot create income. Respectful support may mean connecting the family with resources or using familiar affordable foods rather than requiring speciality purchases. Keep movement and play separate from earning or compensating for food."],"act":{"type":"choice","prompt":"A family reports that the preschool lunchbox comes home full. Which first step gives you the most useful information?","options":[{"label":"Tell the family to buy expensive specialist snacks immediately.","correct":false,"feedback":"This assumes the problem and may add cost without improving access or participation."},{"label":"Ask staff to withhold play until the lunch is finished.","correct":false,"feedback":"This uses pressure and treats play as a reward for intake rather than addressing the feeding environment."},{"label":"Ask about the setting, timing, container access, familiar foods and the child’s experience before changing the menu.","correct":true,"feedback":"Correct. These details may explain the barrier and guide a realistic plan."}]}},{"id":"l6-interactive-7","chapter":"Run a small, respectful mealtime experiment","title":"Run a small, respectful mealtime experiment","teach":["A useful counselling goal names a feasible action and something to observe. If a child eats foods separately at home but rejects mixed dishes at childcare, investigate preferences and context before insisting on tasting. Serving the same components separately with one familiar item may make the meal more approachable without requiring special foods.","The experiment is not a guarantee of acceptance. Remove the pressure to taste, then observe comfort, participation and access rather than measuring success only in bites. Agree how caregivers and staff will review the change. If distress is extensive or swallowing is difficult, referral takes priority over repeatedly adjusting presentation or increasing pressure."],"act":{"type":"choice","prompt":"Which trial best fits a four-year-old who dislikes mixed dishes at childcare but eats the components at home?","options":[{"label":"Remove all mixed dishes permanently and promise the problem is solved.","correct":false,"feedback":"A limited experiment is more informative than an absolute rule or a guarantee; broader difficulty may need assessment."},{"label":"Offer separated components with a familiar item, remove the taste requirement and review comfort and participation with caregivers and staff.","correct":true,"feedback":"Correct. This tests a specific environmental adjustment without coercion or a guaranteed outcome."},{"label":"Hide every disliked ingredient and require a clean plate.","correct":false,"feedback":"This does not address the child’s experience and maintains pressure around intake."}]}},{"id":"l6-interactive-8","chapter":"Know when routine support is not enough","title":"Know when routine support is not enough","teach":["Ordinary selectivity is not interchangeable with a clinically significant feeding problem. Persistent pain, coughing or choking during meals, loss of accepted textures, dehydration, very limited intake or growth concerns warrants assessment. Apparent body size cannot rule out serious nutritional difficulty. Acute breathing difficulty, inability to swallow or marked lethargy needs urgent care.","Document what is observed and arrange appropriate medical, dietetic or feeding-team review rather than diagnosing from the number of accepted foods. A follow-up plan should name an action, who will do it and what triggers earlier help. Practical support can proceed alongside referral, but it must not delay the response to concerning symptoms."],"act":{"type":"sort","prompt":"Choose the level of response that each situation calls for.","categories":["Routine supportive exploration","Qualified assessment needed","Urgent care"],"items":[{"label":"One unfinished dinner, with no other concerns reported.","category":0,"feedback":"Explore the whole-day pattern and context; one meal does not establish deficiency."},{"label":"Repeated coughing and distress during meals.","category":1,"feedback":"Persistent swallowing or feeding concerns require qualified assessment rather than increased pressure."},{"label":"Loss of previously managed textures.","category":1,"feedback":"A change in feeding ability warrants review; do not assume ordinary preference alone."},{"label":"Acute inability to swallow or severe breathing difficulty.","category":2,"feedback":"Urgent care takes priority over routine nutrition counselling."}]}}],"flashcards":[],"quiz":[]},{"n":7,"title":"Child and Preadolescent Nutrition","kicker":"See the school day through the child’s eyes.","perStepChapter":true,"steps":[{"id":"l7-interactive-2","chapter":"The lunch that comes home","title":"The lunch that comes home","teach":["School-age children increasingly eat where caregivers cannot directly observe them. Lunch periods, clubs, transport, friends and advertising become part of the nutrition environment. Children also develop practical skills: opening packaging, choosing between foods, reading simple labels and helping prepare meals. The counsellor’s question expands from “What is served?” to “Can this child comfortably access and eat it?”","Canadian guidance recognizes childhood and adolescence as periods of growth and learning about food. Energy and nutrient adequacy remain central as children approach puberty. The food guide is a pattern to adapt, not a test that each meal must pass."],"act":{"type":"choice","prompt":"An eight-year-old brings lunch home and is very hungry after school. What should you explore first?","options":[{"label":"What happens during lunchtime, including time and containers?","correct":true,"feedback":"Yes. A usable eating opportunity depends on access, not just what was packed. Invite the child’s account before changing food."},{"label":"Whether removing the afternoon snack will increase motivation","correct":false,"feedback":"Withholding food does not solve an inaccessible lunch and ignores hunger. Investigate the school-day barrier first."},{"label":"Whether lunch looks balanced in a photograph","correct":false,"feedback":"A photograph cannot reveal a stuck lid, a short break or anxiety about asking for help."}]}},{"id":"l7-interactive-3","chapter":"Read the age band","title":"Read the age band","teach":["Children reach puberty at different times, so peers of the same age can vary in size and physical maturity. Do not use classmates or siblings as a growth standard. Activity should emphasize participation, skills and enjoyment rather than changing appearance.","Selected Canadian RDAs: ages 4–8: calcium 1,000 mg/day and iron 10 mg/day; ages 9–13: calcium 1,300 mg/day and iron 8 mg/day , for both male and female table categories. These describe total intake, not tablets. Vitamin D’s RDA is 600 IU, or 15 micrograms, daily across these ages."],"act":{"type":"number","prompt":"For a reference-table exercise, what is the calcium RDA for ages 9–13?","answer":1300,"tolerance":0,"unit":"mg/day","explanation":"1,300 mg/day describes total usual intake, not a calcium-tablet dose. The ages 4–8 value is 1,000 mg/day; birthdays do not create abrupt biological changes."}},{"id":"l7-interactive-5","chapter":"Time, tools, temperature and trust","title":"Time, tools, temperature and trust","teach":["Involving children in planning and packing lunches can improve practical food skills and help identify foods they will use. School meals can reflect taste, culture and budget.","A useful original checklist is time, tools, temperature and trust . Time: how long is available after lining up? Tools: can the child manage the lid and utensils? Temperature: can perishables stay cold or hot food stay hot? Trust: can the child report an unpleasant experience without being punished for waste?"],"act":{"type":"sort","prompt":"Match the observation to the most directly relevant next conversation.","categories":["Usable lunch access","Food safety","Dignity and trust"],"items":[{"label":"A jar lid is too tight.","category":0,"feedback":"Try a container the child can open; more food knowledge will not loosen a lid."},{"label":"A perishable lunch has no cooling arrangement.","category":1,"feedback":"Discuss an insulated bag and ice pack, alongside school requirements."},{"label":"Classmates mock a cultural food.","category":2,"feedback":"Ask what the child wants; involve appropriate school support with permission rather than automatically removing the food."},{"label":"Most of the break is spent queuing.","category":0,"feedback":"Explore usable eating time rather than blaming appetite."}]}},{"id":"l7-interactive-6","chapter":"Spot the persuasive message","title":"Spot the persuasive message","teach":["Children encounter marketing through characters, games, prizes and digital media. Their developmental stage can make persuasive intent difficult to recognize. Supporting media literacy and reducing exposure are complementary approaches.","Original activity: compare two fictional cereal packages. One has a superhero and “power breakfast” slogan; the other is plain. Ask which information is an advertisement and which is a nutrition fact. Then ask whether either package reveals cost, taste, cultural fit or whether the child can actually access it. The exercise should build curiosity, not teach shame about enjoying a branded product."],"act":{"type":"explore","prompt":"Predict which feature tells you about nutrition, which is advertising, and what is missing. Then open the panels.","panels":[{"label":"Superhero and “power breakfast”","text":"These are persuasive features. Enjoying a branded cereal is not a moral failure, but its character does not establish nutrient content."},{"label":"Nutrition information","text":"Actual nutrition information answers specific composition questions. It does not establish whether a child’s whole pattern is adequate."},{"label":"The unseen school day","text":"Neither package reveals affordability, whether the child likes the food or whether there is time to eat. Ask about these conditions too."}]}},{"id":"l7-interactive-7","chapter":"Respond without making thinness the goal","title":"Respond without making thinness the goal","teach":["Preadolescents may start comparing bodies before adults expect it. Respond to comments with curiosity rather than a diet. “What happened that made you think you should eat less?” can uncover teasing, a video or a misunderstood classroom lesson. Do not reassure solely by saying a child is thin; that still makes thinness the condition for being acceptable.","Canadian paediatric advice discourages dieting and appearance-focused commentary, emphasizing supportive conversations and a varied eating pattern. Weight-related bullying and preoccupation with food or body shape deserve attention."],"act":{"type":"choice","prompt":"A preteen says, “My teammates skip bread to get faster.” Which reply protects nourishment and dignity?","options":[{"label":"You are already thin, so you do not need to diet.","correct":false,"feedback":"This makes thinness the condition for reassurance and leaves the team message unexamined."},{"label":"What have you heard, and how is it affecting eating? Growing bodies need reliable food.","correct":true,"feedback":"Yes. Explore the message without endorsing restriction; arrange clinical assessment if restriction or symptoms persist."},{"label":"Try avoiding bread only on rest days.","correct":false,"feedback":"This endorses compensatory restriction. Food does not have to be earned through activity."}]}},{"id":"l7-interactive-8","chapter":"Support activity without a product shortcut","title":"Support activity without a product shortcut","teach":["For ordinary play and routine activity, water is generally appropriate. Sports drinks and caffeinated energy drinks are different products; energy drinks are not a hydration strategy for children. Longer, vigorous activity and extreme conditions may require an individualized plan.","Original logistics exercise: for an after-school activity, identify where a snack can be stored, when it can be eaten and what meal follows. A sandwich portion and fruit may be more useful than buying a performance product. Ask whether transport costs or equipment fees are competing with the food budget. Do not suggest that food must be reduced on rest days to compensate for less movement."],"act":{"type":"explore","prompt":"Predict the first useful question in each situation before opening its panel.","panels":[{"label":"After-school practice","text":"Where can a snack be stored and when can it be eaten? Map the travel gap and meal afterward before recommending products."},{"label":"An energy drink advertisement","text":"Water generally suits ordinary activity. Caffeinated energy drinks are not child hydration strategies; demanding or prolonged conditions may need individualized planning."},{"label":"A vegan family pattern","text":"Clarify exclusions and reliable nutrient sources, especially B12. Respect the choice and seek dietetic planning when needed rather than assuming either deficiency or adequacy."}]}},{"id":"l7-interactive-9","chapter":"Support, assessment or urgent help?","title":"Support, assessment or urgent help?","teach":["A counsellor can identify barriers, support food skills and facilitate referral. They should not diagnose nutritional deficiency, interpret growth in isolation or independently treat an eating disorder. Rapid or unexplained weight change, growth faltering, persistent food avoidance and delayed puberty warrant medical assessment regardless of apparent body size.","Ask about pain, swallowing, fatigue, stool concerns, medication effects and distress without assuming one cause. Severe dehydration, fainting with illness or acute breathing problems require urgent clinical attention. A child repeatedly unable to eat should not be left with only a motivational worksheet."],"act":{"type":"sort","prompt":"Sort by the response warranted—not by a diagnosis.","categories":["Practical support within role","Clinical assessment","Urgent clinical attention"],"items":[{"label":"A child cannot open a container; no symptoms are reported.","category":0,"feedback":"Change the container and review whether access improves."},{"label":"Persistent food avoidance and growth concerns are reported.","category":1,"feedback":"These require qualified assessment; do not interpret growth in isolation."},{"label":"A child has acute breathing difficulty.","category":2,"feedback":"Seek emergency assistance rather than continuing food counselling."},{"label":"The household sometimes runs out of food.","category":0,"feedback":"Ask which practical access supports are acceptable; do not require proof of healthy choices."}]}}],"flashcards":[],"quiz":[]},{"n":8,"title":"Adolescent Nutrition","kicker":"Build autonomy without leaving young people unsupported.","perStepChapter":true,"steps":[{"id":"l8-interactive-2","chapter":"Start with the teen’s agenda","title":"Start with the teen’s agenda","teach":["Adolescence combines physical development with increasing independence. A young person may make more food decisions while still depending on adults for groceries, transport, money and permission to use a kitchen. School, employment, sports, relationships and online communities can all shape eating. Good counselling therefore asks what a teenager wants help with and what their day actually permits.","Start with an open invitation: “What would make eating easier for you?” Possible goals include feeling less rushed, having food before practice, learning a low-cost meal or reducing conflict at home. Do not assume the desired goal is weight change. Explain the purpose of questions before asking about sensitive topics."],"act":{"type":"choice","prompt":"A teenager attends because a caregiver booked the appointment. Which opening creates meaningful choice?","options":[{"label":"Which body changes would you like this plan to produce?","correct":false,"feedback":"This assumes an appearance goal the teenager has not chosen."},{"label":"What would make eating easier? We can discuss your day or one difficult situation.","correct":true,"feedback":"Yes. Offer a real role in the conversation while leaving room for practical support."},{"label":"Everything you say will remain secret in all circumstances.","correct":false,"feedback":"Do not promise absolute secrecy. Explain privacy and its limits accurately within your service."}]}},{"id":"l8-interactive-3","chapter":"Enough food before optimization","title":"Enough food before optimization","teach":["A varied eating pattern needs to provide enough food for development and ordinary living as well as activity. A visually impressive salad is not proof of sufficient energy. Nor does a large body exclude undernutrition. Before discussing supplements or detailed nutrient targets, identify missed meals, long gaps and unavailable food.","Original assessment prompts: What happens between school and work? Is there food after evening practice? Are lunch breaks usable? Does nausea, pain, medication or anxiety interfere with eating? Are foods avoided for taste, culture, ethics, allergy, cost or fear? Distinguish a preference from an inability to access food and from distress that requires clinical review."],"act":{"type":"explore","prompt":"Predict why the same “meal prep” advice might fail in these situations. Open the panels to compare.","panels":[{"label":"School to paid work","text":"Prepared food may never be eaten without a usable break or storage. Map the actual gap and agree on a feasible opportunity."},{"label":"An impressive salad","text":"Appearance does not establish adequate overall food. Ask about the whole pattern and missed opportunities rather than praising a photograph."},{"label":"Groceries run out","text":"The missing ingredient may be access, not planning skill. Discuss acceptable support without making a teenager responsible for household finances."}]}},{"id":"l8-interactive-4","chapter":"Reference value or pill dose?","title":"Reference value or pill dose?","teach":["For ages 14–18 , Canadian RDAs include calcium 1,300 mg/day , and iron 11 mg/day in the male table category and 15 mg/day in the female category . These are reference categories, not a complete individualized assessment. Vitamin D’s RDA is 15 micrograms (600 IU) daily .","The reference values describe total usual intake, not doses to add automatically. Clinicians should consider menstrual losses, growth, medical conditions and individual physiology, including the needs of transgender and gender-diverse adolescents, without using table labels to invalidate identity."],"act":{"type":"number","prompt":"In the supplied reference values for ages 14–18, what is the calcium RDA?","answer":1300,"tolerance":0,"unit":"mg/day","explanation":"1,300 mg/day refers to total usual intake. It is not an instruction to add a 1,300 mg supplement. Individual assessment considers growth, health and relevant context."}},{"id":"l8-interactive-5","chapter":"Understand the choice before advising","title":"Understand the choice before advising","teach":["A well-planned vegetarian pattern can meet young people’s needs. A vegan pattern requires reliable vitamin B12 sources and attention to energy, protein, iron, calcium and other nutrients. A registered dietitian can help translate the pattern into affordable, usable meals.","Ask what a label means in practice: does “plant-based” describe adding beans, excluding animal foods or eating only a few products? Respect ethical motivations. At the same time, ask neutrally whether foods are increasingly feared or rules are multiplying. Neither dismissing a vegetarian choice nor automatically declaring it nutritionally complete is good assessment."],"act":{"type":"sort","prompt":"Route each statement toward the most useful next step.","categories":["Clarify foods and adequacy","Review product safety","Arrange clinical assessment"],"items":[{"label":"“I am vegan for ethical reasons and need affordable meals.”","category":0,"feedback":"Respect the motivation; clarify available foods and arrange dietetic help for reliable B12 and overall adequacy."},{"label":"“My pre-workout has ingredients I cannot identify.”","category":1,"feedback":"Record the product, amount, frequency and other supplements; refer uncertainty to a pharmacist or clinician."},{"label":"“I keep adding forbidden foods because eating frightens me.”","category":2,"feedback":"Escalating fear and restriction warrant assessment, not merely a new menu."},{"label":"“Plant-based means I sometimes add beans.”","category":0,"feedback":"Labels describe different patterns. Ask what is actually included and excluded."}]}},{"id":"l8-interactive-6","chapter":"The athlete’s missing lunch","title":"The athlete’s missing lunch","teach":["Distinguish ordinary activity from intensive training. Water generally suits routine activity; sports drinks may have a role in specific prolonged or demanding conditions, but caffeinated energy drinks are different and are not a substitute for hydration or food.","Original planning exercise: place training on the weekly school timetable, then mark meals, snacks, travel and recovery time. Look for practical gaps rather than prescribing a universal athlete menu. A teenager travelling directly from school to practice might need food packed before leaving home and an accessible meal afterward. An athlete with repeated injuries, persistent fatigue or menstrual change needs assessment, not a stronger pre-workout product."],"act":{"type":"choice","prompt":"A sixteen-year-old skips lunch before practice, uses energy drinks and reports dizziness. What is the safest first response?","options":[{"label":"Diagnose low iron and recommend iron tablets.","correct":false,"feedback":"Dizziness does not establish iron deficiency. Do not diagnose or prescribe from this account."},{"label":"Replace the energy drink with a stronger pre-workout.","correct":false,"feedback":"A stimulant neither addresses missed food nor explains symptoms. Product escalation delays care."},{"label":"Address symptoms and arrange timely medical assessment, urgently if severe or acute.","correct":true,"feedback":"Yes. Once safety is addressed, collaboratively map lunch access, travel and food opportunities rather than weight loss."}]}},{"id":"l8-interactive-7","chapter":"Separate the promise from the pressure","title":"Separate the promise from the pressure","teach":["Dieting during adolescence can harm physical and psychological health. Weight bias and messages from family, peers, sport and media can shape food restriction. Canadian paediatric guidance supports moving away from weight-focused messaging toward sustainable health behaviours and supportive assessment.","Original conversation practice: when a teen says, “I need to be smaller,” ask what they hope would change. The answer may involve bullying, selection for a team, clothing fit or feeling accepted. Acknowledge the experience without endorsing a restrictive plan. “You deserve to feel comfortable and supported; we can work on the eating difficulties and get help with the pressure” is more useful than debating whether they look thin enough."],"act":{"type":"explore","prompt":"Predict what each message leaves out before revealing the response.","panels":[{"label":"“Look like this influencer”","text":"An image is not evidence for a nutrition claim. Ask who benefits and whether the advice requires ignoring hunger or buying a product."},{"label":"“You must be smaller to belong”","text":"Explore teasing, team pressure or hoped-for acceptance without endorsing restriction. Support eating rather than debating whether the teen looks thin enough."},{"label":"“Everyone on the team does it”","text":"Popularity does not establish safety. Ask how the rule affects food, distress and symptoms; facilitate appropriate support."}]}},{"id":"l8-interactive-9","chapter":"Do not wait for a visibly low weight","title":"Do not wait for a visibly low weight","teach":["Eating disorders can occur at any body size. Persistent restriction, purging, rapid weight change, medical symptoms or major distress need timely clinical assessment. A generic meal plan is not eating-disorder treatment.","Seek urgent medical help for acute concerns such as fainting, chest pain, confusion, severe dehydration or inability to maintain intake. Do not wait for a visibly low weight. Ask about safety within professional competence and follow local safeguarding procedures. Where serious restriction is suspected, do not prescribe an unsupervised refeeding regimen or interpret laboratory results without qualified care."],"act":{"type":"sort","prompt":"Choose the appropriate response from the information provided.","categories":["Practical planning","Timely clinical assessment","Urgent medical help"],"items":[{"label":"A teen needs lunch storage; no symptoms or restriction are reported.","category":0,"feedback":"Support a safe, usable eating opportunity and review it."},{"label":"Persistent restriction and major distress are reported.","category":1,"feedback":"Eating disorders can occur at any size. A generic meal plan is not treatment."},{"label":"A teen reports chest pain or confusion.","category":2,"feedback":"Seek urgent medical help rather than continuing routine nutrition education."},{"label":"Ongoing menstrual changes or unexplained fatigue are reported.","category":1,"feedback":"These have multiple possible causes and warrant review, not a guessed deficiency."}]}}],"flashcards":[],"quiz":[]},{"n":9,"title":"Adult Nutrition","kicker":"Turn nutrition knowledge into a workable everyday plan.","perStepChapter":true,"steps":[{"id":"l9-interactive-2","chapter":"Two different adequacy questions","title":"Two different adequacy questions","teach":["Energy adequacy and nutrient adequacy are different questions. Energy supplies fuel; nutrients support body functions. An eating pattern can provide enough energy while lacking certain nutrients, or contain nutritious foods while providing insufficient food overall. Canada's dietary guidance explicitly recognizes individual variation in energy needs and cautions that restrictive fad diets may pose nutritional risks.","In a learning assessment, avoid jumping from a body-size description to a conclusion about intake. A person in any body size may skip meals or have a limited diet. Ask what happens on ordinary workdays and days off. The goal is to understand a pattern, not judge a single photograph or food choice."],"act":{"type":"explore","prompt":"Predict why neither body size nor a meal photograph can settle adequacy. Then open each distinction.","panels":[{"label":"Enough energy?","text":"Ask about overall amounts and usable eating opportunities. Food can look nutritious without supplying enough across the day."},{"label":"Enough nutrients?","text":"A pattern may supply sufficient energy while lacking particular nutrients. Variety, reliable sources and usual intake matter."},{"label":"Enough context?","text":"Work, access, health, reproductive life stage and personal priorities shape the assessment. Body size alone does not establish intake."}]}},{"id":"l9-interactive-3","chapter":"Do not make every number a target","title":"Do not make every number a target","teach":["Dietary Reference Intakes describe requirements for healthy populations by life stage and reference categories. An RDA is intended to cover nearly all healthy people in its group. An AI is used when evidence cannot establish an RDA. The EAR estimates the requirement of half a healthy group; the UL is an upper boundary, not an optimal intake goal.","None of these values diagnoses a person’s deficiency. A total-intake reference is not automatically a supplement dose, and one day below an RDA does not establish deficiency. Consider usual intake and clinical context; specialized needs require qualified assessment."],"act":{"type":"sort","prompt":"Match the reference with its correct interpretation.","categories":["Intake reference","Group requirement estimate","Upper boundary, not a goal"],"items":[{"label":"RDA: covers nearly all healthy people in a defined group.","category":0,"feedback":"It describes average daily intake, not automatically an extra supplement dose."},{"label":"AI: used when evidence cannot establish an RDA.","category":0,"feedback":"It has a different evidentiary basis; it is not a diagnosis."},{"label":"EAR: estimated requirement of half a healthy group.","category":1,"feedback":"Do not use it as a universal individual target."},{"label":"UL: an upper intake boundary associated with low risk.","category":2,"feedback":"Higher is not automatically better; this is not an optimum to aim for."}]}},{"id":"l9-interactive-4","chapter":"Keep the meal; adapt the pattern","title":"Keep the meal; adapt the pattern","teach":["Canada's Food Guide encourages vegetables and fruit, whole grains and protein foods, with plant proteins chosen more often; water is the preferred beverage. It also emphasizes cooking, enjoyment, awareness and eating with others. This is a pattern, not a moral ranking of people or a ban on celebration foods.","The plate illustration uses approximately half vegetables and fruit, one-quarter whole grains and one-quarter protein foods. It depicts proportions, not an individualized portion prescription. A bowl, stew or shared platter can express the same principle. Frozen, canned and dried foods can fit."],"act":{"type":"choice","prompt":"A person enjoys rice and chickpeas and wants an affordable addition. Which response best applies the food guide?","options":[{"label":"Replace the meal with an unfamiliar diet-branded product.","correct":false,"feedback":"A product is not required. Start with food the person enjoys and can access."},{"label":"Explore adding acceptable frozen spinach or tomatoes, considering cost and preference.","correct":true,"feedback":"Yes. A familiar mixed dish can express a flexible pattern without becoming a rigid portion prescription."},{"label":"Require every snack to match the plate illustration exactly.","correct":false,"feedback":"The illustration represents a pattern, not a requirement that every snack be perfectly divided."}]}},{"id":"l9-interactive-5","chapter":"Calculate, then state the limit","title":"Calculate, then state the limit","teach":["Carbohydrate, protein and fat are all relevant to a varied diet. Canada's reference tables list adult macronutrient distribution ranges rather than requiring a single universal ratio: carbohydrate 45–65%, fat 20–35% and protein 10–35% of energy. The adult protein RDA is 0.8 g/kg/day for healthy adults; it is not a treatment prescription or proof that every person benefits from the same intake.","For study, connect foods to overlapping contributions rather than exclusive boxes. Beans offer protein and fibre; nuts provide fat and protein; yogurt can contribute protein and calcium. “Protein food” does not mean a food contains only protein. Likewise, evaluating fat involves food sources and the broader pattern, not simply avoiding every food with fat."],"act":{"type":"number","prompt":"For a learning example, apply the healthy-adult protein RDA of 0.8 g/kg/day to a fictional 70 kg adult. What is the result?","answer":56,"tolerance":0,"unit":"g/day","explanation":"70 × 0.8 = 56 g/day. This demonstrates a reference calculation, not an individualized prescription for someone with illness or specialized needs."}},{"id":"l9-interactive-6","chapter":"Ask without diagnosing","title":"Ask without diagnosing","teach":["Vitamin B12: animal-source and fortified foods provide dependable sources. A vegan pattern needs intentional reliable provision. Certain medicines or absorption conditions can complicate status; changing food alone may not address a clinical deficiency.","Vitamin D: Health Canada advises people aged 2–50 to eat vitamin-D-containing foods daily or take 400 IU (10 micrograms) daily. For those 51 and older, it recommends a daily 400 IU supplement as well as vitamin-D-containing foods. This public-health supplement advice is distinct from a total-intake reference value or treatment dose."],"act":{"type":"explore","prompt":"Predict the safe next question in each case, then open the panel.","panels":[{"label":"Fatigue and iron","text":"Ask about reported symptoms and encourage appropriate assessment. Fatigue does not establish iron deficiency or justify treatment-dose iron."},{"label":"A vegan pattern","text":"Ask about dependable B12 sources and the whole pattern. Review actual fortified-food labels; not all plant beverages are equivalent."},{"label":"Vitamin D already in use","text":"Clarify existing products and clinical advice. Public-health supplement advice differs from total-intake references and deficiency treatment."}]}},{"id":"l9-interactive-8","chapter":"Access is not motivation","title":"Access is not motivation","teach":["Food insecurity refers to inadequate or uncertain food access because of financial constraints. It is not equivalent to poor cooking knowledge. Canadian research links it with household financial circumstances and adverse health outcomes.","Ask permission before discussing money: “Would it help to consider food cost or access?” Also ask about transport, a refrigerator, a usable kitchen and time. Suggesting bulk purchases to someone without storage can increase waste. Suggesting daily fresh shopping to a shift worker can create another impossible job. With consent, help identify practical community or income-support pathways without promising eligibility or treating emergency food aid as a complete solution."],"act":{"type":"sort","prompt":"Match the obstacle to a response that addresses it.","categories":["Practical environment support","Accessible food education","Consent-based resource navigation"],"items":[{"label":"No refrigerator is available at work.","category":0,"feedback":"The plan must fit safe storage and the work environment."},{"label":"Someone wants help reading a fortified beverage label.","category":1,"feedback":"Teach the relevant comparison using actual products and personal priorities."},{"label":"There is not enough money for food.","category":2,"feedback":"Ask permission to explore acceptable community or income-support pathways; budgeting does not fix inadequate income."},{"label":"Bulk buying is suggested without storage space.","category":0,"feedback":"Adapt to real storage and transport rather than interpreting difficulty as low motivation."}]}},{"id":"l9-interactive-10","chapter":"Design the shift-work experiment","title":"Design the shift-work experiment","teach":["Mina, 34, reports missing lunch, then arriving home extremely hungry. She asks for a strict meal plan but has unpredictable breaks and no microwave. First clarify whether she wants more structure, fewer decisions or help with symptoms. Ask about refrigeration, food access and any medical issues; do not assume her difficulty is discipline.","An original agreed experiment could be assembling a suitable cold meal on two shifts, using foods she already likes and can store safely. A second option is an accessible snack when a full meal break is delayed. Let Mina select the feasible option. Review practicality and satisfaction rather than grading perfection. Persistent dizziness, marked fatigue or unexplained weight changes warrant medical review; meal planning is not a diagnostic test."],"act":{"type":"choice","prompt":"Mina has unpredictable breaks and no microwave. Which first experiment fits?","options":[{"label":"A strict hot-meal timetable regardless of breaks","correct":false,"feedback":"This adds structure on paper while ignoring why eating is difficult."},{"label":"A macronutrient spreadsheet before discussing access","correct":false,"feedback":"Calculations do not create a break or a safe place to store food."},{"label":"Let Mina choose a safely stored cold meal or accessible snack trial on two shifts.","correct":true,"feedback":"Yes. Clarify her goal and storage first; review practicality and satisfaction, not perfection."}]}}],"flashcards":[],"quiz":[]},{"n":10,"title":"Nutrition and Older Adults","kicker":"Protect nourishment, function and choice in older adulthood.","perStepChapter":true,"steps":[{"id":"l10-interactive-2","chapter":"Find the difficult step","title":"Find the difficult step","teach":["Older adulthood includes people with very different abilities, health conditions, living arrangements and goals. Someone may travel independently at 85 while another person needs substantial support at 65. Ask what matters: preparing breakfast, recovering after hospitalization, enjoying family meals or maintaining enough strength to shop. Nutrition is part of functioning and quality of life, not merely a list of nutrients.","Age-related changes can affect appetite, taste, smell, thirst and the practical ability to buy or prepare food. Medicines, reduced income, living alone and changes in the home environment can also influence eating. These factors require individual questions, not assumptions that all older adults are frail or forgetful."],"act":{"type":"choice","prompt":"An older adult says, “I do not eat much.” What is the most useful opening?","options":[{"label":"Everyone needs less food as they get older.","correct":false,"feedback":"Age does not explain the difficulty. This risks normalizing inadequate intake."},{"label":"Which part of eating is easiest, and which takes the most effort?","correct":true,"feedback":"Yes. Separate shopping, opening, cooking, chewing, swallowing and enjoyment before selecting an intervention."},{"label":"Ask the adult child to answer everything.","correct":false,"feedback":"Address the older person directly and ask whom they want involved. Age does not remove autonomy."}]}},{"id":"l10-interactive-3","chapter":"Nutritious is not the same as enough","title":"Nutritious is not the same as enough","teach":["Some older adults need less energy as activity and body composition change, while nutrient requirements remain important. Others need additional support because illness or recovery makes adequate eating difficult. Avoid the blanket instruction to eat less because of age. The practical question is whether the person can obtain enough food and nutrients for their situation.","The National Institute on Aging encourages nutrient-dense variety and protein foods across the day, including options such as legumes, fish, dairy or fortified soy products."],"act":{"type":"explore","prompt":"Predict why each apparently sensible plan might fail, then open its explanation.","panels":[{"label":"A large low-energy meal","text":"Someone with a small appetite may not manage enough. Ask whether the food is nutritious and whether sufficient food is actually eaten."},{"label":"An automatic “eat less” rule","text":"Some people have lower energy needs; others struggle during illness or recovery. Age alone does not prescribe restriction."},{"label":"An elaborate daily menu","text":"A menu can demand more effort than someone can sustain. Practical effort and enjoyment belong in the plan."}]}},{"id":"l10-interactive-4","chapter":"Observe function; do not assign a diagnosis","title":"Observe function; do not assign a diagnosis","teach":["Sarcopenia is a muscle condition, not simply looking thin. The European consensus emphasizes low strength, confirms the condition with reduced muscle quantity or quality, and uses poor physical performance to indicate severity. It can occur before older adulthood. Screening and diagnosis require appropriate assessment; a counsellor should not label someone from age, body size or a single observation.","A useful counselling distinction is body weight versus function . Stable weight does not prove stable muscle function. Ask about changes in carrying groceries or rising from a chair as conversation prompts, not as a substitute for standardized testing. New weakness or deteriorating function deserves clinical evaluation."],"act":{"type":"sort","prompt":"Sort each action by its role.","categories":["Appropriate observation or support","Clinical assessment needed","Unsupported conclusion"],"items":[{"label":"Ask about a change in carrying groceries.","category":0,"feedback":"This is a conversation prompt, not a substitute for standardized assessment."},{"label":"Arrange evaluation for new weakness.","category":1,"feedback":"Functional decline needs assessment, not an automatic supplement."},{"label":"Declare sarcopenia because someone looks thin.","category":2,"feedback":"Sarcopenia is not diagnosed from appearance or age."},{"label":"Explore acceptable protein foods at different meals.","category":0,"feedback":"Support an achievable pattern while individualized clinical targets remain with qualified professionals."}]}},{"id":"l10-interactive-5","chapter":"A supplement does not replace assessment","title":"A supplement does not replace assessment","teach":["Health Canada's public advice for people aged 51 and older is a daily supplement providing 400 IU (10 micrograms) of vitamin D , alongside vitamin-D-containing foods. Do not confuse this supplement recommendation with the total-intake RDA or a clinical deficiency-treatment regimen. Provincial or condition-specific recommendations can differ; review individual advice with the person's clinician or pharmacist.","Calcium-containing foods and adequate overall eating remain relevant; a vitamin-D pill does not replace meals. If someone avoids dairy, investigate suitable fortified alternatives rather than assuming every plant beverage contains equivalent nutrients. Read the label for the actual product."],"act":{"type":"explore","prompt":"Predict what to clarify before recommending another product.","panels":[{"label":"Vitamin D in the cupboard","text":"Ask what is taken and what advice is in place. Public-health supplement advice differs from a total-intake RDA or treatment regimen."},{"label":"Avoiding dairy","text":"Check actual calcium-containing or fortified alternatives rather than assuming all plant beverages contribute the same nutrients."},{"label":"Memory changes and B12","text":"Do not label memory changes as B12 deficiency or promise a cure. Suspected deficiency or neurological symptoms require clinical assessment."}]}},{"id":"l10-interactive-6","chapter":"Hydration within the existing care plan","title":"Hydration within the existing care plan","teach":["Thirst may become less reliable with age. Regular opportunities to drink can help, and fluids may come from beverages and foods. Québec guidance recommends gradual fibre increases and regular fluids rather than relying entirely on thirst.","This does not justify a universal instruction to drink a fixed large volume. Kidney disease, heart conditions and prescribed fluid restrictions require clinical coordination. Ask what advice the person already follows. Practical barriers also matter: a heavy jug, fear of bathroom access or inability to open a bottle will not disappear after a lecture about hydration."],"act":{"type":"choice","prompt":"A person finds their jug heavy and reports a prescribed fluid restriction. Which response fits your role?","options":[{"label":"Recommend a fixed large daily water volume.","correct":false,"feedback":"A universal volume may conflict with existing care. Clarify restrictions with the treating team."},{"label":"Stop the restriction because thirst becomes less reliable.","correct":false,"feedback":"Do not override clinical instructions. General knowledge about thirst is not authority to alter treatment."},{"label":"Clarify existing advice and explore a manageable cup within that plan.","correct":true,"feedback":"Yes. Address the physical barrier without changing prescribed limits; review whether the arrangement helps."}]}},{"id":"l10-interactive-7","chapter":"Chewing is not swallowing safety","title":"Chewing is not swallowing safety","teach":["Dental pain, poorly fitting dentures, dry mouth and swallowing difficulty are different problems. A person who has trouble chewing may tolerate a softer preparation; a person with swallowing impairment needs appropriate assessment. Coughing during meals, wet-sounding voice after swallowing or food seeming stuck are reasons to seek swallowing evaluation, not invitations to improvise thickened fluids.","Do not automatically purée everything because someone is older. Unwanted texture changes may reduce enjoyment and intake, and texture safety is individual. Follow an assessed plan when one exists, and clarify uncertainty with the treating team. Acute choking or breathing difficulty requires emergency assistance, not a routine nutrition appointment."],"act":{"type":"sort","prompt":"Choose the response supported by each observation.","categories":["Appropriate professional review","Follow assessed plan; clarify uncertainty","Emergency assistance"],"items":[{"label":"Coughing during meals or wet-sounding voice after swallowing.","category":0,"feedback":"Seek prompt swallowing evaluation. Do not improvise thickened fluids or texture prescriptions."},{"label":"An existing swallowing plan is unclear to family.","category":1,"feedback":"Clarify with the treating team and follow the assessed plan rather than guessing."},{"label":"Acute choking with breathing difficulty.","category":2,"feedback":"Get emergency assistance immediately, not a routine nutrition appointment."},{"label":"Poorly fitting dentures cause chewing pain.","category":0,"feedback":"Dental review addresses a different problem from swallowing assessment; do not automatically purée everything."}]}},{"id":"l10-interactive-10","chapter":"Nourishment after bereavement","title":"Nourishment after bereavement","teach":["Sam, 78, says cooking for one feels pointless and clothes are becoming loose. Do not praise the apparent weight loss. Ask about appetite, access, grief, meal routines and the change over time, and encourage timely clinical review for unintentional loss. Offer support without attempting grief psychotherapy outside your training.","Sam chooses a simple evening meal using familiar ingredients and wants to invite a neighbour once a week. Another person might prefer delivered meals or telephone company; there is no mandatory social solution. Discuss whether an existing family helper can assist, with Sam's consent. At follow-up, ask whether meals were eaten and enjoyed, whether shopping is manageable and whether clinical follow-up occurred. The aim is not merely a completed recipe sheet."],"act":{"type":"choice","prompt":"Sam says cooking feels pointless and clothes have become loose. What is the best combined response?","options":[{"label":"Praise the weight loss and give a low-energy plan.","correct":false,"feedback":"Unintentional loss should not be praised or met with restriction. It needs clinical attention."},{"label":"Acknowledge the difficulty, encourage timely clinical review and ask which practical meal support Sam wants.","correct":true,"feedback":"Yes. Combine assessment with chosen support such as a familiar meal, delivery or company; do not impose a social solution."},{"label":"Treat the grief yourself before discussing food.","correct":false,"feedback":"Offer empathy, but do not provide psychotherapy beyond your training or delay assessment of intake changes."}]}}],"flashcards":[],"quiz":[]},{"n":11,"title":"The Counselling Relationship","kicker":"Lesson 11 of your course, built from Chapter 1 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l11-b1","chapter":"Counselling and education","title":"Counselling and education","teach":["Nutrition education and nutrition counselling share the same aim: helping people choose foods that support their health. The difference is who the work is shaped around. Nutrition education is designed around the needs of a group or community. Nutrition counselling is shaped around one client and is built on a working partnership between the counsellor and that client.","In counselling, you pay attention to the client's experience, feelings, thoughts and behaviour, and you respond on purpose: to acknowledge, to explore or to gently challenge. Your job is to increase knowledge, influence motivation and help the client build the skills they need to change how they eat."],"act":{"type":"choice","prompt":"A Nutritionist runs a six-week cooking class for a community centre. Which kind of work is this mainly?","options":[{"label":"Nutrition education","correct":true,"feedback":"Yes. The class is planned around the needs of a group, which is what makes it education."},{"label":"Nutrition counselling","correct":false,"feedback":"Counselling is shaped around one client and their own goals. A class for a community is education."},{"label":"Neither","correct":false,"feedback":"It is nutrition education: learning experiences planned for a group."}]}},{"id":"l11-b2","chapter":"What shapes food choices","title":"What shapes food choices","teach":["Before you can help someone change, you need to understand why they eat the way they do. Many forces pull on food choices at once, and they often compete. Taste is generally seen as the strongest one. Taste preferences can change with age, a move or illness, which is good news for anyone trying to change their diet.","Other influences include habit, health concerns, nutrition knowledge, convenience and time, culture and religion, the people we eat with, advertising and what is around us, money and access, how much variety is on offer, and stress or mood. People with more nutrition knowledge tend to eat better and lose more weight in weight-loss programs, so teaching still matters. Advice also lands better when it stresses that healthy food tastes good and is easy to fit in."],"act":{"type":"sort","prompt":"Match each situation with the main influence on the food choice.","categories":["Social influences","Economics","Culture and religion","Convenience and time"],"items":[{"label":"He orders wings because his friends always do after the game.","category":0,"feedback":"Eating with friends shapes what and how much we eat."},{"label":"She buys most of her groceries at the dollar store near the bus stop.","category":1,"feedback":"Income and transportation affect which stores and foods are within reach."},{"label":"Her family never eats pork.","category":2,"feedback":"Religion and culture define which foods are acceptable."},{"label":"He picks up takeout most nights because he has twenty minutes to make dinner.","category":3,"feedback":"Little time pushes people toward quick, ready-made food."}]}},{"id":"l11-b3","chapter":"What makes an effective counsellor","title":"What makes an effective counsellor","teach":["The relationship between counsellor and client is the main driver of change. Clients who succeed often say the relationship was the most important part of their care.","From a review of the counselling research, Okun named seven qualities that matter most: knowledge, self-awareness, ethical integrity, congruence, honesty, the ability to communicate, and awareness of gender and culture. Nutrition counselling writers add a sense of humour, flexibility, optimism, respect for others and empathy. Congruence means what you say matches who you are and how you act, including your body language. No one has all of these perfectly. They are qualities to keep working on."],"act":{"type":"choice","prompt":"A client describes an unusual eating habit. The counsellor says “I see” calmly, but her face shows shock. Which quality is missing?","options":[{"label":"Congruence","correct":true,"feedback":"Right. Her words and her body language don't match, so she isn't congruent."},{"label":"Knowledge","correct":false,"feedback":"Knowledge is about what she knows. The problem here is the mismatch between her words and her face."},{"label":"Flexibility","correct":false,"feedback":"Flexibility is about pace and expectations. The problem is that her words and her face don't match."}]}},{"id":"l11-b4","chapter":"Know yourself first","title":"Know yourself first","teach":["Your personality is one of the main tools you bring to counselling, so it helps to know it well. Ask yourself honestly why you want to help. Counsellors who need to feel in control tend to lecture and stop listening. Counsellors who need to be liked may avoid hard topics and do too much for the client, so the client never learns new skills.","Your worldview, the outlook you get from your culture and life, shapes how you see health, illness and food. Culture is the shared history of racial, ethnic, religious or other social groups, such as gender, age, occupation or income level. Everyone belongs to several groups, so no two people share exactly the same culture. Knowing your own values and biases helps keep them from leaking into your sessions."],"act":{"type":"choice","prompt":"Which counsellor message is most likely to help the client?","options":[{"label":"“I want you to like me.”","correct":false,"feedback":"A counsellor who needs approval tends to avoid difficult issues, so real change doesn't happen."},{"label":"“I am here to help you.”","correct":true,"feedback":"Yes. The focus stays on the client, not on the counsellor's own needs."},{"label":"“Just do what I tell you.”","correct":false,"feedback":"A counsellor who needs control tends to dictate and stops listening."}]}},{"id":"l11-b5","chapter":"Understanding your client","title":"Understanding your client","teach":["Clients come with their own personality, culture, health problems, worries and expectations. Learn about the cultures your clients come from, but remember that what is true of a group is only a generality. It may or may not fit the person in front of you. Avoid stereotyping.","Timing matters too. Someone who has just been given a serious diagnosis may be in shock, angry or in denial, and not ready for detailed diet advice. Self-sufficiency is often a goal, but not always: some clients prefer a more guided role, and some need ongoing support. Asking for help can also make people feel vulnerable or less capable, so explain clearly why you are there and what the work involves."],"act":{"type":"choice","prompt":"You read that people from a certain culture prefer formal greetings. What should you do with that information?","options":[{"label":"Use it as background, and watch how this client actually prefers to be treated.","correct":true,"feedback":"Yes. Group traits are generalities that may or may not fit the individual."},{"label":"Treat every client from that culture formally, no matter what.","correct":false,"feedback":"That is stereotyping. People take on all, some or none of the habits of a culture they seem to belong to."},{"label":"Ignore it, since culture doesn't affect counselling.","correct":false,"feedback":"Culture shapes how clients see health, food and professionals, so it is worth learning about."}]}},{"id":"l11-b6","chapter":"Two phases of the helping relationship","title":"Two phases of the helping relationship","teach":["The helping relationship has two phases. In the first, you build the relationship: rapport, empathy and trust. The goals are to learn about the problem from the client's point of view, find their strengths and help them explore.","In the second phase, you help the client pick specific behaviours to change and plan realistic ways to change them. Skipping the first phase is a common mistake. Without it, you may end up solving the wrong problem, and the plan is unlikely to work."],"act":{"type":"sort","prompt":"Sort each task into the phase it belongs to.","categories":["Phase 1: building the relationship","Phase 2: facilitating positive action"],"items":[{"label":"Learning about the problem from the client's point of view","category":0,"feedback":"This is the focus of the first phase."},{"label":"Exploring the client's strengths","category":0,"feedback":"Finding strengths is part of building the relationship."},{"label":"Choosing specific behaviours to change","category":1,"feedback":"This comes once the relationship and the problem are clear."},{"label":"Designing realistic behaviour change strategies","category":1,"feedback":"Planning the change belongs to the second phase."}]}},{"id":"l11-b7","chapter":"Why “everything will be fine” falls flat","title":"Why “everything will be fine” falls flat","teach":["Telling a client that everything will be fine sounds kind, but it has no basis yet. It brushes aside how they feel, and any comfort it gives fades because nothing has been solved. It can also sound patronizing, as if you are above them.","In the textbook's example, a fitness counsellor named Joe weighs his new client Lilly, decides she needs to lose 20 pounds, and signs her up for classes before she can finish a sentence. She came for more energy and stamina. Real reassurance comes from explaining your role, looking for possible solutions together and explaining how the program works."],"act":{"type":"choice","prompt":"Lilly says she gets tired quickly and wants more stamina. What would be a better first response from Joe?","options":[{"label":"“Tell me more about when you feel tired and what you'd like to be able to do.”","correct":true,"feedback":"Yes. This learns about the problem from her point of view before planning anything."},{"label":"“Don't worry, everything will be fine. Let's get you on the scale.”","correct":false,"feedback":"Empty reassurance brushes past her concern, and the scale wasn't what she came for."},{"label":"“Take some power bars home. They're great for beginners.”","correct":false,"feedback":"This jumps to a solution before understanding her goals."}]}},{"id":"l11-b8","chapter":"Issues for new counsellors","title":"Issues for new counsellors","teach":["New counsellors often worry about whether they know enough. That worry can lead to vague answers on controversial topics, like a politician who won't take a stand. If you don't know, say you will look into it. If the evidence is still mixed, share the pros and cons fairly.","Another trap is picking only one role. The expert gives answers that clients follow for a while without working out how to make change fit their life. The empathizer listens so much that the client gets little direction. Effective counsellors learn to combine the two. Confidence grows with experience."],"act":{"type":"choice","prompt":"A client asks whether high-protein diets are a good way to lose weight, and you haven't looked into it. What should you say?","options":[{"label":"“Some people say they lose weight on them.”","correct":false,"feedback":"This dodges the question without taking a stand or giving useful information."},{"label":"“I haven't looked into that closely. I'll review it and tell you what I find, including the pros and cons.”","correct":true,"feedback":"Yes. You are honest about what you know and commit to giving balanced information."},{"label":"“They don't work. Next question.”","correct":false,"feedback":"Giving a firm answer you haven't checked isn't honest or balanced."}]}}],"flashcards":[{"front":"Nutrition education","back":"Learning experiences planned for a group or community to help people choose foods and habits that support health."},{"front":"Nutrition counselling","back":"A supportive, collaborative process with one client to set food, nutrition and activity priorities, goals and a personal action plan."},{"front":"Most important influence on food choices","back":"Taste (sensory appeal)."},{"front":"Advice is more likely to work when it stresses…","back":"The good taste of wholesome foods and convenient ways to include them in the diet."},{"front":"Okun's seven counsellor qualities","back":"Knowledge, self-awareness, ethical integrity, congruence, honesty, ability to communicate, and gender and culture awareness."},{"front":"Congruence","back":"No contradiction between who the counsellor is, what they say and how they act, including body language."},{"front":"Two counsellor needs that can harm counselling","back":"A need for power or control (leads to dictating) and a need for approval (leads to avoiding hard issues and doing too much for the client)."},{"front":"Worldview","back":"A cultural outlook: the basic beliefs a group holds about reality, which shape views on health, illness and food."},{"front":"Culture","back":"The shared history of racial, ethnic, religious or other social groups, including their thoughts, customs, beliefs, values and institutions."},{"front":"Cultural values","back":"The principles or standards that members of a cultural group share."},{"front":"Phase 1 of the helping relationship","back":"Building the relationship: rapport, empathy and trust. Learn about the problem from the client's point of view and explore strengths."},{"front":"Phase 2 of the helping relationship","back":"Facilitating positive action: choose specific behaviours to change and plan realistic strategies."},{"front":"Why not say “everything will be fine”?","back":"It has no basis, brushes aside the client's feelings and can sound patronizing. Reassure by explaining your role, finding solutions and explaining the program."},{"front":"Three issues for new counsellors","back":"Worrying about competence, giving vague answers on controversial topics, and relying on only the expert role or only the empathizer role."}],"quiz":[{"q":"_______________ has been defined as “any set of learning experiences designed to facilitate the voluntary adoption of eating and other nutrition-related behaviours conducive to health and well-being.”","o":["Nutrition education","Nutrition counselling","Nutrition culture","Nutrition behaviour"],"a":0,"e":"Checked answer, not from an official key. This describes nutrition education, which is planned around the needs of a group."},{"q":"Nutrition professionals work to","o":["increase knowledge.","influence motivations.","guide development of skills required for dietary behaviour change.","All of the above"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 lists all three as part of the job."},{"q":"Those with ______________ are more likely to have better quality diets and lose more weight in weight loss programs.","o":["more money","higher levels of knowledge","strong willpower","All of the above"],"a":1,"e":"Checked answer, not from an official key. The textbook says people with more nutrition knowledge tend to have better diets and lose more weight."},{"q":"Consumers are more likely to respond to healthful food messages if the advice stresses","o":["the good taste of wholesome foods.","convenient ways to include wholesome foods in the diet.","the low cost of wholesome foods.","All of the above","A and B"],"a":4,"e":"Checked answer, not from an official key. The textbook names good taste and convenient ways to include wholesome foods. It doesn't mention cost."},{"q":"A counsellor’s personality","o":["is one of the principle tools of the helping process.","plays a minor role in the helping process.","is not relevant to the helping process."],"a":0,"e":"Checked answer, not from an official key. The textbook calls personality one of the main tools of the helping process."},{"q":"People from all cultures appreciate a friendly, open health care professional.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Many North Americans do, but people from some cultures find it uncomfortable and may even see it as a sign of incompetence."},{"q":"“Culture” is the shared history of _____________ groups.","o":["racial","gender","religious","occupational","Any of the above"],"a":4,"e":"Checked answer, not from an official key. Culture comes from racial, ethnic, religious or other social groups, and social groups include gender and occupation."},{"q":"The characteristics of a cultural group","o":["apply to all people within that group.","are generalities that may or may not apply to individuals within that group."],"a":1,"e":"Checked answer, not from an official key. Group traits are generalities. Assuming they fit everyone is stereotyping."},{"q":"Promoting self-sufficiency is always a main goal of nutrition counselling.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. It is often a goal, but for some clients it needs to change. Some prefer a guided role or need ongoing support."},{"q":"What is the focus of the first phase of the counselling process?","o":["Helping clients identify specific behaviours to alter","Designing realistic behavior change strategies","Learning about the nature of the problem from the client’s viewpoint","All of the above"],"a":2,"e":"Checked answer, not from an official key. The first phase builds the relationship and learns about the problem from the client's view. Choosing behaviours and planning strategies come in the second phase."}]},{"n":12,"title":"Behaviour Change Models and Theories","kicker":"Lesson 12 of your course, built from Chapter 2 of your Nutrition Counseling textbook. Test practice uses checked answers, because there is no official key for this test.","perStepChapter":true,"steps":[{"id":"l12-b1","chapter":"Why theories matter, and self-efficacy","title":"Why theories matter, and self-efficacy","teach":["Behaviour change theories help you understand why people eat the way they do and choose approaches that are more likely to work. No single theory fits every client, so counsellors often mix ideas from several.","One idea shows up in almost all of them: self-efficacy, or a person's confidence that they can make a change. It affects the choices people make, how much effort they put in, how they see barriers and whether they keep going when things get hard. A person's confidence in their ability to change may matter more than their actual skill."],"act":{"type":"choice","prompt":"Two clients know equally well how to plan meals. One is sure she can do it, the other doubts herself. Who is more likely to change?","options":[{"label":"The confident client","correct":true,"feedback":"Yes. Self-efficacy can matter more than actual skill."},{"label":"Both equally, since their skills are the same","correct":false,"feedback":"Confidence affects effort and persistence, so skill alone doesn't decide it."},{"label":"The doubtful client, because she'll try harder","correct":false,"feedback":"Low confidence usually means less effort and giving up sooner when obstacles come up."}]}},{"id":"l12-b2","chapter":"The Health Belief Model","title":"The Health Belief Model","teach":["The Health Belief Model says people are more likely to act when they believe they are at risk (perceived susceptibility), believe the problem would be serious (perceived severity), believe that acting will help (perceived benefits), and believe the obstacles are manageable (perceived barriers). Severity includes physical and social effects, such as the impact on work or money.","Cues to action are the nudges that get someone started: physical symptoms, seeing someone else take action, a media report, or a doctor's advice. You and your client can also plan your own cues, such as a note on the fridge. Self-efficacy was later added to the model too."],"act":{"type":"sort","prompt":"Match each thought with the Health Belief Model idea it shows.","categories":["Perceived susceptibility","Perceived severity","Perceived barriers","Cue to action"],"items":[{"label":"“Heart disease runs in my family, so I could get it.”","category":0,"feedback":"Believing you are at risk is perceived susceptibility."},{"label":"“If I had a heart attack, I couldn't work and pay my bills.”","category":1,"feedback":"Seeing serious physical or financial effects is perceived severity."},{"label":"“Cooking from scratch takes too much time.”","category":2,"feedback":"Obstacles like time, cost or taste are perceived barriers."},{"label":"“My doctor told me to cut back on salt.”","category":3,"feedback":"A doctor's advice can be a cue to action."}]}},{"id":"l12-b3","chapter":"Stages of change","title":"Stages of change","teach":["The Transtheoretical Model describes change as a series of stages. In precontemplation, the person isn't thinking about changing. In contemplation, they are thinking about it, usually within the next six months, but they're stuck weighing pros and cons. People can stay in contemplation for years, waiting for certainty or a “magic moment”. Then come preparation, action and maintenance.","Decisional balance is the weighing of pros and cons. In precontemplation the cons clearly win, and in contemplation they are about even. Self-efficacy tends to drop between precontemplation and contemplation, as people start to see how hard the change will be, and then it rises gradually through action and maintenance."],"act":{"type":"choice","prompt":"A client says, “I know I should eat better, and I'll probably start sometime this year, but it's just not the right time.” Which stage is this?","options":[{"label":"Precontemplation","correct":false,"feedback":"She is already thinking about changing, so she has moved past precontemplation."},{"label":"Contemplation","correct":true,"feedback":"Yes. She is thinking about it but waiting for the right moment."},{"label":"Action","correct":false,"feedback":"She hasn't started making changes yet."}]}},{"id":"l12-b4","chapter":"Planned behaviour and Social Cognitive Theory","title":"Planned behaviour and Social Cognitive Theory","teach":["The Theory of Planned Behaviour looks at intention. A person is more likely to act when they have a positive attitude toward the behaviour, feel that people who matter to them support it, and feel they have control over doing it.","Social Cognitive Theory goes beyond the individual. It includes a person's relationship with social groups and the environment. It describes reciprocal determinism: the person, their behaviour and their environment all affect each other. For example, a husband's high blood pressure (environment) motivates his wife to learn about food (person), so she starts eating more vegetables (behaviour). Ways to build self-efficacy include social modelling, verbal persuasion and helping the person feel better physically and emotionally."],"act":{"type":"choice","prompt":"Which theory looks at a person's relationship with social groups and the environment?","options":[{"label":"Health Belief Model","correct":false,"feedback":"The Health Belief Model focuses on the person's own beliefs about risk, severity, benefits and barriers."},{"label":"Social Cognitive Theory","correct":true,"feedback":"Yes. It looks at how the person, their behaviour and the environment influence each other."},{"label":"Transtheoretical Model","correct":false,"feedback":"This model describes stages of readiness, not social groups and the environment."}]}},{"id":"l12-b5","chapter":"Cognitive-behavioural approaches","title":"Cognitive-behavioural approaches","teach":["Cognitive-behavioural therapy works on both thoughts and actions. The cognitive part helps clients notice and change unhelpful thinking, such as “I ate one cookie, so the whole day is ruined.”","The behavioural part changes actions directly. Classical conditioning pairs a cue with a response. Operant conditioning is based on the law of effect: behaviours can be changed by their positive or negative effect. In nutrition counselling, the positive side is usually used, such as a reward for reaching a goal. Sometimes the change is its own reward, like relief from constipation after drinking more fluids and eating more fibre."],"act":{"type":"choice","prompt":"A client treats herself to a new cookbook after a month of packing lunches. Which approach is this?","options":[{"label":"Operant conditioning","correct":true,"feedback":"Yes. A reward strengthens the behaviour, which is the law of effect."},{"label":"Classical conditioning","correct":false,"feedback":"Classical conditioning pairs a cue with a response. This is a reward after a behaviour."},{"label":"Modelling","correct":false,"feedback":"Modelling means learning by watching someone else."}]}},{"id":"l12-b6","chapter":"Client-centred and solution-focused counselling","title":"Client-centred and solution-focused counselling","teach":["Client-centred counselling, from Carl Rogers, guides how to build a good counselling relationship: warmth, genuineness, acceptance and empathy. Many practitioners use its basics no matter which other approach they follow.","Solution-focused therapy spends less time on the problem and more on what is already working. It looks for exceptions (times the problem didn't happen) and builds on the client's strengths and past successes."],"act":{"type":"choice","prompt":"Which question fits a solution-focused approach?","options":[{"label":"“Why do you think you overeat at night?”","correct":false,"feedback":"This digs into the problem rather than what works."},{"label":"“Tell me about a night this week when snacking wasn't a problem. What was different?”","correct":true,"feedback":"Yes. Looking for exceptions and building on them is the heart of this approach."},{"label":"“How many calories do you eat after dinner?”","correct":false,"feedback":"This gathers facts but doesn't look for what's already working."}]}},{"id":"l12-b7","chapter":"Motivational interviewing","title":"Motivational interviewing","teach":["Motivational interviewing (MI) helps people resolve ambivalence, the feeling of wanting to change and not wanting to at the same time. Its spirit is a partnership with the client rather than an expert telling them what to do. It assumes people already have reasons to change, and your job is to draw them out (evocation), while respecting that the choice is theirs (autonomy). Your course test describes the three parts as collaboration, evocation and autonomy.","Core MI skills are open-ended questions, affirmations, reflections and summaries. The aim is for the client, not you, to make the case for change. This is called change talk. As the client voices their own need for change and the gap between their behaviour and their values grows, the balance of indecision starts to tip toward action."],"act":{"type":"choice","prompt":"Which counsellor move is most in the spirit of motivational interviewing?","options":[{"label":"Listing all the health risks so the client sees why she must change","correct":false,"feedback":"Trying to convince the client tends to create pushback. MI lets the client make the case."},{"label":"Asking, “What would be different for you if you made this change?”","correct":true,"feedback":"Yes. An open question that draws out the client's own reasons encourages change talk."},{"label":"Telling the client which change to start with","correct":false,"feedback":"MI respects the client's choice and works in partnership."}]}}],"flashcards":[{"front":"Self-efficacy","back":"A person's confidence that they can make a change. It may matter more than actual skill."},{"front":"Health Belief Model: perceived susceptibility","back":"Believing you are at risk of the problem."},{"front":"Health Belief Model: perceived severity","back":"Believing the problem would have serious physical or social effects, including on money or work."},{"front":"Health Belief Model: perceived barriers","back":"The obstacles a person sees, such as taste, cost or inconvenience."},{"front":"Cues to action","back":"Prompts to act, such as physical symptoms, seeing others act, a media report or a doctor's advice."},{"front":"Contemplation stage","back":"Thinking about changing, usually within six months. People can be stuck here for years waiting for the “magic moment”."},{"front":"Self-efficacy across the stages of change","back":"It tends to drop from precontemplation to contemplation, then rises through action and maintenance."},{"front":"Decisional balance","back":"Weighing the pros and cons of changing."},{"front":"Social Cognitive Theory","back":"Looks at the person, their behaviour and the environment, including social groups, and how they affect each other (reciprocal determinism)."},{"front":"Ways to build self-efficacy (SCT)","back":"Social modelling, verbal persuasion, and improving physical and emotional states."},{"front":"Operant conditioning","back":"Based on the law of effect: behaviours change through their positive or negative effects."},{"front":"Solution-focused therapy","back":"Focuses on exceptions and what is already working rather than on the problem."},{"front":"Spirit of motivational interviewing (course test)","back":"Collaboration, evocation and autonomy."},{"front":"Change talk","back":"The client's own statements in favour of change. As it grows, the balance shifts toward action."}],"quiz":[{"q":"A person’s confidence in his or her ability to accomplish a behaviour change may be more important than actual skill.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says this about self-efficacy almost word for word."},{"q":"Which behaviour change theory incorporates a person’s relationship with social groups and the environment?","o":["Health belief model","Transtheoretical model","Theory of planned behaviour","Social cognitive theory","All of the above"],"a":3,"e":"Checked answer, not from an official key. The textbook says Social Cognitive Theory looks beyond the individual to social groups and the environment."},{"q":"In the Health Belief Model, physical symptoms, a media report, or advice of a physician can all be cues to action.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. The textbook lists all three as cues to action."},{"q":"Which Health Belief Construct is the perception that heart disease can negatively affect a person’s financial status?","o":["Cue to Action","Perceived Susceptibility","Perceived Severity","Perceived Barrier"],"a":2,"e":"Checked answer, not from an official key. Perceived severity covers the physical and social effects of a condition, including effects on money."},{"q":"In the Transtheoretical Model, people can be stuck in which stage for years, waiting for the “magic moment”?","o":["Precontemplation","Contemplation","Preparation","Action","Maintenance"],"a":1,"e":"Checked answer, not from an official key. The textbook says this about the contemplation stage."},{"q":"Self-efficacy tends to increase for individuals between the precontemplation and contemplation stages.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. It tends to decrease between these stages, as people start to see how hard the change will be."},{"q":"A__________ is based on the law of effect, which states that behaviours can be changed by their positive or negative effect.","o":["Modelling","Classical conditioning","Operant conditioning","Systematic densensitization"],"a":2,"e":"Checked answer, not from an official key. The textbook defines operant conditioning this way."},{"q":"Social modelling, verbal persuasion, and improving physical and emotional states are intervention strategies for which Social Cognitive Theory concept?","o":["Behavioural capacity","Self-efficacy","Observational learning","Facilitation"],"a":1,"e":"Checked answer, not from an official key. These are the classic ways to build self-efficacy."},{"q":"Collaboration, evocation, and autonomy are the three components of _____________.","o":["solution-focused therapy","behavioural therapy","cognitive therapy","motivational interviewing."],"a":3,"e":"Checked answer, not from an official key. These describe the spirit of motivational interviewing. The 7th edition describes it as partnership, acceptance, compassion and evocation."},{"q":"When clients express _______________, the balance of indecision begins to shift toward taking action.","o":["ambivalence","need for change","resistance","B and C"],"a":1,"e":"Checked answer, not from an official key. As clients voice their own need for change (change talk), the balance of indecision begins to shift toward action."}]},{"n":13,"title":"Communication Skills","kicker":"Listen, check, and respond in a conversation that can change direction • Supplementary learning, not the official chapter or assessment.","perStepChapter":true,"steps":[{"id":"l13-interactive-1","chapter":"Hear the problem before solving it","title":"Hear the problem before solving it","teach":["A technically accurate explanation can still be unhelpful if the client feels judged, cannot understand it, or cannot use it. Effective counselling therefore involves listening for meaning, checking understanding, and agreeing what happens next. The aim is not to win an argument about food.","It is to help someone make an informed, workable decision while preserving their autonomy. Consider the difference between “You need to stop skipping lunch” and “What happens around lunchtime on a workday?” The first assumes both the problem and its solution. The second opens space for information: perhaps breaks are unpredictable, food storage is unavailable, nausea makes eating uncomfortable, or the client is deliberately restricting."],"act":{"type":"choice","prompt":"Maya says, “Everyone tells me to cook. I am exhausted.” What is the best opening?","options":[{"label":"“Batch cooking is the obvious solution.”","correct":false,"feedback":"This repeats the unrequested cooking agenda before learning whether time, facilities, energy, or another issue matters."},{"label":"“More cooking sounds like more work when you are already stretched.”","correct":true,"feedback":"This reflects the expressed concern and gives Maya room to confirm or correct it. Useful problem-solving can follow the actual barrier."},{"label":"“So you do not want to improve your eating.”","correct":false,"feedback":"This infers motivation from a complaint about workload and risks shutting down relevant information."}]}},{"id":"l13-interactive-2","chapter":"Choose a communication tool deliberately","title":"Choose a communication tool deliberately","teach":["OARS stands for open questions, affirmations, reflective listening, and summaries. SAMHSA describes these core motivational interviewing skills within substance-use treatment. Their communication principles can inform nutrition conversations, but this lesson is not training or certification in delivering a complete motivational interviewing intervention.","An open question invites explanation: “What would you like to feel different after our work together?” A closed question obtains a particular detail: “Do you have access to a refrigerator?” Both are useful. Open questions discover the story; focused questions clarify it. Asking only open questions can leave safety details unclear; asking only closed questions can feel like an interrogation."],"act":{"type":"sort","prompt":"Classify each response by its main function. An affirmation recognizes a specific effort; a reflection offers understanding; a summary gathers threads.","categories":["Affirmation","Reflection","Summary"],"items":[{"label":"“You found a way to eat during an unpredictable shift.”","category":0,"feedback":"This identifies an actual effort rather than praising obedience."},{"label":"“Meal preparation feels like another job.”","category":1,"feedback":"This offers an understanding for the client to confirm or correct."},{"label":"“Time is tight, lunch is available nearby, and cost matters. What did I miss?”","category":2,"feedback":"This gathers several relevant threads and invites correction."},{"label":"“You noticed the difficulty and brought it up today.”","category":0,"feedback":"The affirmation is grounded in something the person actually did."}]}},{"id":"l13-interactive-3","chapter":"Follow three possible turns","title":"Follow three possible turns","teach":["A simple reflection stays near the words: “You feel rushed in the morning.” A more complex reflection tentatively connects meaning: “Having breakfast ready might make mornings feel less chaotic.” More complex does not automatically mean better.","If your interpretation is unsupported, use a tentative phrase or return to a simpler reflection. Compare three responses to “I know what to do, but I never keep it up.” Advice-first: “Set an alarm.” Judgment: “You need discipline.” Reflective: “You have tried before, and you are discouraged that the plans have not lasted.” The reflective response does not solve the problem immediately."],"act":{"type":"explore","prompt":"Dev says, “I am not giving up my family’s food.” Predict what each response may open or close before revealing it.","panels":[{"label":"Defend the advice","text":"“But my plan is healthier.” This moves into debate and misses Dev’s concern about identity. More information may not resolve a concern that advice feels dismissive."},{"label":"Reflect too confidently","text":"“You are afraid your family will reject you.” This adds a meaning Dev has not supplied. If it misses, accept correction rather than defending the interpretation."},{"label":"Reflect and invite","text":"“Keeping family meals matters, and you worry this means losing them. What would you actually like help with?” Dev can clarify the concern and identify a different priority."}]}},{"id":"l13-interactive-4","chapter":"Ask–offer–check, without a hidden agenda","title":"Ask–offer–check, without a hidden agenda","teach":["Information is often more useful when it answers a question the client actually has. An original teaching sequence is ask–offer–check: ask what they know and whether information would help; offer a small relevant explanation; check what they make of it.","This is a study sequence, not a validated assessment tool. For example: “What have you heard about fibre?” Then: “Would a short explanation help?” After a brief explanation: “How does that fit with foods you enjoy?” Do not treat asking permission as a trick to secure agreement. Someone may decline, ask for another topic, or disagree after hearing the information."],"act":{"type":"choice","prompt":"Maya confirms that recipes are not the problem. She asks for low-preparation ideas. What do you say?","options":[{"label":"“I cannot give information because good counselling only uses questions.”","correct":false,"feedback":"Collaborative communication does not mean withholding a requested, appropriate explanation within your competence."},{"label":"“Here are twenty options and a full nutrient lecture.”","correct":false,"feedback":"An information flood may obscure the decision she wants to make. Start with a small relevant amount in a usable format."},{"label":"“Would comparing two familiar options help? Then we can see which fits your breaks.”","correct":true,"feedback":"This offers relevant information after understanding the request and leaves the choice open. Asking permission does not require her to agree afterward."}]}},{"id":"l13-interactive-5","chapter":"Check your explanation—not the client’s obedience","title":"Check your explanation—not the client’s obedience","teach":["Teach-back asks a person to explain the plan in their own words so you can identify communication gaps. It should be framed as a check on how clearly you explained, not as a memory examination. If understanding is incomplete, explain differently and check again.","An original example: “I covered several things quickly. To check that I explained them clearly, how would you describe the lunch experiment we agreed?” If the person describes a different plan, avoid “No, you weren't listening.” Try “I can see I made that confusing. Let's make the plan simpler.” Teach-back is different from asking “Do you understand?” People may say yes out of politeness or embarrassment."],"act":{"type":"choice","prompt":"Maya describes a different shopping day from the one you thought was agreed. Choose your next response.","options":[{"label":"“I may have made that confusing. Let’s clarify what fits, then you can describe the plan in your own words.”","correct":true,"feedback":"This takes responsibility for clarity and checks a workable shared understanding. Maya can understand a plan and still choose to change it."},{"label":"“You said you understood, so the explanation is finished.”","correct":false,"feedback":"A yes/no understanding check can hide confusion. The mismatch is useful information, not something to ignore."},{"label":"“No, you were not listening. Repeat my plan exactly.”","correct":false,"feedback":"Teach-back is not a memory test or a demand for compliance. This response makes a communication gap the client’s fault."}]}},{"id":"l13-interactive-6","chapter":"Make disagreement useful","title":"Make disagreement useful","teach":["Shared decision-making connects available options with what matters to the person. Discuss relevant benefits, burdens, uncertainties, and the option of no change where appropriate; agree how the decision will be reviewed. In an original nutrition example, the options might be preparing food at home, assembling convenience foods, or buying lunch. These are not ranked by moral worth.","Compare cost, time, facilities, enjoyment, and reliability. Ask “Which would fit your next week?” rather than “Which is the healthiest choice?” when the latter hides practical trade-offs. If disagreement emerges, slow down. “We may be looking at this differently. What feels unhelpful about my suggestion?”"],"act":{"type":"explore","prompt":"Predict which next turn preserves both accuracy and autonomy. Compare these endings to a discussion of lunch options.","panels":[{"label":"“The home-cooked option wins.”","text":"This ranks options without checking cost, time, facilities, or preference. A technically appealing option can still be impractical."},{"label":"“Whatever you read online must be right for you.”","text":"Rapport does not require endorsing unsafe or unsupported claims. Explain uncertainty respectfully and seek qualified input when needed."},{"label":"“What feels unhelpful about my suggestion?”","text":"This makes room for correction. Compare genuine trade-offs, acknowledge uncertainty, and agree whether to try something, gather information, or make no change."}]}}],"flashcards":[],"quiz":[]},{"n":14,"title":"The Counselling Interview","kicker":"Navigate an interview with signposts, not an interrogation • Supplementary learning, not the official chapter or assessment.","perStepChapter":true,"steps":[{"id":"l14-interactive-1","chapter":"Set up a safe conversation","title":"Set up a safe conversation","teach":["Before the meeting, confirm the purpose, available time, accessibility needs, and any information already provided. Do not make the client repeat a long history simply because you have not reviewed authorized records. Equally, do not treat an old record as automatically accurate. Ask what has changed. Consider privacy in both physical and remote settings.","Can others hear the conversation? Is the client comfortable speaking where they are? Use approved systems rather than improvising with personal accounts or recordings. Do not record sessions by default. Any recording requires the relevant permission, secure arrangements, and compliance with applicable rules."],"act":{"type":"explore","prompt":"Before opening each setting, predict what you would check before starting the interview.","panels":[{"label":"Remote appointment in a shared room","text":"Ask whether the client can speak comfortably and privately. Use approved systems and consider alternatives if the setting is unsuitable; do not record by default."},{"label":"A support person joins","text":"Ask whether the client wants that involvement and clarify what may be discussed. Presence does not automatically grant unrestricted permission."},{"label":"The client expects medical answers","text":"Explain your actual role and who can address medical questions. Describe applicable confidentiality limits without promising absolute secrecy."}]}},{"id":"l14-interactive-2","chapter":"Negotiate the agenda","title":"Negotiate the agenda","teach":["A warm opening need not be elaborate. Confirm how the person wishes to be addressed and whether any communication adjustments would help. Ask what brought them and what would make the appointment useful. If someone else referred them, distinguish the referrer's concern from the client's own priorities.","NICE recommends agreeing an agenda and making the available discussion time clear. It also emphasizes the person's preferences for involvement in decisions. An original opening might be: “We have about forty minutes. I would like to understand your routine, hear what you want help with, and leave time for a next step. What would you put first?”"],"act":{"type":"choice","prompt":"Lena’s referral says “weight management.” She says, “I want to get through work without being distracted by hunger.” Choose your opening.","options":[{"label":"“That hunger proves your blood sugar is abnormal.”","correct":false,"feedback":"An interview report does not establish a medical diagnosis. Clarify the experience and arrange assessment when appropriate."},{"label":"“The referral determines the goal, so we must start with weight.”","correct":false,"feedback":"The referral provides context, not automatic consent. Lena’s priority needs to be heard alongside relevant safety considerations."},{"label":"“Let’s start with what happens during work. We can agree what is useful today and flag anything needing separate assessment.”","correct":true,"feedback":"This respects Lena’s agenda without abandoning safety or scope. A shared agenda guides the interview better than an imposed label."}]}},{"id":"l14-interactive-3","chapter":"Separate reports from conclusions","title":"Separate reports from conclusions","teach":["Begin broadly: “Walk me through a fairly typical day.” Follow with “How was yesterday different?” A single day may be unusual, so learn about variability across workdays, weekends, caregiving demands, and available money. Ask what already works. An assessment that records only deficits misses resources the eventual plan could use.","Relevant areas may include meal timing, food access, cooking facilities, preferences, cultural or religious practices, symptoms, relevant diagnosed conditions, and medicines or supplements. Ask only for information relevant to your role and purpose. The presence of a topic on a template does not justify intrusive questioning."],"act":{"type":"sort","prompt":"Place each note in the correct category before building a plan.","categories":["Client report","Unsupported conclusion","Useful clarification"],"items":[{"label":"“Client reports nausea after breakfast on three mornings.”","category":0,"feedback":"This records the person’s account without asserting a cause."},{"label":"“Breakfast causes the nausea.”","category":1,"feedback":"Timing alone does not establish causation or authorize diagnosis."},{"label":"“How was yesterday different from a usual workday?”","category":2,"feedback":"This explores variability rather than treating one day as a full baseline."},{"label":"“Missed lunch means low motivation.”","category":1,"feedback":"A missed meal can reflect access, scheduling, symptoms, priorities, or other factors."}]}},{"id":"l14-interactive-4","chapter":"Offer a reason and an exit","title":"Offer a reason and an exit","teach":["Sensitive areas can include finances, weight experiences, restriction, body image, alcohol, family conflict, and mental health. Explain relevance in neutral language: “Food costs can affect what plans are realistic. Would it be okay to ask whether your budget regularly covers enough food?” Avoid implying that financial difficulty is a personal failure. Do not require disclosure beyond what is necessary for safe service.","A client can decline a question. Explain if that missing information limits the advice you can responsibly provide. Offer another way of discussing it, another appointment, or an appropriate referral where helpful. If someone becomes distressed, pause the information gathering."],"act":{"type":"choice","prompt":"Amir becomes quiet: “I do not want to discuss what happens at home.” What is the best next turn?","options":[{"label":"“We can pause. Is there anything that changes what would feel safe or practical to plan, without going into details?”","correct":true,"feedback":"This respects a boundary and focuses on relevant planning needs. Follow applicable safety procedures if an immediate concern emerges."},{"label":"“I promise nothing you say could ever be shared.”","correct":false,"feedback":"Absolute secrecy may misrepresent applicable confidentiality limits. Explain the actual rules of the setting accurately."},{"label":"“I need every detail before I can help.”","correct":false,"feedback":"More disclosure is not automatically a better interview. Explain relevant limits without demanding unnecessary sensitive detail."}]}},{"id":"l14-interactive-5","chapter":"Choose the appropriate interview outcome","title":"Choose the appropriate interview outcome","teach":["A useful midpoint summary includes the person's goal, the main circumstances, existing strengths, uncertainties, and possible safety needs. Say “Let me check that I have this right,” then invite correction. This reduces the risk of building an elaborate plan around a mistaken assumption. Motivational interviewing literature warns against premature focus: moving into a change agenda before establishing a working relationship and understanding the person's priorities.","Distinguish three possible findings. First, there may be enough information to discuss a low-risk practical experiment. Second, you may need another detail before choosing a plan. Third, the issue may need a different professional."],"act":{"type":"sort","prompt":"Match the situation to the next kind of work; not every interview should end with a new eating goal.","categories":["Practical experiment","Clarify first","Appropriate professional input"],"items":[{"label":"The client chooses a feasible lunch option and access is understood.","category":0,"feedback":"There may be enough information for a low-risk, jointly chosen practical trial within your role."},{"label":"It is unclear whether any food storage is available.","category":1,"feedback":"Resolve the detail that determines whether the proposed action is workable."},{"label":"The client asks you to diagnose the cause of recurring symptoms.","category":2,"feedback":"Do not convert an interview into a diagnosis. Explain your role and the appropriate assessment pathway."},{"label":"The client says the old record no longer reflects their medicines.","category":1,"feedback":"Clarify the relevant current information through appropriate channels; do not independently alter treatment."}]}},{"id":"l14-interactive-6","chapter":"Close the loop","title":"Close the loop","teach":["Leave time to agree what happens next. Ask what the client wants to try, what might make it difficult, and what support is needed. If no behavioural change is chosen, the next step could be gathering information, arranging a referral, or returning to a decision later.","Give a short summary in an accessible format. Use teach-back to check your explanation, not to test obedience. For example: “You will choose two workdays to try the lunch option. I will send our short list through the approved system. Next week we will review what was easy and what got in the way. How would you describe that plan?”"],"act":{"type":"choice","prompt":"You have two minutes left. Lena chose one lunch trial and you offered to send a short list. Which ending is most useful?","options":[{"label":"“Great, just eat better and book again sometime.”","correct":false,"feedback":"This loses the agreed action, responsibilities, and review. A positive tone does not replace a clear next step."},{"label":"“You choose the two workdays; I send the list through our approved system. Next week we review access and ease. How would you describe the plan?”","correct":true,"feedback":"This clarifies who does what and why follow-up matters, then checks your explanation. Document the actual agreement promptly."},{"label":"“I will record that you accepted the referral’s full programme.”","correct":false,"feedback":"Only record consent and actions actually agreed. One practical trial is not consent to a different programme."}]}}],"flashcards":[],"quiz":[]},{"n":15,"title":"Developing a Nutritional Care Plan","kicker":"Build a plan that fits a real week—and can be revised • Supplementary learning, not the official chapter or assessment.","perStepChapter":true,"steps":[{"id":"l15-interactive-1","chapter":"Start with a useful baseline","title":"Start with a useful baseline","teach":["Ask “What would you most like this plan to help with?” Possible answers include more reliable meals, less stress about shopping, support following advice from a treating clinician, or greater confidence preparing familiar foods. Do not automatically substitute your preferred outcome. A baseline describes the present situation in enough detail to guide a decision.","For a lunch-access goal, useful information might include the number of workdays with a break, food facilities, usual purchases, budget, and what the client considers satisfying. A comprehensive food diary is not always necessary. Choose the least burdensome information that answers the question."],"act":{"type":"choice","prompt":"Jo says, “I want less chaotic evenings.” Which question most directly starts a relevant plan?","options":[{"label":"“Can you track every food and nutrient for a month first?”","correct":false,"feedback":"A detailed diary is not automatically necessary. Choose the least burdensome information that answers the planning question."},{"label":"“Will you agree to cook every night?”","correct":false,"feedback":"This selects a demanding solution before understanding Jo’s routine, resources, or definition of less chaotic."},{"label":"“Which evenings are hardest, and what already works on the others?”","correct":true,"feedback":"This connects the stated priority to variability and existing strengths. It can reveal a small action that fits rather than rebuilding everything."}]}},{"id":"l15-interactive-2","chapter":"Triage the planning work","title":"Triage the planning work","teach":["Not every issue deserves equal attention today. Separate urgent clinical concerns from practical goals that can safely be explored. If concerning symptoms, major restriction, or a possible medicine-related problem emerges, arrange the appropriate professional input rather than hiding it inside an ordinary meal-planning task.","Do not independently stop or adjust prescribed medicines. For nonurgent choices, discuss which issue matters most and which change seems feasible. A useful original prompt is “Which change would make the biggest useful difference without overwhelming the week?” Sometimes stabilizing access to enough food is more appropriate than optimizing variety. Sometimes the first step is understanding a clinician's instructions rather than adding new advice."],"act":{"type":"sort","prompt":"Choose the main next step in each situation. Safety and scope come before adding goals.","categories":["Explore a practical goal","Clarify feasibility","Arrange qualified input"],"items":[{"label":"A client asks you to stop a prescribed medicine.","category":2,"feedback":"Do not independently alter medicines. Help direct the question to the appropriate treating professional."},{"label":"Jo chooses two low-preparation dinners using familiar foods.","category":0,"feedback":"This is a focused practical option if it fits the assessment and your role."},{"label":"The plan requires a second shopping trip, but transport is unknown.","category":1,"feedback":"Check access before calling the goal achievable."},{"label":"A client wants a strict elimination diet for unexplained symptoms.","category":2,"feedback":"Do not diagnose intolerance from a diary or invent a therapeutic restriction protocol; appropriate clinical assessment is needed."}]}},{"id":"l15-interactive-3","chapter":"Compare genuine options","title":"Compare genuine options","teach":["For a practical problem there may be several acceptable options. If breakfast is difficult, possibilities might include preparing something the night before, choosing a portable food, eating at a different point in the morning, or first investigating symptoms that interfere with eating. The options are not interchangeable for every person.","Shared decision-making involves considering choices alongside what matters to the person and recording the decision and its relevant preferences. For each option, discuss likely usefulness, burden, cost, enjoyment, and uncertainty. Do not present a possibility as guaranteed to improve symptoms. “This could help us test whether having food available changes the afternoon pattern” is more accurate than “This will cure your tiredness.” Explain when medical assessment should occur independently of the experiment."],"act":{"type":"explore","prompt":"Predict which trade-off could change Jo’s choice before opening each option. No option wins solely because it sounds more virtuous.","panels":[{"label":"Cook from scratch each evening","text":"Explore time, enjoyment, energy, equipment, and costs. This may suit some people but conflicts with Jo’s description of two particularly difficult evenings."},{"label":"Use familiar low-preparation dinners","text":"This may fit the existing shopping routine and reduce work. Check whether the meals are acceptable and accessible rather than assuming convenience solves everything."},{"label":"Pause a new food goal","text":"A pause may be appropriate if access, symptoms, or another priority needs attention. Choosing no immediate dietary change is not automatically a failed appointment."}]}},{"id":"l15-interactive-4","chapter":"Draft a flexible goal","title":"Draft a flexible goal","teach":["SMART is commonly expanded as specific, measurable, achievable, relevant, and time-bound. Variants exist. Here it is a drafting aid, not a validated treatment or a rule that every meaningful goal must be reduced to a number.","“Eat better” is too vague to guide action. An original version could be: “For the next seven days, I will put one familiar lunch option in my work bag on Monday and Thursday evenings, then review whether it was practical.” The goal identifies an action, context, and review period. It does not promise a health outcome. Measurable need not mean calories, weight, or exhaustive tracking."],"act":{"type":"choice","prompt":"Which goal best turns Jo’s priority into an agreed, reviewable experiment?","options":[{"label":"“Be healthier and never miss a home-cooked dinner.”","correct":false,"feedback":"This combines a vague outcome with an absolute demand. It does not describe a realistic, flexible action or useful review."},{"label":"“At the usual shop, choose ingredients for two familiar easy dinners next week; review stress, ease, and enjoyment afterward.”","correct":true,"feedback":"This specifies an action, context, and review tied to Jo’s own purpose. Measurement does not need to mean calories, weight, or exhaustive tracking."},{"label":"“Cook every night until your stress is cured.”","correct":false,"feedback":"This promises an outcome and ignores the baseline. A routine trial cannot guarantee a cure or establish the cause of distress."}]}},{"id":"l15-interactive-5","chapter":"Give the plan a backbone","title":"Give the plan a backbone","teach":["A goal names what the person wants to do. An action plan specifies when, where, and how. A coping plan addresses predictable barriers. NICE's behaviour-change guidance includes collaboratively chosen goals, action planning, monitoring, and plans for setbacks.","For example, buy two familiar lunch options during the usual shop and place a reminder beside the work bag. If the planned food is unavailable, use an affordable purchased option identified beforehand. Review cost, convenience, and satisfaction. The backup is not a lesser moral choice; it makes the plan resilient. Ask whether family support is welcome and safe before suggesting it."],"act":{"type":"sort","prompt":"Match each planning statement to its function.","categories":["Action and cue","Coping backup","Review question"],"items":[{"label":"“Choose the two dinner options during Saturday’s usual shop.”","category":0,"feedback":"This says when and how the chosen action will happen."},{"label":"“If ingredients are unavailable, use the affordable prepared option already identified.”","category":1,"feedback":"A realistic backup handles disruption without treating it as moral failure."},{"label":"“Did those evenings feel less stressful, and was the food enjoyable?”","category":2,"feedback":"Review the original purpose and lived experience, not just task completion."},{"label":"“Place the short shopping list beside the usual bag.”","category":0,"feedback":"The cue supports the action at a useful moment; it is not a guarantee."}]}},{"id":"l15-interactive-6","chapter":"Record agreement, then review it honestly","title":"Record agreement, then review it honestly","teach":["A practical record can use seven headings: priority, relevant assessment, agreed action, support, responsibilities, monitoring, and review. Add consent, referrals, and safety instructions as appropriate to the setting. Use professional documentation requirements if they apply; this teaching template does not replace them. Write “Client chose to try…” only when that is true.","Separate “Options discussed” from “Action agreed.” Include why the selected option fits the person's circumstances. Record important uncertainty rather than making the note appear more certain than the conversation was. Monitoring should be proportionate. Ask what information will help decide whether to continue, change, or stop the plan."],"act":{"type":"choice","prompt":"Jo considered several options but chose only two easy dinners. Which note best supports continuity?","options":[{"label":"“Client needs more motivation.”","correct":false,"feedback":"A character label is neither an agreed plan nor an explanation. Record the circumstances and what the person decided."},{"label":"“Client committed to the complete healthy-eating plan.”","correct":false,"feedback":"This overstates agreement and hides what was actually chosen. Options discussed are not the same as consented actions."},{"label":"“Client chose two familiar dinners for difficult evenings; buys ingredients at usual shop; backup discussed; review stress and access next week.”","correct":true,"feedback":"This records the reason, action, context, backup, and review. Add the actual responsibilities, consent, or referrals required in your setting."}]}}],"flashcards":[],"quiz":[]},{"n":16,"title":"Facilitating Self Management","kicker":"Build adaptable skills without creating dependency or blame • Supplementary learning, not the official chapter or assessment.","perStepChapter":true,"steps":[{"id":"l16-interactive-1","chapter":"Independence can include support","title":"Independence can include support","teach":["Self-management means participating in decisions and everyday actions that affect one's health and wellbeing. It does not mean doing everything alone, never needing help, or accepting responsibility for circumstances outside one's control. A client may manage a routine effectively with family assistance, accessible services, reminders, or professional follow-up.","The counsellor's job is not to become the client's permanent decision-maker. It is to help the person understand choices, develop relevant skills, use available resources, and know when to seek help. Independence can include the ability to request support early. An important distinction is between self-management and self-blame."],"act":{"type":"explore","prompt":"Predict which version develops self-management. Open each interpretation and compare what it asks of the client.","panels":[{"label":"“You should never need help again.”","text":"This mistakes self-management for isolation. Requesting support early can be a useful skill, especially when circumstances change."},{"label":"“I will choose every meal for you.”","text":"This can make the counsellor the permanent decision-maker. The aim is to build understanding and choices the person can use beyond the appointment."},{"label":"“Let’s practise a decision you can adapt.”","text":"This supports transferable skills while leaving room for chosen help, accessible resources, and continued professional care when needed."}]}},{"id":"l16-interactive-2","chapter":"Match support to the missing piece","title":"Match support to the missing piece","teach":["When a plan is not happening, do not assume the explanation is unwillingness. Ask what the person understands, what they can do, what the setting permits, and whether the goal still matters.","The same missed lunch could reflect uncertainty about what to buy, lack of storage, no break, nausea, or a decision to prioritize another concern. An original diagnostic-for-learning question—not a medical diagnostic tool—is: “Is the main difficulty knowing what, knowing how, having the opportunity, or wanting this change right now?” The answer guides the next conversation. A knowledge gap may call for a short explanation."],"act":{"type":"sort","prompt":"Choose the most direct starting point, then check your hypothesis with the person.","categories":["Explain or practise","Address opportunity","Renegotiate the goal"],"items":[{"label":"“I have access to ingredients but do not know how to put this meal together.”","category":0,"feedback":"A short demonstration or practice may address the relevant skill gap."},{"label":"“I can prepare it, but there is no reliable break.”","category":1,"feedback":"The setting constrains the action. More instructions do not create time at work."},{"label":"“I want help with food costs, not meal variety.”","category":2,"feedback":"The proposed goal misses the person’s priority; agree what matters now."},{"label":"“I understand the plan, but cannot afford the food.”","category":1,"feedback":"Explore accessible practical support rather than interpreting the problem as unwillingness."}]}},{"id":"l16-interactive-3","chapter":"Make the skill reusable","title":"Make the skill reusable","teach":["A self-management skill is something the person can use again: comparing realistic options, planning a shopping trip, preparing a familiar meal, explaining a question to a clinician, or adapting a routine when work changes. Choose a skill connected to the client's goal rather than assigning generic homework. Break the skill into manageable steps.","For meal assembly, the steps might be identifying available foods, checking facilities, selecting an option, obtaining ingredients, and trying it once. Do not assume the person needs instruction at every step. Ask what they already do confidently. An experiment is different from a performance test."],"act":{"type":"choice","prompt":"A client wants confidence choosing lunch when the usual option is unavailable. What task fits?","options":[{"label":"Compare two available options, check cost and facilities, then rehearse choosing a backup.","correct":true,"feedback":"This breaks a relevant decision into manageable steps the client can reuse. Ask which parts they already do confidently."},{"label":"Require a perfect week before offering feedback.","correct":false,"feedback":"A small experiment is for learning, not proving commitment. Feedback can help even when the first trial does not work."},{"label":"Ask them to memorize one menu and repeat it indefinitely.","correct":false,"feedback":"This gives a fixed answer but does not practise adapting when the relevant condition changes."}]}},{"id":"l16-interactive-4","chapter":"Repair the environment, not the person","title":"Repair the environment, not the person","teach":["Motivation varies, so the physical and social setting matters. Consider what is visible, available, affordable, and easy at the moment of action. An original example is keeping an agreed shelf space for work-lunch ingredients. Another is identifying a reliable food option near the workplace rather than relying on cooking after an exhausting shift.","NICE's behaviour-change guidance includes attention to supportive routines, social support, coping plans, and changes to the immediate environment when maintaining behaviour. These are supports, not guarantees. Social support should be chosen by the client. A friend might help with shopping or share a meal, but monitoring, criticism, or unsolicited comments may make things harder."],"act":{"type":"choice","prompt":"Sara says, “I stopped packing lunch when my shift moved earlier. I knew I could not keep anything up.” Choose your response.","options":[{"label":"“Your old plan succeeded once, so it must still be the right plan.”","correct":false,"feedback":"A plan can stop fitting when conditions change. Previous success is useful information, not a reason to ignore new constraints."},{"label":"“Let’s double the tracking until your willpower returns.”","correct":false,"feedback":"This assumes a motivation deficit and adds burden without addressing the removed cue or changed schedule."},{"label":"“That change disrupted something that had worked. Where could lunch fit now, and what storage is actually available?”","correct":true,"feedback":"This reflects disappointment and investigates the environment. Sara can choose a new cue, location, or practical backup rather than being graded on willpower."}]}},{"id":"l16-interactive-5","chapter":"Notice when monitoring becomes harmful","title":"Notice when monitoring becomes harmful","teach":["Monitoring is useful only if it informs a decision. A daily check mark may answer whether a routine happened. A short note about the barrier may explain why it did not. Detailed tracking of every food, symptom, and emotion may be unnecessary and can become intrusive.","Agree what will be observed, how often, who will see it, and when it will stop or change. Ask whether monitoring has caused distress in the past. If it increases preoccupation or shame, reassess rather than insisting that more data are always better. Use feedback descriptively. “Lunch happened on the two days when the food was already at work” is more useful than “You were only fifty percent compliant.” The descriptive version suggests an environmental solution."],"act":{"type":"choice","prompt":"Eli says, “The diary makes me anxious. I avoid foods I cannot record precisely.” What should happen next?","options":[{"label":"Take the concern seriously, reassess the diary, and arrange appropriately qualified support for concerning distress or restriction.","correct":true,"feedback":"The tool should serve the person, not become the goal. Stay within your role, consider a lower-burden alternative if appropriate, and coordinate care with consent."},{"label":"Diagnose an eating disorder and begin psychotherapy yourself.","correct":false,"feedback":"Recognizing a concern does not authorize diagnosis or psychological treatment. Explain your limits and use an appropriate referral pathway."},{"label":"Praise the precision and add more tracking fields.","correct":false,"feedback":"Increasing restriction and distress should not be treated as dedication. More data are not automatically safer or more useful."}]}},{"id":"l16-interactive-6","chapter":"Rehearse a difficult-day recovery","title":"Rehearse a difficult-day recovery","teach":["A lapse is a departure from a chosen plan, not evidence of a defective character. Avoid interpreting one difficult day as proof that nothing has changed. Equally, do not dismiss a recurring difficulty with empty reassurance. Investigate the pattern. An original recovery sequence is notice, understand, adjust, reconnect.","Notice what happened without moral labels. Understand the circumstances and the person's response. Adjust the plan or support. Reconnect with the chosen next step or relevant professional help. This is a study sequence, not a validated clinical relapse-prevention treatment. Use an if–then backup: “If the shift changes and I cannot shop, then I will use the agreed cupboard option.” A backup should be realistic and safe."],"act":{"type":"explore","prompt":"The chosen shopping trip falls through. Predict which backup supports learning rather than punishment, then compare the three paths.","panels":[{"label":"Punish the lapse","text":"“Skip the next meal to make up for it.” A backup should not introduce compensatory restriction or an increasingly rigid set of rules."},{"label":"Ignore the pattern","text":"“It does not matter; just try harder next time.” Empty reassurance misses repeated barriers and does not help the person make a workable decision."},{"label":"Notice, understand, adjust, reconnect","text":"Describe what happened, ask what changed, choose a realistic backup or pause, and reconnect with support. This is an original study sequence, not a clinical relapse-prevention treatment."}]}}],"flashcards":[],"quiz":[]},{"n":17,"title":"Professional Development","kicker":"Turn learning into observable, ethical practice improvement • Supplementary learning, not the official chapter or assessment.","perStepChapter":true,"steps":[{"id":"l17-interactive-1","chapter":"Separate attendance from improvement","title":"Separate attendance from improvement","teach":["Professional development is the ongoing work of keeping knowledge, skills, judgment, and conduct fit for the role you actually perform. Reading a new article can help, but development is incomplete if nothing changes in how you assess information, communicate, document, or seek help. Distinguish attendance, learning, and practice improvement. Attendance means being present at an activity.","Learning means acquiring or revising understanding or a skill. Practice improvement means applying that learning in a way that can be observed or evaluated. A certificate usually establishes attendance or completion, not universal competence. An original example: attending a communication workshop is an activity; recognizing that you interrupt clients is learning; deliberately leaving pauses and obtaining feedback is a practice change."],"act":{"type":"sort","prompt":"Classify the strongest evidence each statement actually provides.","categories":["Attendance","Learning","Practice improvement"],"items":[{"label":"“I completed a communication webinar.”","category":0,"feedback":"Completion documents an activity, not automatically competence or a change in practice."},{"label":"“I can explain why I interrupt when I rush into advice.”","category":1,"feedback":"This shows revised understanding; it does not yet demonstrate a changed interaction."},{"label":"“In supervised role-plays I paused and invited correction; feedback showed fewer missed priorities.”","category":2,"feedback":"This links application with observed feedback rather than relying only on a certificate."},{"label":"“My portfolio lists ten courses.”","category":0,"feedback":"A course list records participation. Add what changed and how you reviewed it."}]}},{"id":"l17-interactive-2","chapter":"State a useful boundary","title":"State a useful boundary","teach":["Before offering a service, identify what your education, experience, supervision, employer policies, and applicable legal requirements permit. A course title or personal interest does not by itself authorize diagnosis, prescribing, psychotherapy, or a regulated professional title.","Verify uncertain requirements through the relevant official regulator or authority rather than relying on promotional material. The UK HCPC standards require its registrants to work within their knowledge and skills, maintain relevant development, and refer when needs exceed their scope. These are cited as an example of a professional regulatory framework, not as rules automatically applying to every reader."],"act":{"type":"choice","prompt":"A client asks, “Can you tell me the medical cause of this symptom?” Choose your response as a trainee nutrition counsellor.","options":[{"label":"“This course lets me diagnose anything related to food.”","correct":false,"feedback":"A course title does not authorize diagnosis or regulated practice. Verify actual qualifications, supervision, and applicable requirements."},{"label":"“I can support practical eating routines, but cannot determine the medical cause. Let’s identify the appropriate professional for that question.”","correct":true,"feedback":"This explains the boundary while preserving useful support. Referral is a responsible next step, not an admission that the person should be abandoned."},{"label":"“Professional standards are identical everywhere, so I already know the legal answer.”","correct":false,"feedback":"Requirements depend on location, profession, registration, and setting. Illustrative UK standards do not establish Ontario rules or your eligibility to practise."}]}},{"id":"l17-interactive-3","chapter":"Find the real learning gap","title":"Find the real learning gap","teach":["“I need to learn more about nutrition” is too broad to guide development. Identify a situation, the decision involved, and the knowledge or skill gap. For example: “How can I explain uncertainty in supplement claims without either endorsing them or dismissing the client's experience?” Separate questions about effectiveness from questions about communication or service delivery.","A clinical intervention question may need research evidence and qualified interpretation. A communication question may benefit from observed practice and feedback. A documentation question may require your organization's policy, not a research paper. Write what you currently think, why you think it, and what evidence would change your mind."],"act":{"type":"explore","prompt":"Noor gave meal-variety advice while the client repeatedly raised cost. Predict which development activity addresses the gap before opening each panel.","panels":[{"label":"More facts about food groups","text":"This may increase knowledge but does not directly address missed priorities. Choose learning based on the decision that went wrong, not the easiest course to find."},{"label":"Agenda-setting role-play with feedback","text":"Practise an opening priority question, summarize before advising, and ask an observer where the client’s concern was missed. This targets the communication gap."},{"label":"A vague promise to “be better”","text":"This gives no observable change or review. State a focused gap, a safe application, and the evidence that would show improvement."}]}},{"id":"l17-interactive-4","chapter":"Look past the impressive headline","title":"Look past the impressive headline","teach":["Before using a study, identify its question, design, participants, comparison, outcomes, duration, and limitations. NIH explains that different clinical study designs have different strengths and weaknesses; well-designed randomized trials can help evaluate causal effects, while not every question can be addressed that way. An association is not automatically a cause.","People choosing a particular food may differ in many other ways. A laboratory mechanism is not proof of a meaningful benefit in everyday life. A change in a biomarker is not necessarily equivalent to feeling better, avoiding disease, or living longer. Look for what was actually measured rather than the outcome suggested by the headline."],"act":{"type":"choice","prompt":"A webinar promises a supplement will “transform energy.” It cites a small biomarker study and offers sales commission. What is the sound next step?","options":[{"label":"Declare the study false solely because a commission is offered.","correct":false,"feedback":"A conflict deserves scrutiny and disclosure, but does not by itself prove a claim false. Evaluate the evidence and do not let sales incentives determine advice."},{"label":"Recommend it because the presenter has a polished slide deck.","correct":false,"feedback":"Presentation quality and attendance certificates do not establish clinical benefit or suitability for an individual client."},{"label":"Examine participants, comparison, outcomes, duration, harms, and independent evidence; record uncertainty and seek qualified input where needed.","correct":true,"feedback":"This checks what was actually measured instead of accepting a broad promise. A biomarker change is not automatically an everyday benefit, and commercial interests deserve attention."}]}},{"id":"l17-interactive-5","chapter":"Make records useful and safe","title":"Make records useful and safe","teach":["Documentation should allow an authorized reader to understand what happened, what was agreed, and what needs follow-up. Separate reported information from observations and interpretations. Avoid judgmental labels, unsupported diagnoses, and claims of consent that did not occur.","HCPC's recordkeeping standards for its registrants emphasize clear, accurate, prompt, and secure records. These are useful principles, while specific retention, access, correction, and disclosure requirements must be checked in the reader's own setting. An original note contrast: “Noncompliant again” gives little actionable information. “Client reports the planned food was unavailable during three shifts; chose to explore a workplace storage option” identifies the problem and decision."],"act":{"type":"sort","prompt":"Decide whether each note or action supports a clear record or needs correction.","categories":["Useful documentation","Needs correction"],"items":[{"label":"“Client reports food unavailable during three shifts; chose to explore storage.”","category":0,"feedback":"This separates the report from the decision and describes a practical barrier."},{"label":"“Noncompliant again.”","category":1,"feedback":"A judgmental label omits the circumstances and provides little continuity of care."},{"label":"Paste a distinctive client story into a personal learning tool after removing the name.","category":1,"feedback":"Removing a name may not prevent identification. Use approved systems and proper authorization and safeguards."},{"label":"Document options discussed separately from the action actually agreed.","category":0,"feedback":"This prevents an offered suggestion from being misrepresented as consent."}]}},{"id":"l17-interactive-6","chapter":"Respond to an error without hiding it","title":"Respond to an error without hiding it","teach":["Be clear about appointment arrangements, communication channels, response times, fees where relevant, and the limits of your availability. Warmth does not require becoming a friend, exchanging personal favours, or providing unlimited access. Consider how power and trust affect decisions about gifts, social media, or personal relationships.","If you discover an error, prioritize safety, obtain appropriate guidance, and follow the setting's disclosure and incident procedures. Do not conceal it, fabricate a record, or reassure beyond what is known. Learning from an error includes examining the system that allowed it, not only blaming an individual. Professional development also includes recognizing fatigue, overload, and situations in which you need support."],"act":{"type":"choice","prompt":"You notice an inaccurate note after a supervised session. What is the strongest response?","options":[{"label":"Silently overwrite it so no one can see the mistake.","correct":false,"feedback":"Concealment undermines an accurate record. Follow the setting’s correction and incident procedures rather than hiding the original error."},{"label":"Prioritize any safety issue, seek appropriate guidance, and correct the record through the approved process.","correct":true,"feedback":"This combines immediate responsibility with transparent learning. Review what allowed the error so the improvement addresses the system as well as your own practice."},{"label":"Promise the client there could not be any consequence before checking.","correct":false,"feedback":"Do not reassure beyond what is known. Obtain appropriate guidance and follow applicable disclosure procedures."}]}}],"flashcards":[],"quiz":[]}]};
